INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「植える」の目的語「種」を示す。"}, {"text": "が", "is_correct": false, "explanation": "「種が植える」では種が動作主になり誤り。"}, {"text": "に", "is_correct": false, "explanation": "「種に植える」は植える物を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では植える物を示せない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「植える」の目的語「種」を示す。", "が": "「種が植える」では種が動作主になり誤り。", "に": "「種に植える」は植える物を示せない。", "で": "手段の「で」では植える物を示せない。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抜く", "is_correct": true, "explanation": "植えた植物を土から取り出すことで、植えるの反対。"}, {"text": "耕す", "is_correct": false, "explanation": "植える前に土を掘り返すことで、反対ではない。"}, {"text": "育てる", "is_correct": false, "explanation": "植えた後の世話で、反対ではない。"}, {"text": "埋める", "is_correct": false, "explanation": "土に入れる点で近く、反対ではない。"}], "correct_answer": "抜く", "explanations": {"抜く": "植えた植物を土から取り出すことで、植えるの反対。", "耕す": "植える前に土を掘り返すことで、反対ではない。", "育てる": "植えた後の世話で、反対ではない。", "埋める": "土に入れる点で近く、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "植える", "is_correct": true, "explanation": "正解：「うえる」と読む対象語。"}, {"text": "売れる", "is_correct": false, "explanation": "「うれる」と読む。二モーラ目「え」が「れ」に変わる。"}, {"text": "増える", "is_correct": false, "explanation": "「ふえる」と読む。一モーラ目「う」が「ふ」に変わる。"}, {"text": "生える", "is_correct": false, "explanation": "「はえる」と読む。一モーラ目「う」が「は」に変わる。"}, {"text": "冷える", "is_correct": false, "explanation": "「ひえる」と読む。一モーラ目「う」が「ひ」に変わる。"}], "explanations": {"植える": "正解：「うえる」と読む対象語。", "売れる": "「うれる」と読む。二モーラ目「え」が「れ」に変わる。", "増える": "「ふえる」と読む。一モーラ目「う」が「ふ」に変わる。", "生える": "「はえる」と読む。一モーラ目「う」が「は」に変わる。", "冷える": "「ひえる」と読む。一モーラ目「う」が「ひ」に変わる。"}, "sentence_index": null, "correct_answer": "植える"}, "level_3": {"options": [{"text": "植え", "is_correct": true, "explanation": "父が木を土に入れたので「植えた」。"}, {"text": "見え", "is_correct": false, "explanation": "項構造：「父が見えた」では木を植えた意味にならない。"}, {"text": "生え", "is_correct": false, "explanation": "項構造：「生える」は自動詞で「父が」と合わない。"}, {"text": "枯れ", "is_correct": false, "explanation": "意味：父が枯れたのではない。"}], "explanations": {"植え": "父が木を土に入れたので「植えた」。", "見え": "項構造：「父が見えた」では木を植えた意味にならない。", "生え": "項構造：「生える」は自動詞で「父が」と合わない。", "枯れ": "意味：父が枯れたのではない。"}, "sentence_index": 6, "correct_answer": "植え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鉢を植えた種から芽が出た。", "explanation": "助詞の混同：植える場所は「を」ではなく「に」で示す。"}, {"text": "鉢に植えった種から芽が出た。", "explanation": "活用の誤り：一段動詞「植える」のた形は「植えた」で、促音は入らない。"}, {"text": "芽が出た鉢に種から植えた。", "explanation": "語順・係り受けの誤り：因果関係が崩れ意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この木は十年前に父を植えたものだ。", "corrected_sentence": "この木は十年前に父が植えたものだ。", "error_description": "植えた人（動作主）は「を」ではなく「が」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "植える", "is_correct": true, "explanation": "名詞「時期」を修飾する連体形。"}, {"text": "植えよう", "is_correct": false, "explanation": "意向形は名詞を直接修飾できない。"}, {"text": "植えます", "is_correct": false, "explanation": "丁寧形は通常名詞を修飾しない。"}, {"text": "植えなさい", "is_correct": false, "explanation": "命令の形は名詞を修飾できない。"}], "correct_form": "植える", "base_form": "植える", "form_label": "連体形（辞書形）", "sentence_index": 7, "explanations": {"植える": "名詞「時期」を修飾する連体形。", "植えよう": "意向形は名詞を直接修飾できない。", "植えます": "丁寧形は通常名詞を修飾しない。", "植えなさい": "命令の形は名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39227, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「植える」の目的語「トマト」を示す。"}, {"text": "に", "is_correct": false, "explanation": "「トマトに植える」では植える物を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」は目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「植える」の目的語「トマト」を示す。", "に": "「トマトに植える」では植える物を示せない。", "で": "手段・場所の「で」は目的語にならない。", "へ": "方向を表し、目的語にならない。"}, "error_tags": {"に": "location_vs_target", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "引き抜く", "is_correct": true, "explanation": "土に植わったものを引っぱって取り出すことで、植えるの反対。"}, {"text": "撒く", "is_correct": false, "explanation": "種を散らすことで、反対ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移すことで、反対関係にない。"}, {"text": "掘る", "is_correct": false, "explanation": "土に穴をあけることで、反対ではない。"}], "correct_answer": "引き抜く", "explanations": {"引き抜く": "土に植わったものを引っぱって取り出すことで、植えるの反対。", "撒く": "種を散らすことで、反対ではない。", "運ぶ": "物を移すことで、反対関係にない。", "掘る": "土に穴をあけることで、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伝わる", "is_correct": true, "explanation": "正解：「つたわる」と読む対象語。"}, {"text": "いたわる", "is_correct": false, "explanation": "「いたわる」と読む。一モーラ目「つ」が「い」に変わる。労る：大切に扱うこと。"}, {"text": "伝える", "is_correct": false, "explanation": "「つたえる」と読む。三モーラ目「わ」が「え」に変わる。他動詞の別語。"}, {"text": "こだわる", "is_correct": false, "explanation": "「こだわる」と読む。「つ」が「こ」、「た」が「だ」に変わる近い音。"}], "explanations": {"伝わる": "正解：「つたわる」と読む対象語。", "いたわる": "「いたわる」と読む。一モーラ目「つ」が「い」に変わる。労る：大切に扱うこと。", "伝える": "「つたえる」と読む。三モーラ目「わ」が「え」に変わる。他動詞の別語。", "こだわる": "「こだわる」と読む。「つ」が「こ」、「た」が「だ」に変わる近い音。"}, "sentence_index": null, "correct_answer": "伝わる"}, "level_3": {"options": [{"text": "伝わっ", "is_correct": true, "explanation": "水が根の網目まで移って届いていくので「伝わっていく」。"}, {"text": "座っ", "is_correct": false, "explanation": "意味：水が座ることはない。"}, {"text": "習っ", "is_correct": false, "explanation": "項構造：「習う」は対象を必要とし、水は習わない。"}, {"text": "怒っ", "is_correct": false, "explanation": "意味：水が怒るのは不自然。"}], "explanations": {"伝わっ": "水が根の網目まで移って届いていくので「伝わっていく」。", "座っ": "意味：水が座ることはない。", "習っ": "項構造：「習う」は対象を必要とし、水は習わない。", "怒っ": "意味：水が怒るのは不自然。"}, "sentence_index": 0, "correct_answer": "伝わっ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このお祭りは昔から村を伝わっている。", "explanation": "助詞の混同：伝わる先は「を」ではなく「に」で示す。"}, {"text": "このお祭りは昔から村に伝わりている。", "explanation": "活用の誤り：「ている」はて形に付くので「伝わっている」とする。"}, {"text": "村に昔からこのお祭りは伝わってある。", "explanation": "アスペクトの誤り：「てある」は自動詞「伝わる」に付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の気持ちがみんなを伝わった。", "corrected_sentence": "彼の気持ちがみんなに伝わった。", "error_description": "伝わる相手は「を」ではなく「に」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "伝わる", "is_correct": true, "explanation": "名詞「生地の…」を修飾し、今伝わってくる感覚を表す。"}, {"text": "伝われ", "is_correct": false, "explanation": "命令形は名詞を修飾できない。"}, {"text": "伝わろう", "is_correct": false, "explanation": "意向形は名詞を修飾できない。"}, {"text": "伝わって", "is_correct": false, "explanation": "て形は名詞に直接かからない。"}], "correct_form": "伝わる", "base_form": "伝わる", "form_label": "連体形（辞書形）", "sentence_index": 1, "explanations": {"伝わる": "名詞「生地の…」を修飾し、今伝わってくる感覚を表す。", "伝われ": "命令形は名詞を修飾できない。", "伝わろう": "意向形は名詞を修飾できない。", "伝わって": "て形は名詞に直接かからない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「〜を通じて」の形で経由するものを示す。"}, {"text": "が", "is_correct": false, "explanation": "「指先が通じて」では経由の意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手の「と」は経由を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点の「より」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「〜を通じて」の形で経由するものを示す。", "が": "「指先が通じて」では経由の意味にならない。", "と": "並列・相手の「と」は経由を示せない。", "より": "比較・起点の「より」は不自然。"}, "error_tags": {"が": "object_marking", "と": "other", "より": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "伝わる", "is_correct": true, "explanation": "正解：「つたわる」と読む対象語。"}, {"text": "伝える", "is_correct": false, "explanation": "「つたえる」と読む。三モーラ目「わ」が「え」に変わる。他動詞の別語。"}, {"text": "かかわる", "is_correct": false, "explanation": "「かかわる」と読む。関わる：関係をもつこと。一・二モーラ目が異なる近い音。"}, {"text": "くわわる", "is_correct": false, "explanation": "「くわわる」と読む。加わる：仲間に入ること。一・二モーラ目が異なる近い音。"}], "explanations": {"伝わる": "正解：「つたわる」と読む対象語。", "伝える": "「つたえる」と読む。三モーラ目「わ」が「え」に変わる。他動詞の別語。", "かかわる": "「かかわる」と読む。関わる：関係をもつこと。一・二モーラ目が異なる近い音。", "くわわる": "「くわわる」と読む。加わる：仲間に入ること。一・二モーラ目が異なる近い音。"}, "sentence_index": null, "correct_answer": "伝わる"}, "level_3": {"options": [{"text": "伝わっ", "is_correct": true, "explanation": "振動が床を通して届くので「伝わってくる」。"}, {"text": "太っ", "is_correct": false, "explanation": "意味：振動が太るのは不自然。"}, {"text": "謝っ", "is_correct": false, "explanation": "意味：振動は謝らない。"}, {"text": "笑っ", "is_correct": false, "explanation": "意味：振動は笑わない。"}], "explanations": {"伝わっ": "振動が床を通して届くので「伝わってくる」。", "太っ": "意味：振動が太るのは不自然。", "謝っ": "意味：振動は謝らない。", "笑っ": "意味：振動は笑わない。"}, "sentence_index": 6, "correct_answer": "伝わっ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手紙で感謝を伝わるといいな。", "explanation": "助詞の混同：自動詞「伝わる」の主語は「が」で示す。"}, {"text": "手紙で感謝が伝わっるといいな。", "explanation": "活用の誤り：辞書形は「伝わる」で、促音は入らない。"}, {"text": "感謝が手紙で伝わってあるといいな。", "explanation": "アスペクトの誤り：「てある」は自動詞に付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_