INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35159, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "音は空気を通して伝える。", "corrected_sentence": "音は空気を通して伝わる。", "error_description": "音が主語の自動詞文なので、他動詞「伝える」ではなく「伝わる」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "伝わる", "is_correct": true, "explanation": "一般的な事実を述べる文末の辞書形。"}, {"text": "伝わり", "is_correct": false, "explanation": "連用形だけでは文が終わらない。"}, {"text": "伝われば", "is_correct": false, "explanation": "仮定形では文が完結しない。"}, {"text": "伝わりながら", "is_correct": false, "explanation": "「ながら」の形では文が終わらない。"}], "correct_form": "伝わる", "base_form": "伝わる", "form_label": "辞書形（終止形）", "sentence_index": 7, "explanations": {"伝わる": "一般的な事実を述べる文末の辞書形。", "伝わり": "連用形だけでは文が終わらない。", "伝われば": "仮定形では文が完結しない。", "伝わりながら": "「ながら」の形では文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
