INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52568, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "崇高", "is_correct": true, "explanation": "正解：「すうこう」と読む対象語。"}, {"text": "遂行", "is_correct": false, "explanation": "「すいこう」と読む。二モーラ目「う」が「い」に変わる。"}, {"text": "空港", "is_correct": false, "explanation": "「くうこう」と読む。一モーラ目「す」が「く」に変わる。"}, {"text": "通行", "is_correct": false, "explanation": "「つうこう」と読む。一モーラ目「す」が「つ」に変わる。"}, {"text": "走行", "is_correct": false, "explanation": "「そうこう」と読む。一モーラ目「す」が「そ」に変わる。"}], "explanations": {"崇高": "正解：「すうこう」と読む対象語。", "遂行": "「すいこう」と読む。二モーラ目「う」が「い」に変わる。", "空港": "「くうこう」と読む。一モーラ目「す」が「く」に変わる。", "通行": "「つうこう」と読む。一モーラ目「す」が「つ」に変わる。", "走行": "「そうこう」と読む。一モーラ目「す」が「そ」に変わる。"}, "sentence_index": null, "correct_answer": "崇高"}, "level_3": {"options": [{"text": "崇高", "is_correct": true, "explanation": "生命への祈りに似た気高い儀式なので「崇高な」。"}, {"text": "便利", "is_correct": false, "explanation": "意味：儀式の気高さを表さない。"}, {"text": "安価", "is_correct": false, "explanation": "意味：値段の話で文脈に合わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "連語：儀式を「新鮮な」と形容するのは不自然。"}], "explanations": {"崇高": "生命への祈りに似た気高い儀式なので「崇高な」。", "便利": "意味：儀式の気高さを表さない。", "安価": "意味：値段の話で文脈に合わない。", "新鮮": "連語：儀式を「新鮮な」と形容するのは不自然。"}, "sentence_index": 0, "correct_answer": "崇高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜明けの山は崇高の美しさに満ちていた。", "explanation": "活用の誤り：形状詞は名詞を修飾するとき「の」ではなく「な」を使う。"}, {"text": "夜明けの山を崇高な美しさに満ちていた。", "explanation": "助詞の混同：主題は「を」ではなく「は」で示す。"}, {"text": "夜明けの山は崇高だ美しさに満ちていた。", "explanation": "活用の誤り：名詞を修飾するときは「崇高だ」ではなく「崇高な」とする。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52568, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は人を助けるという崇高い目標を持っている。", "corrected_sentence": "彼は人を助けるという崇高な目標を持っている。", "error_description": "「崇高」は形状詞なので「崇高い」ではなく「崇高な」とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "崇高", "is_correct": true, "explanation": "形状詞は語幹に「な」を付けて名詞を修飾する。"}, {"text": "崇高さ", "is_correct": false, "explanation": "名詞形で、後に「な」は続かない。"}, {"text": "崇高だ", "is_correct": false, "explanation": "終止形で、後に「な」は続かない。"}, {"text": "崇高に", "is_correct": false, "explanation": "連用形で、後に「な」は続かない。"}], "correct_form": "崇高", "base_form": "崇高", "form_label": "語幹（な接続）", "sentence_index": 1, "explanations": {"崇高": "形状詞は語幹に「な」を付けて名詞を修飾する。", "崇高さ": "名詞形で、後に「な」は続かない。", "崇高だ": "終止形で、後に「な」は続かない。", "崇高に": "連用形で、後に「な」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476c651-3a8f-4089-b861-10a4174c0ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
