INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52692, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "すぐれた人や大きな自然などを、深く敬いおそれる気持ち。", "primary_collocate": null, "pronunciation": "いけい", "ipa": "ikeː", "syllable_count": 3, "sentences": [{"text": "彼は畏敬の念にも似た慎ましやかな所作で、乾いた土の表面へとそれを静かに注ぎ下ろす。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "その姿を凝視する子供の瞳には、生命が持つ根源的な逞しさへの畏敬の念が宿っている。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "山の大きさに畏敬を感じた。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "やま おお いけい かん", "sentence_source": "generated"}, {"text": "彼は先生に畏敬の念を持つ。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "かれ せんせい いけい ねん も", "sentence_source": "generated"}, {"text": "自然への畏敬を忘れない。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "しぜん いけい わす", "sentence_source": "generated"}, {"text": "畏敬の気持ちで海を見た。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "いけい きも うみ み", "sentence_source": "generated"}, {"text": "人々は王に畏敬を抱いていた。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "ひとびと おう いけい いだ", "sentence_source": "generated"}, {"text": "古い神社に畏敬を覚える。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "ふる じんじゃ いけい おぼ", "sentence_source": "generated"}, {"text": "命への畏敬が大切だ。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "いのち いけい たいせつ", "sentence_source": "generated"}, {"text": "星空に畏敬の念がわいた。", "target_word": "畏敬", "complexity_tier": "T3", "furigana": "ほしぞら いけい ねん", "sentence_source": "generated"}], "morphological_forms": [{"form": "畏敬する", "label": "派生"}, {"form": "畏敬の念", "label": "派生"}, {"form": "畏敬すべき", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 深く敬いおそれる気持ち", "collocate_grounding": {"status": "no_source", "reason": "no colloc