INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52702, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水分がなくなり、かわいた状態になること。", "primary_collocate": null, "pronunciation": "かわく", "ipa": "kawakɯ", "syllable_count": 3, "sentences": [{"text": "彼は畏敬の念にも似た慎ましやかな所作で、乾いた土の表面へとそれを静かに注ぎ下ろす。", "target_word": "乾い", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "深紅とも、あるいは乾いた血の色とも形容すべきそのブーツは、もはや単なる履物という枠組みを超え、私の内面に潜む情動を可視化する媒体となっているのだ。\n\n指先でなぞる革の質感は、過ぎ去りし季節の冷たさと、それに抗った熱気を同時に記憶している。", "target_word": "乾い", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "洗濯物がもう乾いた。", "target_word": "乾い", "complexity_tier": "T3", "furigana": "せんたくもの かわ", "sentence_source": "generated"}, {"text": "雨の後、道が乾いていく。", "target_word": "乾い", "complexity_tier": "T3", "furigana": "あめ あと みち かわ", "sentence_source": "generated"}, {"text": "乾いたタオルで手をふく。", "target_word": "乾い", "complexity_tier": "T3", "furigana": "かわ て", "sentence_source": "generated"}, {"text": "このシャツはすぐ乾く。", "target_word": "乾く", "complexity_tier": "T3", "furigana": "かわ", "sentence_source": "generated"}, {"text": "冬は空気が乾いている。", "target_word": "乾い", "complexity_tier": "T3", "furigana": "ふゆ くうき かわ", "sentence_source": "generated"}, {"text": "ペンキがまだ乾かない。", "target_word": "乾か", "complexity_tier": "T3", "furigana": "かわ", "sentence_source": "generated"}, {"text": "乾いた土に水をまいた。", "target_word": "乾い", "complexity_tier": "T3", "furigana": "かわ つち みず", "sentence_source": "generated"}, {"text": "髪が乾くまで待っている。", "target_word": "乾く", "complexity_tier": "T3", "furigana": "かみ かわ ま", "sentence_source": "generated"}], "morphological_forms": [{"form": "乾いた", "label": "活用"}, {"form": "乾いて", "label": "活用"}, {"form": "乾かない", "label": "活用"}, {"form": "乾かす", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 水分がなくなってかわく", "collocate_grounding"