INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38353, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "命", "is_correct": true, "explanation": "聞こえた音と同じ語。"}, {"text": "祈り", "is_correct": false, "explanation": "いのりと読み、一拍だけ違う別の語。"}, {"text": "異能", "is_correct": false, "explanation": "いのうと読み、一拍だけ違う別の語。"}, {"text": "亥の子", "is_correct": false, "explanation": "いのこと読み、一拍だけ違う別の語。"}], "explanations": {"命": "聞こえた音と同じ語。", "祈り": "いのりと読み、一拍だけ違う別の語。", "異能": "いのうと読み、一拍だけ違う別の語。", "亥の子": "いのこと読み、一拍だけ違う別の語。"}, "sentence_index": null, "correct_answer": "命"}, "level_3": {"options": [{"text": "命", "is_correct": true, "explanation": "鉢の中の植物の「命」が水を糧に育つ。"}, {"text": "机", "is_correct": false, "explanation": "意味：机は水を糧にして緑を深めない。"}, {"text": "石", "is_correct": false, "explanation": "意味：石は生きておらず緑を深めない。"}, {"text": "窓", "is_correct": false, "explanation": "意味：窓は水を糧に育たない。"}], "explanations": {"命": "鉢の中の植物の「命」が水を糧に育つ。", "机": "意味：机は水を糧にして緑を深めない。", "石": "意味：石は生きておらず緑を深めない。", "窓": "意味：窓は水を糧に育たない。"}, "sentence_index": 0, "correct_answer": "命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "命をとても大切なものです。", "explanation": "助詞の混同：主題は「は」で示す。"}, {"text": "一枚の命を守った。", "explanation": "助数詞の誤り：命は「枚」で数えない。"}, {"text": "命は明日とても大切だった。", "explanation": "活用・アスペクトの誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0959fac-857a-4d2a-b53d-604a635235f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
