INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38353, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置で文法的に正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「模倣が超え」では超える対象が示せない。"}, {"text": "に", "is_correct": false, "explanation": "「模倣に超え」は非文。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、この位置では非文。"}], "correct_answer": "を", "explanations": {"を": "この位置で文法的に正しい助詞。", "が": "「模倣が超え」では超える対象が示せない。", "に": "「模倣に超え」は非文。", "で": "手段・場所を表し、この位置では非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死", "is_correct": true, "explanation": "命（生きていること）の反対は死。"}, {"text": "心", "is_correct": false, "explanation": "命と対の関係ではない。"}, {"text": "体", "is_correct": false, "explanation": "生き物の一部で、命の反対ではない。"}, {"text": "夢", "is_correct": false, "explanation": "命とは関係が対にならない。"}], "correct_answer": "死", "explanations": {"死": "命（生きていること）の反対は死。", "心": "命と対の関係ではない。", "体": "生き物の一部で、命の反対ではない。", "夢": "命とは関係が対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0959fac-857a-4d2a-b53d-604a635235f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
