INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52716, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "注意して見るべきものを、うっかり見のがすこと。", "primary_collocate": null, "pronunciation": "みおとす", "ipa": "mi.o.to.sɯ", "syllable_count": 4, "sentences": [{"text": "我々成人が往々にして見落とす、静謐なる成長の過程を、彼はただ純粋な慈愛をもって見守っているのだ。", "target_word": "見落とす", "complexity_tier": "T3", "furigana": "みおとす", "sentence_source": "mined"}, {"text": "我々大人が往々にして見落とす微小な営みを、彼は無心に、そして厳粛に刻み続けているのである。", "target_word": "見落とす", "complexity_tier": "T3", "furigana": "みおとす", "sentence_source": "mined"}, {"text": "テストで大事な問題を見落とした。", "target_word": "見落とし", "complexity_tier": "T3", "furigana": "みおと", "sentence_source": "generated"}, {"text": "小さなミスを見落とさないでください。", "target_word": "見落とさ", "complexity_tier": "T3", "furigana": "みおと", "sentence_source": "generated"}, {"text": "見落としていた文字に後で気づいた。", "target_word": "見落とし", "complexity_tier": "T3", "furigana": "みおと", "sentence_source": "generated"}, {"text": "彼はいつも細かい点を見落とす。", "target_word": "見落とす", "complexity_tier": "T3", "furigana": "みおとす", "sentence_source": "generated"}, {"text": "見落とした看板を探しに戻った。", "target_word": "見落とし", "complexity_tier": "T3", "furigana": "みおと", "sentence_source": "generated"}, {"text": "地図の小さな道を見落としてしまった。", "target_word": "見落とし", "complexity_tier": "T3", "furigana": "みおと", "sentence_source": "generated"}, {"text": "先生は誰のミスも見落とさない。", "target_word": "見落とさ", "complexity_tier": "T3", "furigana": "みおと", "sentence_source": "generated"}, {"text": "注意しないと大切なことを見落とす。", "target_word": "見落とす", "complexity_tier": "T3", "furigana": "みおとす", "sentence_source": "generated"}], "morphological_forms": [{"form": "見落とした", "label": "活用"}, {"form": "見落として", "label": "活用"}, {"form": "見落とさない", "label": "活用"}, {"form": "見落とし", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 大事なものをうっかり見のがす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81c1f2e-7701-48c2-bb01-7ceb0dc6f48b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37877, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "刃物で細かく切ったり彫ったりすること。また、心や記憶に強く残すこと。", "primary_collocate": null, "pronunciation": "きざむ", "ipa": "ki.za.mɯ", "syllable_count": 3, "sentences": [{"text": "童子の行為は、単なる日常的な営みの模倣を超え、生命の循環に対する原初的な祈りにも似た、崇高な儀式としてそこに刻まれるのである。", "target_word": "刻ま", "complexity_tier": "T3", "furigana": "きざ", "sentence_source": "mined"}, {"text": "我々大人が往々にして見落とす微小な営みを、彼は無心に、そして厳粛に刻み続けているのである。", "target_word": "刻み", "complexity_tier": "T3", "furigana": "きざ", "sentence_source": "mined"}, {"text": "母がねぎを細かく刻んでいる。", "target_word": "刻ん", "complexity_tier": "T3", "furigana": "きざ", "sentence_source": "generated"}, {"text": "木に自分の名前を刻んだ。", "target_word": "刻ん", "complexity_tier": "T3", "furigana": "きざ", "sentence_source": "generated"}, {"text": "その言葉を心に刻む。", "target_word": "刻む", "complexity_tier": "T3", "furigana": "きざむ", "sentence_source": "generated"}, {"text": "石に刻まれた文字は古い。", "target_word": "刻ま", "complexity_tier": "T3", "furigana": "きざ", "sentence_source": "generated"}, {"text": "玉ねぎを刻むと涙が出る。", "target_word": "刻む", "complexity_tier": "T3", "furigana": "きざむ", "sentence_source": "generated"}, {"text": "あの日の思い出は胸に刻まれている。", "target_word": "刻ま", "complexity_tier": "T3", "furigana": "きざ", "sentence_source": "generated"}, {"text": "父は包丁で野菜を刻んだ。", "target_word": "刻ん", "complexity_tier": "T3", "furigana": "きざ", "sentence_source": "generated"}, {"text": "記念碑に名前を刻む。", "target_word": "刻む", "complexity_tier": "T3", "furigana": "きざむ", "sentence_source": "generated"}], "morphological_forms": [{"form": "刻んだ", "label": "活用"}, {"form": "刻んで", "label": "活用"}, {"form": "刻まれる", "label": "活用"}, {"form": "刻み", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 細かく切る・彫る・心に残す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81c1f2e-7701-48c2-bb01-7ceb0dc6f48b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52230, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "すべてを同じ形や基準にそろえること。個性をなくして一つの型にはめること。", "primary_collocate": null, "pronunciation": "かくいつ", "ipa": "ka.kɯ.i.tsɯ", "syllable_count": 4, "sentences": [{"text": "現代の高等教育において、画一的な知識伝達モデルはもはやその有効性を維持し得ない。", "target_word": "画一", "complexity_tier": "T3", "furigana": "かくいつ", "sentence_source": "mined"}, {"text": "現代の商業的なベーキングにおいては往々にして画一的な効率性が優先されがちであるが、彼が真に渇望するのは、サワードウ特有の繊細かつ複雑な酸味と、穀物本来が秘める深い旨みの極致である。", "target_word": "画一", "complexity_tier": "T3", "furigana": "かくいつ", "sentence_source": "mined"}, {"text": "画一的な制服に反対する生徒もいる。", "target_word": "画一", "complexity_tier": "T3", "furigana": "かくいつ", "sentence_source": "generated"}, {"text": "町の家がみな画一的に見える。", "target_word": "画一", "complexity_tier": "T3", "furigana": "かくいつ", "sentence_source": "generated"}, {"text": "教育の画一化が問題になっている。", "target_word": "画一", "complexity_tier": "T3", "furigana": "かくいつ", "sentence_source": "generated"}, {"text": "画一的な考え方では新しい物は生まれない。", "target_word": "画一", "complexity_tier": "T3", "furigana": "かくいつ", "sentence_source": "generated"}, {"text": "店の商品が画一化されてきた。", "target_word": "画一", "complexity_tier": "T3", "furigana": "かくいつ", "sentence_source": "generated"}, {"text": "画一を嫌う人は自由な服を着る。", "target_word": "画一", "complexity_tier": "T3", "furigana": "かくいつ", "sentence_source": "generated"}, {"text": "彼は画一的なやり方に疑問を持った。", "target_word": "画一", "complexity_tier": "T3", "furigana": "かくいつ", "sentence_source": "generated"}, {"text": "画一より多様さを大切にしたい。", "target_word": "画一", "complexity_tier": "T3", "furigana": "かくいつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "画一的", "label": "派生"}, {"form": "画一化", "label": "派生"}, {"form": "画一性", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | すべてを同じ型にそろえること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81c1f2e-7701-48c2-bb01-7ceb0dc6f48b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36487, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の筋道を立てた考え。また、ある分野の基本的な理論や学説。", "primary_collocate": null, "pronunciation": "ろん", "ipa": "ɾoɴ", "syllable_count": 2, "sentences": [{"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "論", "complexity_tier": "T3", "furigana": "ろん", "sentence_source": "mined"}, {"text": "企業はブランディングにおいて、色彩理論を巧みに利用している。", "target_word": "論", "complexity_tier": "T3", "furigana": "ろん", "sentence_source": "mined"}, {"text": "色は単なる装飾ではなく、記号論の観点から特定のメッセージを伝える記号として機能するのだ。", "target_word": "論", "complexity_tier": "T3", "furigana": "ろん", "sentence_source": "mined"}, {"text": "彼の論はとても分かりやすい。", "target_word": "論", "complexity_tier": "T3", "furigana": "ろん", "sentence_source": "generated"}, {"text": "その論には少し無理がある。", "target_word": "論", "complexity_tier": "T3", "furigana": "ろん", "sentence_source": "generated"}, {"text": "先生の論を聞いて考えが変わった。", "target_word": "論", "complexity_tier": "T3", "furigana": "ろん", "sentence_source": "generated"}, {"text": "二人の論が正反対だった。", "target_word": "論", "complexity_tier": "T3", "furigana": "ろん", "sentence_source": "generated"}, {"text": "新しい論が学会で話題になった。", "target_word": "論", "complexity_tier": "T3", "furigana": "ろん", "sentence_source": "generated"}, {"text": "この本は教育論について書いている。", "target_word": "論", "complexity_tier": "T3", "furigana": "ろん", "sentence_source": "generated"}, {"text": "彼女は自分の論をはっきり述べた。", "target_word": "論", "complexity_tier": "T3", "furigana": "ろん", "sentence_source": "generated"}], "morphological_forms": [{"form": "理論", "label": "派生"}, {"form": "議論", "label": "派生"}, {"form": "論じる", "label": "派生"}, {"form": "論文", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 筋道立てた考えや理論", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81c1f2e-7701-48c2-bb01-7ceb0dc6f48b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37643, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ほかの物とはちがう、その物だけが持つ性質や特ちょう。", "primary_collocate": null, "pronunciation": "とくせい", "ipa": "to.kɯ.seː", "syllable_count": 4, "sentences": [{"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "特性", "complexity_tier": "T3", "furigana": "とくせい", "sentence_source": "mined"}, {"text": "社会経済現象の真の駆動力は、還元主義的な分析の彼方、ネットワーク全体の創発的特性の内にこそ宿っていると言えよう。", "target_word": "特性", "complexity_tier": "T3", "furigana": "とくせい", "sentence_source": "mined"}, {"text": "この布は水を通さない特性がある。", "target_word": "特性", "complexity_tier": "T3", "furigana": "とくせい", "sentence_source": "generated"}, {"text": "金属の特性を理科で学んだ。", "target_word": "特性", "complexity_tier": "T3", "furigana": "とくせい", "sentence_source": "generated"}, {"text": "特性を生かして仕事を選ぶ。", "target_word": "特性", "complexity_tier": "T3", "furigana": "とくせい", "sentence_source": "generated"}, {"text": "犬の特性は鼻がよいことだ。", "target_word": "特性", "complexity_tier": "T3", "furigana": "とくせい", "sentence_source": "generated"}, {"text": "それぞれの子どもの特性が違う。", "target_word": "特性", "complexity_tier": "T3", "furigana": "とくせい", "sentence_source": "generated"}, {"text": "この木の特性は軽くて強いことだ。", "target_word": "特性", "complexity_tier": "T3", "furigana": "とくせい", "sentence_source": "generated"}, {"text": "材料の特性を調べてから使う。", "target_word": "特性", "complexity_tier": "T3", "furigana": "とくせい", "sentence_source": "generated"}, {"text": "彼は自分の特性をよく知っている。", "target_word": "特性", "complexity_tier": "T3", "furigana": "とくせい", "sentence_source": "generated"}], "morphological_forms": [{"form": "特性値", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | その物だけが持つ性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81c1f2e-7701-48c2-bb01-7ceb0dc6f48b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35753, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の仕組みや、それを実現するための方法や型。", "primary_collocate": null, "pronunciation": "もでる", "ipa": "mo.de.ɾɯ", "syllable_count": 3, "sentences": [{"text": "現代の高等教育において、画一的な知識伝達モデルはもはやその有効性を維持し得ない。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "この会社は新しいモデルで成功した。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "町のごみ集めは他の町のモデルになった。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "このモデルでは天気を予想できない。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "新しい学習モデルを試している。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "その店の売り方がモデルとされた。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "古いモデルを変える時が来た。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "簡単なモデルで仕組みを説明した。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "この計画は地域のモデルになる。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "モデル化", "label": "派生"}, {"form": "モデルケース", "label": "派生"}, {"form": "ビジネスモデル", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事の仕組みや方法の型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 6 words above tier T1 (max 2): サプライ (Zipf 3.19), 文脈 (Zipf 3.63), 個々 (Zipf 3.92), ミクロ (Zipf 3.34), 局所 (Zipf 3.35), 線形 (Zipf 2.97)']::text[], 'f81c1f2e-7701-48c2-bb01-7ceb0dc6f48b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52716, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "見落とす", "is_correct": true, "explanation": "正解。みおとす。"}, {"text": "見下ろす", "is_correct": false, "explanation": "みおろす。「と」が「ろ」に変わる一モーラ差。"}, {"text": "見劣り", "is_correct": false, "explanation": "みおとり。「す」が「り」に変わる一モーラ差。"}, {"text": "射落とす", "is_correct": false, "explanation": "いおとす。「み」が「い」に変わる一モーラ差。"}], "explanations": {"見落とす": "正解。みおとす。", "見下ろす": "みおろす。「と」が「ろ」に変わる一モーラ差。", "見劣り": "みおとり。「す」が「り」に変わる一モーラ差。", "射落とす": "いおとす。「み」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "見落とす"}, "level_3": {"options": [{"text": "見落とす", "is_correct": true, "explanation": "正解。大人が気づかずに見のがすという文意に合う。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "意味：自動詞で「過程」を修飾しても文意が成り立たない。"}, {"text": "食べる", "is_correct": false, "explanation": "意味：過程を食べることはできない。"}, {"text": "売る", "is_correct": false, "explanation": "連語：「過程を売る」は不自然。"}], "explanations": {"見落とす": "正解。大人が気づかずに見のがすという文意に合う。", "泳ぐ": "意味：自動詞で「過程」を修飾しても文意が成り立たない。", "食べる": "意味：過程を食べることはできない。", "売る": "連語：「過程を売る」は不自然。"}, "sentence_index": 0, "correct_answer": "見落とす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ミスを一冊見落としました。", "explanation": "助数詞の誤り：ミスに「冊」は使わない。"}, {"text": "大切な点に見落とした。", "explanation": "助詞の混同：見落とす対象は「を」で示す。"}, {"text": "明日、私は彼の間違いを見落としていた。", "explanation": "活用・アスペクトの誤り：「明日」と過去の「ていた」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79aab334-e32f-4799-8f16-c84c7d95308f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
