INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37877, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "刻む", "is_correct": true, "explanation": "正解。きざむ。"}, {"text": "軋む", "is_correct": false, "explanation": "きしむ。「ざ」が「し」になった語。"}, {"text": "兆し", "is_correct": false, "explanation": "きざし。「む」が「し」になった語。"}, {"text": "気障", "is_correct": false, "explanation": "きざ。最後の「む」がない語。"}], "explanations": {"刻む": "正解。きざむ。", "軋む": "きしむ。「ざ」が「し」になった語。", "兆し": "きざし。「む」が「し」になった語。", "気障": "きざ。最後の「む」がない語。"}, "sentence_index": null, "correct_answer": "刻む"}, "level_3": {"options": [{"text": "刻む", "is_correct": true, "explanation": "正解。玉ねぎを細かく切ると涙が出る、という文意に合う。"}, {"text": "洗う", "is_correct": false, "explanation": "意味：洗っても涙は出ない。"}, {"text": "買う", "is_correct": false, "explanation": "意味：買うことと涙は結びつかない。"}, {"text": "植える", "is_correct": false, "explanation": "連語：玉ねぎを植えて涙が出るのは不自然。"}], "explanations": {"刻む": "正解。玉ねぎを細かく切ると涙が出る、という文意に合う。", "洗う": "意味：洗っても涙は出ない。", "買う": "意味：買うことと涙は結びつかない。", "植える": "連語：玉ねぎを植えて涙が出るのは不自然。"}, "sentence_index": 6, "correct_answer": "刻む"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "記念碑を名前に刻む。", "explanation": "助詞の混同：刻む場所は「に」、刻むものは「を」。"}, {"text": "昨日、記念碑に名前を刻む。", "explanation": "活用・アスペクトの誤り：「昨日」には過去形が必要。"}, {"text": "記念碑に名前を一匹刻む。", "explanation": "助数詞の誤り：名前に「匹」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79aab334-e32f-4799-8f16-c84c7d95308f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37877, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は包丁が野菜を刻んだ。", "corrected_sentence": "父は包丁で野菜を刻んだ。", "error_description": "助詞の混同：道具は「が」ではなく「で」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "刻ま", "is_correct": true, "explanation": "正解。受身「れる」に続くのは未然形。"}, {"text": "刻み", "is_correct": false, "explanation": "連用形には「れる」が付かない。"}, {"text": "刻む", "is_correct": false, "explanation": "辞書形には「れる」が付かない。"}, {"text": "刻も", "is_correct": false, "explanation": "意向形「刻もう」の語幹で「れる」に続かない。"}], "correct_form": "刻ま", "base_form": "刻む", "form_label": "未然形（受身）", "sentence_index": 7, "explanations": {"刻ま": "正解。受身「れる」に続くのは未然形。", "刻み": "連用形には「れる」が付かない。", "刻む": "辞書形には「れる」が付かない。", "刻も": "意向形「刻もう」の語幹で「れる」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79aab334-e32f-4799-8f16-c84c7d95308f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37877, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。刻まれる場所「胸」を示すので「に」。"}, {"text": "を", "is_correct": false, "explanation": "受身文で場所を目的語にできない。"}, {"text": "が", "is_correct": false, "explanation": "主格になり「思い出は」と衝突する。"}, {"text": "と", "is_correct": false, "explanation": "並列・引用になり意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "正解。刻まれる場所「胸」を示すので「に」。", "を": "受身文で場所を目的語にできない。", "が": "主格になり「思い出は」と衝突する。", "と": "並列・引用になり意味が通らない。"}, "error_tags": {"を": "location_vs_target", "が": "topic_vs_subject", "と": "listing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79aab334-e32f-4799-8f16-c84c7d95308f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52230, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "画一", "is_correct": true, "explanation": "正解。かくいつ。"}, {"text": "確実", "is_correct": false, "explanation": "かくじつ。「い」が「じ」に変わる一モーラ差。"}, {"text": "格別", "is_correct": false, "explanation": "かくべつ。「い」が「べ」に変わる一モーラ差。"}, {"text": "確執", "is_correct": false, "explanation": "かくしつ。「い」が「し」に変わる一モーラ差。"}], "explanations": {"画一": "正解。かくいつ。", "確実": "かくじつ。「い」が「じ」に変わる一モーラ差。", "格別": "かくべつ。「い」が「べ」に変わる一モーラ差。", "確執": "かくしつ。「い」が「し」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "画一"}, "level_3": {"options": [{"text": "画一", "is_correct": true, "explanation": "正解。すべて同じ型にはめる教育モデルという文意に合う。"}, {"text": "温暖", "is_correct": false, "explanation": "意味：「温暖的」という語はなく文意に合わない。"}, {"text": "砂漠", "is_correct": false, "explanation": "意味：「砂漠的な知識伝達モデル」は意味をなさない。"}, {"text": "野性", "is_correct": false, "explanation": "意味：知識伝達に野性は関係しない。"}], "explanations": {"画一": "正解。すべて同じ型にはめる教育モデルという文意に合う。", "温暖": "意味：「温暖的」という語はなく文意に合わない。", "砂漠": "意味：「砂漠的な知識伝達モデル」は意味をなさない。", "野性": "意味：知識伝達に野性は関係しない。"}, "sentence_index": 0, "correct_answer": "画一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町の家が三匹の画一だ。", "explanation": "助数詞の誤り：家に「匹」は使わない。"}, {"text": "町の家を画一的に見える。", "explanation": "助詞の混同：「見える」の主語は「が」で示す。"}, {"text": "明日、町の家が画一的に見えた。", "explanation": "活用・アスペクトの誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79aab334-e32f-4799-8f16-c84c7d95308f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
