INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52230, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「優先される」の主語「効率性」を示すので「が」。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "並列になり主語がなくなる。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾になり述語に続かない。"}], "correct_answer": "が", "explanations": {"が": "正解。「優先される」の主語「効率性」を示すので「が」。", "へ": "方向を表し主語にならない。", "と": "並列になり主語がなくなる。", "の": "連体修飾になり述語に続かない。"}, "error_tags": {"へ": "direction", "と": "listing", "の": "other"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多様", "is_correct": true, "explanation": "正解。すべて同じ⇔さまざま、の対義関係。"}, {"text": "統一", "is_correct": false, "explanation": "同じ方向の意味で対義ではない。"}, {"text": "平均", "is_correct": false, "explanation": "分野は近いが対義ではない。"}, {"text": "規則", "is_correct": false, "explanation": "関係はあるが対義ではない。"}], "correct_answer": "多様", "explanations": {"多様": "正解。すべて同じ⇔さまざま、の対義関係。", "統一": "同じ方向の意味で対義ではない。", "平均": "分野は近いが対義ではない。", "規則": "関係はあるが対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79aab334-e32f-4799-8f16-c84c7d95308f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52230, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "画一", "is_correct": true, "explanation": "正解。かくいつ。"}, {"text": "確実", "is_correct": false, "explanation": "かくじつ。「い」が「じ」。"}, {"text": "隔月", "is_correct": false, "explanation": "かくげつ。「い」が「げ」。"}, {"text": "各位", "is_correct": false, "explanation": "かくい。最後の「つ」がない。"}], "explanations": {"画一": "正解。かくいつ。", "確実": "かくじつ。「い」が「じ」。", "隔月": "かくげつ。「い」が「げ」。", "各位": "かくい。最後の「つ」がない。"}, "sentence_index": null, "correct_answer": "画一"}, "level_3": {"options": [{"text": "画一", "is_correct": true, "explanation": "正解。商品がみな同じ型にそろってきたという文意に合う。"}, {"text": "温暖", "is_correct": false, "explanation": "意味：商品が温暖化することはない。"}, {"text": "高齢", "is_correct": false, "explanation": "意味：高齢化は人について言う。"}, {"text": "砂漠", "is_correct": false, "explanation": "意味：商品が砂漠化することはない。"}], "explanations": {"画一": "正解。商品がみな同じ型にそろってきたという文意に合う。", "温暖": "意味：商品が温暖化することはない。", "高齢": "意味：高齢化は人について言う。", "砂漠": "意味：商品が砂漠化することはない。"}, "sentence_index": 6, "correct_answer": "画一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "画一を多様さより大切にしたいので、個性が好きだ。", "explanation": "意味の誤り：画一を大切にするのに個性が好きとは矛盾する。"}, {"text": "画一が多様さを大切にしたい。", "explanation": "助詞の混同：比較は「より」で示し、主語にできない。"}, {"text": "昨日から画一より多様さを大切にしたいだろう。", "explanation": "活用・アスペクトの誤り：「昨日から」と推量の「だろう」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79aab334-e32f-4799-8f16-c84c7d95308f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
