INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35753, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "モデル", "is_correct": true, "explanation": "正解。もでる。"}, {"text": "モデム", "is_correct": false, "explanation": "もでむ。「る」が「む」に変わる一モーラ差。"}, {"text": "燃える", "is_correct": false, "explanation": "もえる。「で」が「え」に変わる一モーラ差。"}, {"text": "漏れる", "is_correct": false, "explanation": "もれる。「で」が「れ」に変わる一モーラ差。"}, {"text": "もてる", "is_correct": false, "explanation": "もてる。「で」が「て」になる清濁の違い。"}], "explanations": {"モデル": "正解。もでる。", "モデム": "もでむ。「る」が「む」に変わる一モーラ差。", "燃える": "もえる。「で」が「え」に変わる一モーラ差。", "漏れる": "もれる。「で」が「れ」に変わる一モーラ差。", "もてる": "もてる。「で」が「て」になる清濁の違い。"}, "sentence_index": null, "correct_answer": "モデル"}, "level_3": {"options": [{"text": "モデル", "is_correct": true, "explanation": "正解。知識を伝える仕組み・型という意味に合う。"}, {"text": "タオル", "is_correct": false, "explanation": "意味：知識伝達のタオルとは言わない。"}, {"text": "ボール", "is_correct": false, "explanation": "意味：知識伝達のボールは意味をなさない。"}, {"text": "ドア", "is_correct": false, "explanation": "連語：「知識伝達ドア」は不自然。"}], "explanations": {"モデル": "正解。知識を伝える仕組み・型という意味に合う。", "タオル": "意味：知識伝達のタオルとは言わない。", "ボール": "意味：知識伝達のボールは意味をなさない。", "ドア": "連語：「知識伝達ドア」は不自然。"}, "sentence_index": 0, "correct_answer": "モデル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町のごみ集めは他の町のモデルに一匹なった。", "explanation": "助数詞の誤り：モデルに「匹」は使わない。"}, {"text": "町のごみ集めは他の町のモデルをなった。", "explanation": "助詞の混同：「なる」の結果は「に」で示す。"}, {"text": "明日、町のごみ集めは他の町のモデルになった。", "explanation": "活用・アスペクトの誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79aab334-e32f-4799-8f16-c84c7d95308f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_war