INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38057, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "物事がすでに変わってしまい、元には戻らないことを表す。多く「もはや〜ない」の形で使う。", "primary_collocate": null, "pronunciation": "もはや", "ipa": "mohaja", "syllable_count": 3, "sentences": [{"text": "現代の高等教育において、画一的な知識伝達モデルはもはやその有効性を維持し得ない。", "target_word": "もはや", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "深紅とも、あるいは乾いた血の色とも形容すべきそのブーツは、もはや単なる履物という枠組みを超え、私の内面に潜む情動を可視化する媒体となっているのだ。\n\n指先でなぞる革の質感は、過ぎ去りし季節の冷たさと、それに抗った熱気を同時に記憶している。", "target_word": "もはや", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "もはや手遅れだ。", "target_word": "もはや", "complexity_tier": "T3", "furigana": "もはや", "sentence_source": "generated"}, {"text": "彼はもはや子どもではない。", "target_word": "もはや", "complexity_tier": "T3", "furigana": "かれ こ", "sentence_source": "generated"}, {"text": "もはや誰も信じられない。", "target_word": "もはや", "complexity_tier": "T3", "furigana": "だれ しん", "sentence_source": "generated"}, {"text": "その店はもはや存在しない。", "target_word": "もはや", "complexity_tier": "T3", "furigana": "みせ そんざい", "sentence_source": "generated"}, {"text": "もはや待つ時間はない。", "target_word": "もはや", "complexity_tier": "T3", "furigana": "ま じかん", "sentence_source": "generated"}, {"text": "この方法はもはや古い。", "target_word": "もはや", "complexity_tier": "T3", "furigana": "ほうほう ふる", "sentence_source": "generated"}, {"text": "もはや後戻りはできない。", "target_word": "もはや", "complexity_tier": "T3", "furigana": "あともど", "sentence_source": "generated"}, {"text": "痛みはもはや感じない。", "target_word": "もはや", "complexity_tier": "T3", "furigana": "いた かん", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "副詞 | すでに状況が変わり元に戻らない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code: