INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52660, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "資料や情報などを人に示すこと。", "primary_collocate": null, "pronunciation": "ていじ", "ipa": "teːdʑi", "syllable_count": 3, "sentences": [{"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "提示", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "提示", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "受付で学生証を提示した。", "target_word": "提示", "complexity_tier": "T3", "furigana": "うけつけ がくせいしょう ていじ", "sentence_source": "generated"}, {"text": "先生が新しい案を提示した。", "target_word": "提示", "complexity_tier": "T3", "furigana": "せんせい あたら あん ていじ", "sentence_source": "generated"}, {"text": "資料の提示が遅れた。", "target_word": "提示", "complexity_tier": "T3", "furigana": "しりょう ていじ おく", "sentence_source": "generated"}, {"text": "入口でチケットを提示する。", "target_word": "提示", "complexity_tier": "T3", "furigana": "いりぐち ていじ", "sentence_source": "generated"}, {"text": "証拠の提示を求められた。", "target_word": "提示", "complexity_tier": "T3", "furigana": "しょうこ ていじ もと", "sentence_source": "generated"}, {"text": "彼は条件を提示してきた。", "target_word": "提示", "complexity_tier": "T3", "furigana": "かれ じょうけん ていじ", "sentence_source": "generated"}, {"text": "データを提示して説明した。", "target_word": "提示", "complexity_tier": "T3", "furigana": "ていじ せつめい", "sentence_source": "generated"}, {"text": "身分証の提示が必要です。", "target_word": "提示", "complexity_tier": "T3", "furigana": "みぶんしょう ていじ ひつよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "提示する", "label": "派生"}, {"form": "提示した", "label": "活用"}, {"form": "提示される", "label": "活用"}], "register": "formal", "sense_fin