INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38451, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "ある性質や物を豊かに持っている。多く「〜に富む」の形で使う。", "primary_collocate": null, "pronunciation": "とむ", "ipa": "tomɯ", "syllable_count": 2, "sentences": [{"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "富む", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "富ん", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "彼の話は変化に富む。", "target_word": "富む", "complexity_tier": "T3", "furigana": "かれ はなし へんか と", "sentence_source": "generated"}, {"text": "この地方は資源に富む。", "target_word": "富む", "complexity_tier": "T3", "furigana": "ちほう しげん と", "sentence_source": "generated"}, {"text": "彼女は才能に富んでいる。", "target_word": "富ん", "complexity_tier": "T3", "furigana": "かのじょ さいのう と", "sentence_source": "generated"}, {"text": "栄養に富んだ食事をとる。", "target_word": "富ん", "complexity_tier": "T3", "furigana": "えいよう と しょくじ", "sentence_source": "generated"}, {"text": "この国は自然に富む。", "target_word": "富む", "complexity_tier": "T3", "furigana": "くに しぜん と", "sentence_source": "generated"}, {"text": "彼はユーモアに富む人だ。", "target_word": "富む", "complexity_tier": "T3", "furigana": "かれ と ひと", "sentence_source": "generated"}, {"text": "経験に富んだ先生が来た。", "target_word": "富ん", "complexity_tier": "T3", "furigana": "けいけん と せんせい き", "sentence_source": "generated"}, {"text": "果物はビタミンに富む。", "target_word": "富む", "complexity_tier": "T3", "furigana": "くだもの と", "sentence_source": "generated"}], "morphological_forms": [{"form": "富んだ", "label": "活用"}, {"form": "富んで", "label": "活用"}, {"form": "富まない", "label": "活用"}, {"form": "富み", "label": "派生"}], "register": "formal", "sense_fingerprin