INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36413, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "実際に物事や仕事が行われている場所。また、事件や事故が起きた場所。", "primary_collocate": null, "pronunciation": "げんば", "ipa": "gemba", "syllable_count": 3, "sentences": [{"text": "大学教育の現場において、教授陣が個々の学修到達度を最大化するためにこのシステムを如何に設計し、運用するかが問われているのである。", "target_word": "現場", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "犯罪現場という苛烈な情報の奔流の中から、科学捜査の担い手は微細な痕跡を拾い上げる。", "target_word": "現場", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "まず、現場や鑑識ラボにおいて、肉眼では捉えられぬ潜在指紋を、シアノアクリレート法や光学的手法といったアプローチにより顕在化させる。", "target_word": "現場", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "警察が事故の現場に来た。", "target_word": "現場", "complexity_tier": "T3", "furigana": "けいさつ じこ げんば き", "sentence_source": "generated"}, {"text": "父は工事の現場で働く。", "target_word": "現場", "complexity_tier": "T3", "furigana": "ちち こうじ げんば はたら", "sentence_source": "generated"}, {"text": "現場の声を大切にしたい。", "target_word": "現場", "complexity_tier": "T3", "furigana": "げんば こえ たいせつ", "sentence_source": "generated"}, {"text": "記者が現場から伝えている。", "target_word": "現場", "complexity_tier": "T3", "furigana": "きしゃ げんば つた", "sentence_source": "generated"}, {"text": "現場はとても暑かった。", "target_word": "現場", "complexity_tier": "T3", "furigana": "げんば あつ", "sentence_source": "generated"}, {"text": "彼は毎日現場に通っている。", "target_word": "現場", "complexity_tier": "T3", "furigana": "かれ まいにち げんば かよ", "sentence_source": "generated"}, {"text": "現場を見て問題に気づいた。", "target_word": "現場", "complexity_tier": "T3", "furigana": "げんば み もんだい き", "sentence_source": "generated"}], "morphological_forms": [{"form": "現場監督", "label": "派生"}, {"form": "工事現場", "label": "派生"}, {"form": "事故現場", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事が実際に行われる場所", "collocat