INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38077, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "わからないことを尋ねる。また、責任や能力などを問題として取り上げる。", "primary_collocate": null, "pronunciation": "とう", "ipa": "toɯ", "syllable_count": 2, "sentences": [{"text": "大学教育の現場において、教授陣が個々の学修到達度を最大化するためにこのシステムを如何に設計し、運用するかが問われているのである。", "target_word": "問わ", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな冷徹さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "問う", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "年齢は問わない。", "target_word": "問わ", "complexity_tier": "T3", "furigana": "ねんれい と", "sentence_source": "generated"}, {"text": "彼に理由を問うた。", "target_word": "問う", "complexity_tier": "T3", "furigana": "かれ りゆう と", "sentence_source": "generated"}, {"text": "リーダーの責任が問われる。", "target_word": "問わ", "complexity_tier": "T3", "furigana": "せきにん と", "sentence_source": "generated"}, {"text": "経験の有無は問わない。", "target_word": "問わ", "complexity_tier": "T3", "furigana": "けいけん うむ と", "sentence_source": "generated"}, {"text": "先生は生徒に意見を問う。", "target_word": "問う", "complexity_tier": "T3", "furigana": "せんせい せいと いけん と", "sentence_source": "generated"}, {"text": "男女を問わず参加できる。", "target_word": "問わ", "complexity_tier": "T3", "furigana": "だんじょ と さんか", "sentence_source": "generated"}, {"text": "自分の心に問うてみた。", "target_word": "問う", "complexity_tier": "T3", "furigana": "じぶん こころ と", "sentence_source": "generated"}, {"text": "今、私たちの力が問われている。", "target_word": "問わ", "complexity_tier": "T3", "furigana": "いま わたし ちから と", "sentence_source": "generated"}], "morphological_forms": [{"form": "問わない", "label": "活用"}, {"form": "問われる", "label": "活用"}, {"form": "問うた", "label": "活用"}, {"form": "問い", "label": "派生"}], "register": "formal", "sense_fing