INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36421, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を考えたり進めたりするときの、基本となる考え方や仕組み。", "primary_collocate": null, "pronunciation": "わくぐみ", "ipa": "ɰakɯgɯmi", "syllable_count": 4, "sentences": [{"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "深紅とも、あるいは乾いた血の色とも形容すべきそのブーツは、もはや単なる履物という枠組みを超え、私の内面に潜む情動を可視化する媒体となっているのだ。\n\n指先でなぞる革の質感は、過ぎ去りし季節の冷たさと、それに抗った熱気を同時に記憶している。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "計画の枠組みが決まった。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "けいかく わくぐみ き", "sentence_source": "generated"}, {"text": "新しい枠組みを作る。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "あたら わくぐみ つく", "sentence_source": "generated"}, {"text": "話し合いの枠組みを考えた。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "はな あ わくぐみ かんが", "sentence_source": "generated"}, {"text": "古い枠組みにとらわれない。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "ふる わくぐみ", "sentence_source": "generated"}, {"text": "この枠組みは使いやすい。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "わくぐみ つか", "sentence_source": "generated"}, {"text": "国際的な枠組みで協力する。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "こくさいてき わくぐみ きょうりょく", "sentence_source": "generated"}, {"text": "枠組みを変える必要がある。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "わくぐみ か ひつよう", "sentence_source": "generated"}, {"text": "その枠組みの中で考えよう。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "わくぐみ なか かんが", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 物事の基本となる考え方や構成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: 10 words above tier T3 (max 3): 深紅 (Zipf 2.91), 形容 (Zipf 3.21), 履物 (Zipf 2.6), 潜む (Zipf 3.39), 情動 (Zipf 2.72), なぞる (Zipf 2.97)']::text[], '97a1f2a1-a8c9-40c4-a0e9-9ab6216eeaf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38057, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "最早", "is_correct": true, "explanation": "音声「もはや」の正しい表記。"}, {"text": "模範", "is_correct": false, "explanation": "「もはん」と読み、最後のモーラ「や」が「ん」に変わる一モーラ差。"}, {"text": "餅屋", "is_correct": false, "explanation": "「もちや」と読み、「は」が「ち」に変わる一モーラ差。"}, {"text": "専ら", "is_correct": false, "explanation": "古語的読み「もはら」で、最後のモーラ「や」が「ら」に変わる一モーラ差。"}], "explanations": {"最早": "音声「もはや」の正しい表記。", "模範": "「もはん」と読み、最後のモーラ「や」が「ん」に変わる一モーラ差。", "餅屋": "「もちや」と読み、「は」が「ち」に変わる一モーラ差。", "専ら": "古語的読み「もはら」で、最後のモーラ「や」が「ら」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "最早"}, "level_3": {"options": [{"text": "もはや", "is_correct": true, "explanation": "文脈と義項に合う唯一の語。"}, {"text": "ぜひ", "is_correct": false, "explanation": "連語：「ぜひ」は願望と結びつき、否定の「得ない」とは合わない"}, {"text": "ちょうど", "is_correct": false, "explanation": "意味：数量や時刻の一致を表し、状態の変化を表さない"}, {"text": "わざわざ", "is_correct": false, "explanation": "意味：特別に手間をかける意味で、文意に合わない"}], "explanations": {"もはや": "文脈と義項に合う唯一の語。", "ぜひ": "連語：「ぜひ」は願望と結びつき、否定の「得ない」とは合わない", "ちょうど": "意味：数量や時刻の一致を表し、状態の変化を表さない", "わざわざ": "意味：特別に手間をかける意味で、文意に合わない"}, "sentence_index": 0, "correct_answer": "もはや"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼をもはや子どもではない。", "explanation": "助詞の混同：主題は「は」で示し、「を」は使えない。"}, {"text": "明日、彼はもはや子どもではなかった。", "explanation": "活用・アスペクトの誤り：「明日」と過去形が矛盾する。"}, {"text": "彼はまだもはや子どもではない。", "explanation": "語順・係り受けの誤り：「まだ」と「もはや」が同時に係り、意味が矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
