INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38057, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "最早", "is_correct": true, "explanation": "音声「もはや」の正しい表記。"}, {"text": "餅屋", "is_correct": false, "explanation": "「もちや」と読み、「は」が「ち」に変わる一モーラ差。"}, {"text": "母屋", "is_correct": false, "explanation": "「おもや」と読み、「もや」の部分が共通する近い音。"}, {"text": "喪屋", "is_correct": false, "explanation": "「もや」と読み、モーラ「は」が抜けた近い音。"}], "explanations": {"最早": "音声「もはや」の正しい表記。", "餅屋": "「もちや」と読み、「は」が「ち」に変わる一モーラ差。", "母屋": "「おもや」と読み、「もや」の部分が共通する近い音。", "喪屋": "「もや」と読み、モーラ「は」が抜けた近い音。"}, "sentence_index": null, "correct_answer": "最早"}, "level_3": {"options": [{"text": "もはや", "is_correct": true, "explanation": "文脈と義項に合う唯一の語。"}, {"text": "ぜひ", "is_correct": false, "explanation": "連語：願望の副詞で、「ない」という否定と結びつかない"}, {"text": "さっき", "is_correct": false, "explanation": "アスペクト：過去の時点を表し、「時間はない」という現在の状態と合わない"}, {"text": "ぴったり", "is_correct": false, "explanation": "意味：一致を表し、時間がなくなった変化を表さない"}], "explanations": {"もはや": "文脈と義項に合う唯一の語。", "ぜひ": "連語：願望の副詞で、「ない」という否定と結びつかない", "さっき": "アスペクト：過去の時点を表し、「時間はない」という現在の状態と合わない", "ぴったり": "意味：一致を表し、時間がなくなった変化を表さない"}, "sentence_index": 6, "correct_answer": "もはや"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "痛みはもはや感じないだ。", "explanation": "活用の誤り：否定の「ない」の後に「だ」は付けない。"}, {"text": "一枚の痛みはもはや感じない。", "explanation": "助数詞の誤り：痛みを「枚」で数えることはできない。"}, {"text": "痛みは感じもはやない。", "explanation": "語順の誤り：「もはや」は述語「感じない」の前に置き、動詞の中に割り込ませない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
