INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52660, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提示", "is_correct": true, "explanation": "音声「ていじ」の正しい表記。"}, {"text": "政治", "is_correct": false, "explanation": "「せいじ」と読み、最初のモーラ「て」が「せ」に変わる一モーラ差。"}, {"text": "停止", "is_correct": false, "explanation": "「ていし」と読み、最後のモーラ「じ」が清音「し」になる清濁の対立。"}, {"text": "定期", "is_correct": false, "explanation": "「ていき」と読み、「じ」が「き」に変わる一モーラ差。"}, {"text": "定義", "is_correct": false, "explanation": "「ていぎ」と読み、「じ」が「ぎ」に変わる一モーラ差。"}], "explanations": {"提示": "音声「ていじ」の正しい表記。", "政治": "「せいじ」と読み、最初のモーラ「て」が「せ」に変わる一モーラ差。", "停止": "「ていし」と読み、最後のモーラ「じ」が清音「し」になる清濁の対立。", "定期": "「ていき」と読み、「じ」が「き」に変わる一モーラ差。", "定義": "「ていぎ」と読み、「じ」が「ぎ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "提示"}, "level_3": {"options": [{"text": "提示", "is_correct": true, "explanation": "文脈と義項に合う唯一の語。"}, {"text": "睡眠", "is_correct": false, "explanation": "意味：眠ることで、教材と結びつかない"}, {"text": "天気", "is_correct": false, "explanation": "意味：気象を表し、可能にする対象として意味が通らない"}, {"text": "謝罪", "is_correct": false, "explanation": "連語：「教材謝罪」という結びつきは成立しない"}], "explanations": {"提示": "文脈と義項に合う唯一の語。", "睡眠": "意味：眠ることで、教材と結びつかない", "天気": "意味：気象を表し、可能にする対象として意味が通らない", "謝罪": "連語：「教材謝罪」という結びつきは成立しない"}, "sentence_index": 0, "correct_answer": "提示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生が新しい案に提示した。", "explanation": "助詞の混同：示す内容は「を」で示し、「に」は使えない。"}, {"text": "明日、先生が新しい案を提示した。", "explanation": "活用・アスペクトの誤り：「明日」と過去形が矛盾する。"}, {"text": "先生が三匹の新しい案を提示した。", "explanation": "助数詞の誤り：案を「匹」で数えることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
