INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52660, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "提示", "is_correct": true, "explanation": "音声「ていじ」の正しい表記。"}, {"text": "明治", "is_correct": false, "explanation": "「めいじ」と読み、最初のモーラ「て」が「め」に変わる一モーラ差。"}, {"text": "零時", "is_correct": false, "explanation": "「れいじ」と読み、「て」が「れ」に変わる一モーラ差。"}, {"text": "低地", "is_correct": false, "explanation": "「ていち」と読み、最後のモーラ「じ」が「ち」に変わる一モーラ差。"}, {"text": "刑事", "is_correct": false, "explanation": "「けいじ」と読み、「て」が「け」に変わる一モーラ差。"}], "explanations": {"提示": "音声「ていじ」の正しい表記。", "明治": "「めいじ」と読み、最初のモーラ「て」が「め」に変わる一モーラ差。", "零時": "「れいじ」と読み、「て」が「れ」に変わる一モーラ差。", "低地": "「ていち」と読み、最後のモーラ「じ」が「ち」に変わる一モーラ差。", "刑事": "「けいじ」と読み、「て」が「け」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "提示"}, "level_3": {"options": [{"text": "提示", "is_correct": true, "explanation": "文脈と義項に合う唯一の語。"}, {"text": "昼寝", "is_correct": false, "explanation": "意味：証拠に対して求める行為として意味が通らない"}, {"text": "散歩", "is_correct": false, "explanation": "意味：歩くことで、証拠と結びつかない"}, {"text": "拍手", "is_correct": false, "explanation": "連語：「証拠の拍手」という結びつきはない"}], "explanations": {"提示": "文脈と義項に合う唯一の語。", "昼寝": "意味：証拠に対して求める行為として意味が通らない", "散歩": "意味：歩くことで、証拠と結びつかない", "拍手": "連語：「証拠の拍手」という結びつきはない"}, "sentence_index": 6, "correct_answer": "提示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "身分証を提示が必要です。", "explanation": "助詞の混同：名詞「提示」を修飾するには「の」を使い、「を」は使えない。"}, {"text": "一匹の身分証の提示が必要です。", "explanation": "助数詞の誤り：身分証を「匹」で数えることはできない。"}, {"text": "身分証の提示しが必要です。", "explanation": "品詞・形の誤り：名詞として使うときは「提示」で、「提示し」に「が」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52660, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "データを提示しって説明した。", "corrected_sentence": "データを提示して説明した。", "error_description": "活用の誤り：「提示する」のて形は「提示して」で、「提示しって」ではない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52660, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「提示する」の目的語「条件」を標示する。"}, {"text": "が", "is_correct": false, "explanation": "「条件が提示してきた」では条件が主体になり非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は提示する物を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「条件に提示する」とは言わない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「提示する」の目的語「条件」を標示する。", "が": "「条件が提示してきた」では条件が主体になり非文。", "へ": "方向の「へ」は提示する物を示せない。", "に": "「条件に提示する」とは言わない。"}, "error_tags": {"が": "object_marking", "へ": "direction", "に": "location_vs_target"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38451, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "富む", "is_correct": true, "explanation": "音声「とむ」の正しい表記。"}, {"text": "飛ぶ", "is_correct": false, "explanation": "「とぶ」と読み、二つ目のモーラ「む」が「ぶ」に変わる一モーラ差。"}, {"text": "取る", "is_correct": false, "explanation": "「とる」と読み、「む」が「る」に変わる一モーラ差。"}, {"text": "組む", "is_correct": false, "explanation": "「くむ」と読み、最初のモーラ「と」が「く」に変わる一モーラ差。"}, {"text": "込む", "is_correct": false, "explanation": "「こむ」と読み、「と」が「こ」に変わる一モーラ差。"}, {"text": "住む", "is_correct": false, "explanation": "「すむ」と読み、「と」が「す」に変わる一モーラ差。"}], "explanations": {"富む": "音声「とむ」の正しい表記。", "飛ぶ": "「とぶ」と読み、二つ目のモーラ「む」が「ぶ」に変わる一モーラ差。", "取る": "「とる」と読み、「む」が「る」に変わる一モーラ差。", "組む": "「くむ」と読み、最初のモーラ「と」が「く」に変わる一モーラ差。", "込む": "「こむ」と読み、「と」が「こ」に変わる一モーラ差。", "住む": "「すむ」と読み、「と」が「す」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "富む"}, "level_3": {"options": [{"text": "富む", "is_correct": true, "explanation": "文脈と義項に合う唯一の語。"}, {"text": "走る", "is_correct": false, "explanation": "意味：「示唆に走る」では意味が通らない"}, {"text": "泳ぐ", "is_correct": false, "explanation": "意味：導入が泳ぐことはなく、意味が合わない"}, {"text": "似る", "is_correct": false, "explanation": "項構造：「似る」は比べる相手をとり、「示唆に似る」は不自然"}], "explanations": {"富む": "文脈と義項に合う唯一の語。", "走る": "意味：「示唆に走る」では意味が通らない", "泳ぐ": "意味：導入が泳ぐことはなく、意味が合わない", "似る": "項構造：「似る」は比べる相手をとり、「示唆に似る」は不自然"}, "sentence_index": 0, "correct_answer": "富む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この地方は資源を富む。", "explanation": "助詞の混同：「富む」は「〜に富む」の形をとり、「を」は使えない。"}, {"text": "この地方は資源に富みている。", "explanation": "活用の誤り：て形は「富んで」で、「富みている」という形はない。"}, {"text": "一匹の地方は資源に富む。", "explanation": "助数詞の誤り：地方を「匹」で数えることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38451, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の話は変化を富む。", "corrected_sentence": "彼の話は変化に富む。", "error_description": "助詞の混同：「富む」は「を」ではなく「に」をとる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "富ん", "is_correct": true, "explanation": "「富む」の連用形は撥音便で「富ん」となり、「だ」に続く。"}, {"text": "富ま", "is_correct": false, "explanation": "「富まだ」という形はない。未然形は「ない」に続く。"}, {"text": "富み", "is_correct": false, "explanation": "「富みだ」は誤り。た形は撥音便「富んだ」になる。"}, {"text": "富め", "is_correct": false, "explanation": "「富めだ」という形はない。"}], "correct_form": "富ん", "base_form": "富む", "form_label": "連用形（撥音便）", "sentence_index": 1, "explanations": {"富ん": "「富む」の連用形は撥音便で「富ん」となり、「だ」に続く。", "富ま": "「富まだ」という形はない。未然形は「ない」に続く。", "富み": "「富みだ」は誤り。た形は撥音便「富んだ」になる。", "富め": "「富めだ」という形はない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38451, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "欠ける", "is_correct": true, "explanation": "「〜に欠ける」は不足していることを表し、「〜に富む」の対義語。"}, {"text": "満ちる", "is_correct": false, "explanation": "十分にある意味で、類義であり対義ではない。"}, {"text": "恵まれる", "is_correct": false, "explanation": "よいものが豊かにある意味で、類義語。"}, {"text": "備える", "is_correct": false, "explanation": "持っている・準備する意味で、対義ではない。"}], "correct_answer": "欠ける", "explanations": {"欠ける": "「〜に欠ける」は不足していることを表し、「〜に富む」の対義語。", "満ちる": "十分にある意味で、類義であり対義ではない。", "恵まれる": "よいものが豊かにある意味で、類義語。", "備える": "持っている・準備する意味で、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38451, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "富む", "is_correct": true, "explanation": "音声「とむ」の正しい表記。"}, {"text": "止む", "is_correct": false, "explanation": "「やむ」と読み、最初のモーラ「と」が「や」に変わる一モーラ差。"}, {"text": "説く", "is_correct": false, "explanation": "「とく」と読み、二つ目のモーラ「む」が「く」に変わる一モーラ差。"}, {"text": "汲む", "is_correct": false, "explanation": "「くむ」と読み、「と」が「く」に変わる一モーラ差。"}, {"text": "研ぐ", "is_correct": false, "explanation": "「とぐ」と読み、「む」が「ぐ」に変わる一モーラ差。"}], "explanations": {"富む": "音声「とむ」の正しい表記。", "止む": "「やむ」と読み、最初のモーラ「と」が「や」に変わる一モーラ差。", "説く": "「とく」と読み、二つ目のモーラ「む」が「く」に変わる一モーラ差。", "汲む": "「くむ」と読み、「と」が「く」に変わる一モーラ差。", "研ぐ": "「とぐ」と読み、「む」が「ぐ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "富む"}, "level_3": {"options": [{"text": "富む", "is_correct": true, "explanation": "文脈と義項に合う唯一の語。"}, {"text": "座る", "is_correct": false, "explanation": "意味：国が座ることはなく、意味が通らない"}, {"text": "書く", "is_correct": false, "explanation": "項構造：「書く」は「〜を」をとり、「自然に書く」では豊かさを表さない"}, {"text": "売る", "is_correct": false, "explanation": "項構造：「売る」は目的語「〜を」をとり、この文型に合わない"}], "explanations": {"富む": "文脈と義項に合う唯一の語。", "座る": "意味：国が座ることはなく、意味が通らない", "書く": "項構造：「書く」は「〜を」をとり、「自然に書く」では豊かさを表さない", "売る": "項構造：「売る」は目的語「〜を」をとり、この文型に合わない"}, "sentence_index": 6, "correct_answer": "富む"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "果物はビタミンで富む。", "explanation": "助詞の混同：「富む」は「〜に富む」で、「で」は使えない。"}, {"text": "果物はビタミンに富んている。", "explanation": "活用の誤り：て形は「富んで」で、「富んて」とは言わない。"}, {"text": "果物は二冊のビタミンに富む。", "explanation": "助数詞の誤り：ビタミンを「冊」で数えることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38451, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は才能に富みている。", "corrected_sentence": "彼女は才能に富んでいる。", "error_description": "活用の誤り：「富む」のて形は「富んで」で、「富みて」ではない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "富む", "is_correct": true, "explanation": "名詞「人」を修飾する連体形として辞書形が入る。"}, {"text": "富んで", "is_correct": false, "explanation": "て形は名詞を直接修飾できない。"}, {"text": "富もう", "is_correct": false, "explanation": "意向形は名詞を修飾しない。"}, {"text": "富め", "is_correct": false, "explanation": "命令形は名詞を修飾できない。"}], "correct_form": "富む", "base_form": "富む", "form_label": "辞書形（連体形）", "sentence_index": 7, "explanations": {"富む": "名詞「人」を修飾する連体形として辞書形が入る。", "富んで": "て形は名詞を直接修飾できない。", "富もう": "意向形は名詞を修飾しない。", "富め": "命令形は名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38451, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "欠ける", "is_correct": true, "explanation": "必要なものが足りないことで、「富む」の対義語。"}, {"text": "溢れる", "is_correct": false, "explanation": "いっぱいにある意味で、類義に近く対義ではない。"}, {"text": "含む", "is_correct": false, "explanation": "中に持っている意味で、対義ではない。"}, {"text": "持つ", "is_correct": false, "explanation": "所有を表し、「富む」の反対ではない。"}], "correct_answer": "欠ける", "explanations": {"欠ける": "必要なものが足りないことで、「富む」の対義語。", "溢れる": "いっぱいにある意味で、類義に近く対義ではない。", "含む": "中に持っている意味で、対義ではない。", "持つ": "所有を表し、「富む」の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36413, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "現場", "is_correct": true, "explanation": "音声「げんば」の正しい表記。"}, {"text": "元気", "is_correct": false, "explanation": "「げんき」と読み、最後のモーラ「ば」が「き」に変わる一モーラ差。"}, {"text": "言語", "is_correct": false, "explanation": "「げんご」と読み、最後のモーラ「ば」が「ご」に変わる一モーラ差。"}, {"text": "原価", "is_correct": false, "explanation": "「げんか」と読み、最後のモーラ「ば」が「か」に変わる一モーラ差。"}, {"text": "原子", "is_correct": false, "explanation": "「げんし」と読み、最後のモーラ「ば」が「し」に変わる一モーラ差。"}], "explanations": {"現場": "音声「げんば」の正しい表記。", "元気": "「げんき」と読み、最後のモーラ「ば」が「き」に変わる一モーラ差。", "言語": "「げんご」と読み、最後のモーラ「ば」が「ご」に変わる一モーラ差。", "原価": "「げんか」と読み、最後のモーラ「ば」が「か」に変わる一モーラ差。", "原子": "「げんし」と読み、最後のモーラ「ば」が「し」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "現場"}, "level_3": {"options": [{"text": "現場", "is_correct": true, "explanation": "文脈と義項に合う唯一の語。"}, {"text": "天井", "is_correct": false, "explanation": "意味：部屋の上の面で、教育が行われる場所を表さない"}, {"text": "財布", "is_correct": false, "explanation": "意味：お金を入れる物で、場所の意味にならない"}, {"text": "喜び", "is_correct": false, "explanation": "連語：「教育の喜びにおいて」は「おいて」と結びつかず不自然"}], "explanations": {"現場": "文脈と義項に合う唯一の語。", "天井": "意味：部屋の上の面で、教育が行われる場所を表さない", "財布": "意味：お金を入れる物で、場所の意味にならない", "喜び": "連語：「教育の喜びにおいて」は「おいて」と結びつかず不自然"}, "sentence_index": 0, "correct_answer": "現場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察が事故の現場を来た。", "explanation": "助詞の混同：「来る」の着点は「に」で示し、「を」は使えない。"}, {"text": "警察が一冊の事故の現場に来た。", "explanation": "助数詞の誤り：場所である現場を「冊」で数えることはできない。"}, {"text": "明日、警察が事故の現場に来た。", "explanation": "活用・アスペクトの誤り：「明日」と過去の「来た」が矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
