INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36413, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "現場", "is_correct": true, "explanation": "音声「げんば」の正しい表記。"}, {"text": "現地", "is_correct": false, "explanation": "「げんち」と読み、最後のモーラ「ば」が「ち」に変わる一モーラ差。"}, {"text": "源氏", "is_correct": false, "explanation": "「げんじ」と読み、「ば」が「じ」に変わる一モーラ差。"}, {"text": "サンバ", "is_correct": false, "explanation": "「さんば」と読み、最初のモーラ「げ」が「さ」に変わる一モーラ差。"}, {"text": "言語", "is_correct": false, "explanation": "「げんご」と読み、「ば」が「ご」に変わる一モーラ差。"}], "explanations": {"現場": "音声「げんば」の正しい表記。", "現地": "「げんち」と読み、最後のモーラ「ば」が「ち」に変わる一モーラ差。", "源氏": "「げんじ」と読み、「ば」が「じ」に変わる一モーラ差。", "サンバ": "「さんば」と読み、最初のモーラ「げ」が「さ」に変わる一モーラ差。", "言語": "「げんご」と読み、「ば」が「ご」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "現場"}, "level_3": {"options": [{"text": "現場", "is_correct": true, "explanation": "文脈と義項に合う唯一の語。"}, {"text": "昼寝", "is_correct": false, "explanation": "意味：行為であり、記者が報告する場所にならない"}, {"text": "好物", "is_correct": false, "explanation": "意味：好きな食べ物で、場所を表さない"}, {"text": "値段", "is_correct": false, "explanation": "意味：物の価格であり、そこから伝えることはできない"}], "explanations": {"現場": "文脈と義項に合う唯一の語。", "昼寝": "意味：行為であり、記者が報告する場所にならない", "好物": "意味：好きな食べ物で、場所を表さない", "値段": "意味：物の価格であり、そこから伝えることはできない"}, "sentence_index": 6, "correct_answer": "現場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "現場が見て問題に気づいた。", "explanation": "助詞の混同：見る対象は「を」で示し、「が」では現場が見る主体になる。"}, {"text": "明日、現場を見て問題に気づいた。", "explanation": "活用・アスペクトの誤り：未来の「明日」と過去形「気づいた」が合わない。"}, {"text": "二枚の現場を見て問題に気づいた。", "explanation": "助数詞の誤り：場所を「枚」で数えることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
