INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36413, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜において」は「に」＋「おいて」の固定形。"}, {"text": "で", "is_correct": false, "explanation": "「でおいて」という形はない。"}, {"text": "を", "is_correct": false, "explanation": "「現場をおいて」は「〜を除いて」の意になり文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へおいて」という形はない。"}], "correct_answer": "に", "explanations": {"に": "「〜において」は「に」＋「おいて」の固定形。", "で": "「でおいて」という形はない。", "を": "「現場をおいて」は「〜を除いて」の意になり文が成立しない。", "へ": "「へおいて」という形はない。"}, "error_tags": {"で": "location_vs_target", "を": "object_marking", "へ": "direction"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38077, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "問う", "is_correct": true, "explanation": "音声「とう」の正しい表記。"}, {"text": "飛ぶ", "is_correct": false, "explanation": "「とぶ」と読み、二つ目のモーラ「う」が「ぶ」に変わる一モーラ差。"}, {"text": "取る", "is_correct": false, "explanation": "「とる」と読み、「う」が「る」に変わる一モーラ差。"}, {"text": "解く", "is_correct": false, "explanation": "「とく」と読み、「う」が「く」に変わる一モーラ差。"}, {"text": "追う", "is_correct": false, "explanation": "「おう」と読み、最初のモーラ「と」が「お」に変わる一モーラ差。"}, {"text": "縫う", "is_correct": false, "explanation": "「ぬう」と読み、最初のモーラ「と」が「ぬ」に変わる一モーラ差。"}], "explanations": {"問う": "音声「とう」の正しい表記。", "飛ぶ": "「とぶ」と読み、二つ目のモーラ「う」が「ぶ」に変わる一モーラ差。", "取る": "「とる」と読み、「う」が「る」に変わる一モーラ差。", "解く": "「とく」と読み、「う」が「く」に変わる一モーラ差。", "追う": "「おう」と読み、最初のモーラ「と」が「お」に変わる一モーラ差。", "縫う": "「ぬう」と読み、最初のモーラ「と」が「ぬ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "問う"}, "level_3": {"options": [{"text": "問わ", "is_correct": true, "explanation": "文脈と義項に合う唯一の語。"}, {"text": "歌わ", "is_correct": false, "explanation": "意味：「歌われている」では設計・運用の方法が歌われることになり意味が通らない"}, {"text": "洗わ", "is_correct": false, "explanation": "意味：「洗われている」は物を洗う意味で文意に合わない"}, {"text": "払わ", "is_correct": false, "explanation": "連語：「〜かが払われている」という結びつきはない"}], "explanations": {"問わ": "文脈と義項に合う唯一の語。", "歌わ": "意味：「歌われている」では設計・運用の方法が歌われることになり意味が通らない", "洗わ": "意味：「洗われている」は物を洗う意味で文意に合わない", "払わ": "連語：「〜かが払われている」という結びつきはない"}, "sentence_index": 0, "correct_answer": "問わ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼に理由が問うた。", "explanation": "助詞の混同：問う内容は「を」で示し、「が」は使えない。"}, {"text": "明日、彼に理由を問うた。", "explanation": "活用・アスペクトの誤り：「明日」と過去形が矛盾する。"}, {"text": "彼に理由を問わった。", "explanation": "活用の誤り：「問う」の過去形は「問うた」で、「問わった」という形はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38077, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼に理由を問った。", "corrected_sentence": "彼に理由を問うた。", "error_description": "活用の誤り：「問う」の過去形は「問った」ではなく「問うた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "問う", "is_correct": true, "explanation": "「問う」のて形は特別に「問うて」となり、「問うている」が正しい。"}, {"text": "問わ", "is_correct": false, "explanation": "「問わている」という形はない。未然形は「ない・れる」に続く。"}, {"text": "問い", "is_correct": false, "explanation": "「問いている」は誤り。連用形「問い」は「て」に続かない。"}, {"text": "問え", "is_correct": false, "explanation": "「問えている」は可能・命令の形で、この文では成立しない。"}], "correct_form": "問う", "base_form": "問う", "form_label": "て形（「問うて」の語幹部）", "sentence_index": 1, "explanations": {"問う": "「問う」のて形は特別に「問うて」となり、「問うている」が正しい。", "問わ": "「問わている」という形はない。未然形は「ない・れる」に続く。", "問い": "「問いている」は誤り。連用形「問い」は「て」に続かない。", "問え": "「問えている」は可能・命令の形で、この文では成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38077, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「問う」の対象「本質」を標示する。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では問う対象が示されない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「問う」の対象にならない。"}, {"text": "と", "is_correct": false, "explanation": "「本質と問うている」は並列・引用として成立しない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「問う」の対象「本質」を標示する。", "で": "手段の「で」では問う対象が示されない。", "へ": "方向の「へ」は「問う」の対象にならない。", "と": "「本質と問うている」は並列・引用として成立しない。"}, "error_tags": {"で": "instrument", "へ": "direction", "と": "listing"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "答える", "is_correct": true, "explanation": "「問う」（たずねる）の対義語。"}, {"text": "尋ねる", "is_correct": false, "explanation": "「問う」の類義語であり、対義語ではない。"}, {"text": "調べる", "is_correct": false, "explanation": "情報を探す動作で、問うことの反対ではない。"}, {"text": "求める", "is_correct": false, "explanation": "何かを欲しがる意味で、対義の関係にない。"}], "correct_answer": "答える", "explanations": {"答える": "「問う」（たずねる）の対義語。", "尋ねる": "「問う」の類義語であり、対義語ではない。", "調べる": "情報を探す動作で、問うことの反対ではない。", "求める": "何かを欲しがる意味で、対義の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38077, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "問う", "is_correct": true, "explanation": "音声「とう」の正しい表記。"}, {"text": "吸う", "is_correct": false, "explanation": "「すう」と読み、最初のモーラ「と」が「す」に変わる一モーラ差。"}, {"text": "買う", "is_correct": false, "explanation": "「かう」と読み、「と」が「か」に変わる一モーラ差。"}, {"text": "酔う", "is_correct": false, "explanation": "「よう」と読み、「と」が「よ」に変わる一モーラ差。"}, {"text": "研ぐ", "is_correct": false, "explanation": "「とぐ」と読み、二つ目のモーラ「う」が「ぐ」に変わる一モーラ差。"}], "explanations": {"問う": "音声「とう」の正しい表記。", "吸う": "「すう」と読み、最初のモーラ「と」が「す」に変わる一モーラ差。", "買う": "「かう」と読み、「と」が「か」に変わる一モーラ差。", "酔う": "「よう」と読み、「と」が「よ」に変わる一モーラ差。", "研ぐ": "「とぐ」と読み、二つ目のモーラ「う」が「ぐ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "問う"}, "level_3": {"options": [{"text": "問う", "is_correct": true, "explanation": "文脈と義項に合う唯一の語。"}, {"text": "食べる", "is_correct": false, "explanation": "意味：意見は食べるものではない"}, {"text": "洗う", "is_correct": false, "explanation": "意味：意見は洗う対象にならない"}, {"text": "走る", "is_correct": false, "explanation": "項構造：「走る」は「意見を」という目的語をとらない"}], "explanations": {"問う": "文脈と義項に合う唯一の語。", "食べる": "意味：意見は食べるものではない", "洗う": "意味：意見は洗う対象にならない", "走る": "項構造：「走る」は「意見を」という目的語をとらない"}, "sentence_index": 6, "correct_answer": "問う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今、私たちの力に問われている。", "explanation": "助詞の混同：受身の主語は「が」で示す。「に」では問う相手になってしまう。"}, {"text": "明日、私たちの力が問われていた。", "explanation": "活用・アスペクトの誤り：「明日」と過去形「いた」が矛盾する。"}, {"text": "今、私たちの力が問わられている。", "explanation": "活用の誤り：「問う」の受身は「問われる」で、「問わられる」という形はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.valid