INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38077, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "経験の有無が問わない。", "corrected_sentence": "経験の有無は問わない。", "error_description": "助詞の混同：問わない対象を「が」で示すと主語になる。主題の「は」（または「を」）を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "問わ", "is_correct": true, "explanation": "否定の「ず」は未然形「問わ」に続き、「問わず」となる。"}, {"text": "問い", "is_correct": false, "explanation": "「問いず」という形はない。"}, {"text": "問う", "is_correct": false, "explanation": "辞書形に「ず」は付かない。"}, {"text": "問お", "is_correct": false, "explanation": "「問おず」という形はない。「お」は意向形「問おう」の形。"}], "correct_form": "問わ", "base_form": "問う", "form_label": "ない形（未然形）＋ず", "sentence_index": 7, "explanations": {"問わ": "否定の「ず」は未然形「問わ」に続き、「問わず」となる。", "問い": "「問いず」という形はない。", "問う": "辞書形に「ず」は付かない。", "問お": "「問おず」という形はない。「お」は意向形「問おう」の形。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
