INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36421, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "枠組み", "is_correct": true, "explanation": "音声「わくぐみ」の正しい表記。"}, {"text": "腕組み", "is_correct": false, "explanation": "「うでぐみ」と読み、前半「わく」が「うで」に変わる近い音。"}, {"text": "骨組み", "is_correct": false, "explanation": "「ほねぐみ」と読み、前半「わく」が「ほね」に変わる近い音。"}, {"text": "縁組み", "is_correct": false, "explanation": "「えんぐみ」と読み、前半「わく」が「えん」に変わる近い音。"}], "explanations": {"枠組み": "音声「わくぐみ」の正しい表記。", "腕組み": "「うでぐみ」と読み、前半「わく」が「うで」に変わる近い音。", "骨組み": "「ほねぐみ」と読み、前半「わく」が「ほね」に変わる近い音。", "縁組み": "「えんぐみ」と読み、前半「わく」が「えん」に変わる近い音。"}, "sentence_index": null, "correct_answer": "枠組み"}, "level_3": {"options": [{"text": "枠組み", "is_correct": true, "explanation": "文脈と義項に合う唯一の語。"}, {"text": "食器", "is_correct": false, "explanation": "意味：皿などの道具で、認識論的に構築するものではない"}, {"text": "雨傘", "is_correct": false, "explanation": "意味：雨具であり、考え方の構成を表さない"}, {"text": "喜び", "is_correct": false, "explanation": "連語：「認識論的喜びを構築する」は結びつかず不自然"}], "explanations": {"枠組み": "文脈と義項に合う唯一の語。", "食器": "意味：皿などの道具で、認識論的に構築するものではない", "雨傘": "意味：雨具であり、考え方の構成を表さない", "喜び": "連語：「認識論的喜びを構築する」は結びつかず不自然"}, "sentence_index": 0, "correct_answer": "枠組み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい枠組みが作る。", "explanation": "助詞の混同：作られる対象は「を」で示す。「が」では枠組みが作る主体になる。"}, {"text": "一匹の新しい枠組みを作る。", "explanation": "助数詞の誤り：抽象的な枠組みを動物の「匹」で数えることはできない。"}, {"text": "明日、新しい枠組みを作った。", "explanation": "活用・アスペクトの誤り：「明日」と過去形「作った」が矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6cc558f-73db-401b-8689-c005c553049a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_i