INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35035, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の回数や程度を表す言葉。「一度」「二度」のように回数を数える。", "primary_collocate": null, "pronunciation": "ど", "ipa": "do", "syllable_count": 1, "sentences": [{"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "度", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "大学教育の現場において、教授陣が個々の学修到達度を最大化するためにこのシステムを如何に設計し、運用するかが問われているのである。", "target_word": "度", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "それは幼い頃、何度も握りしめた懐かしい色だ。", "target_word": "度", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "その映画は何度見ても面白い。", "target_word": "度", "complexity_tier": "T3", "furigana": "なんど", "sentence_source": "generated"}, {"text": "もう一度言ってください。", "target_word": "度", "complexity_tier": "T3", "furigana": "いちど", "sentence_source": "generated"}, {"text": "この店には二度行きました。", "target_word": "度", "complexity_tier": "T3", "furigana": "にど", "sentence_source": "generated"}, {"text": "彼の冗談は度が過ぎている。", "target_word": "度", "complexity_tier": "T3", "furigana": "ど", "sentence_source": "generated"}, {"text": "一度だけ富士山に登った。", "target_word": "度", "complexity_tier": "T3", "furigana": "いちど", "sentence_source": "generated"}, {"text": "何度も練習して上手になった。", "target_word": "度", "complexity_tier": "T3", "furigana": "なんど", "sentence_source": "generated"}, {"text": "三度目の挑戦で試験に合格した。", "target_word": "度", "complexity_tier": "T3", "furigana": "さんど", "sentence_source": "generated"}], "morphological_forms": [{"form": "一度", "label": "派生"}, {"form": "何度", "label": "派生"}, {"form": "程度", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 回数や程度を表す語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 6 words above tier T1 (max 2): 文脈 (Zipf 3.63), アルゴリズム (Zipf 3.83), 習熟 (Zipf 2.99), 教材 (Zipf 3.84), 示唆 (Zipf 3.85), 富む (Zipf 2.88)','sentence 1 above tier T1: 3 words above tier T1 (max 2): 個々 (Zipf 3.92), 学修 (Zipf 2.76), 如何 (Zipf 3.96)']::text[], 'd520d28d-ccf1-4454-a3af-d2672d49a952') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39265, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "知識や技術を身につけるために学ぶこと。", "primary_collocate": null, "pronunciation": "がくしゅう", "ipa": "ɡakɯ̥ɕɯː", "syllable_count": 4, "sentences": [{"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "学習", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "教師の指示のもと、静寂を保ちつつも頭脳をフル回転させる学習の時間。", "target_word": "学習", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "毎日一時間、英語を学習している。", "target_word": "学習", "complexity_tier": "T3", "furigana": "がくしゅう", "sentence_source": "generated"}, {"text": "学習の計画を立てよう。", "target_word": "学習", "complexity_tier": "T3", "furigana": "がくしゅう", "sentence_source": "generated"}, {"text": "彼は熱心に数学を学習した。", "target_word": "学習", "complexity_tier": "T3", "furigana": "がくしゅう", "sentence_source": "generated"}, {"text": "学習には集中が大切だ。", "target_word": "学習", "complexity_tier": "T3", "furigana": "がくしゅう", "sentence_source": "generated"}, {"text": "図書館は学習に向いている。", "target_word": "学習", "complexity_tier": "T3", "furigana": "がくしゅう", "sentence_source": "generated"}, {"text": "学習した内容を復習する。", "target_word": "学習", "complexity_tier": "T3", "furigana": "がくしゅう", "sentence_source": "generated"}, {"text": "新しい学習方法を試した。", "target_word": "学習", "complexity_tier": "T3", "furigana": "がくしゅう", "sentence_source": "generated"}, {"text": "学習が進むと自信がつく。", "target_word": "学習", "complexity_tier": "T3", "furigana": "がくしゅう", "sentence_source": "generated"}], "morphological_forms": [{"form": "学習する", "label": "派生"}, {"form": "学習者", "label": "派生"}, {"form": "学習帳", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 知識や技術を学んで身につけること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd520d28d-ccf1-4454-a3af-d2672d49a952') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38119, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「どのようにして」という意味の言葉。方法や程度を問う。", "primary_collocate": null, "pronunciation": "いかに", "ipa": "ikaɲi", "syllable_count": 3, "sentences": [{"text": "大学教育の現場において、教授陣が個々の学修到達度を最大化するためにこのシステムを如何に設計し、運用するかが問われているのである。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "多忙な現代の専門職に就く我々にとって、オフィスや書斎で迎える限られた昼食の時間はいかにして精神的・肉体的充足へと転換され得るだろうか。", "target_word": "いかに", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "問題を如何に解くかを考えた。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "いかに", "sentence_source": "generated"}, {"text": "時間を如何に使うかが大切だ。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "いかに", "sentence_source": "generated"}, {"text": "彼は如何にして成功したのか。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "いかに", "sentence_source": "generated"}, {"text": "如何に伝えるかで結果が変わる。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "いかに", "sentence_source": "generated"}, {"text": "如何に生きるべきか悩んだ。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "いかに", "sentence_source": "generated"}, {"text": "ごみを如何に減らせるだろうか。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "いかに", "sentence_source": "generated"}, {"text": "如何に早く走れるか試した。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "いかに", "sentence_source": "generated"}, {"text": "友達と如何に話すか考える。", "target_word": "如何に", "complexity_tier": "T3", "furigana": "いかに", "sentence_source": "generated"}], "morphological_forms": [{"form": "いかに", "label": "派生"}, {"form": "如何にして", "label": "派生"}, {"form": "如何にも", "label": "派生"}], "register": "formal", "sense_fingerprint": "副詞 | どのようにして・方法を問う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd520d28d-ccf1-4454-a3af-d2672d49a952') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35329, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "前の方へ移動する。また、物事がはかどる。", "primary_collocate": null, "pronunciation": "すすむ", "ipa": "sɯsɯmɯ", "syllable_count": 3, "sentences": [{"text": "現在、オフィスでの定型業務の自動化が進み、AIがホワイトカラーの雇用を代替する時代となっている。", "target_word": "進み", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "酵母の活動を観察しながら生地を仕上げ、いよいよ焼成へと進みます。", "target_word": "進み", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "道をまっすぐ進んでください。", "target_word": "進ん", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "工事が予定どおり進んだ。", "target_word": "進ん", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "列がなかなか進まない。", "target_word": "進ま", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "船はゆっくり北へ進む。", "target_word": "進む", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "宿題が少しずつ進んでいる。", "target_word": "進ん", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "前に進むのが怖かった。", "target_word": "進む", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "話し合いがうまく進んだ。", "target_word": "進ん", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "彼は次の試合に進んだ。", "target_word": "進ん", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}], "morphological_forms": [{"form": "進んだ", "label": "活用"}, {"form": "進んで", "label": "活用"}, {"form": "進まない", "label": "活用"}, {"form": "進める", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 前へ移動する・物事がはかどる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 