INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39449, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今この時。話している時点。", "primary_collocate": null, "pronunciation": "げんざい", "ipa": "ɡeɴzai", "syllable_count": 4, "sentences": [{"text": "現在、オフィスでの定型業務の自動化が進み、AIがホワイトカラーの雇用を代替する時代となっている。", "target_word": "現在", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "しかし、その無骨な外観や維持管理の難しさから、現在ではその価値が再評価される一方で、取り壊されるケースも増えています。", "target_word": "現在", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "現在の気温は二十度です。", "target_word": "現在", "complexity_tier": "T3", "furigana": "げんざい", "sentence_source": "generated"}, {"text": "彼は現在、東京に住んでいる。", "target_word": "現在", "complexity_tier": "T3", "furigana": "げんざい", "sentence_source": "generated"}, {"text": "現在の時刻を教えてください。", "target_word": "現在", "complexity_tier": "T3", "furigana": "げんざい", "sentence_source": "generated"}, {"text": "現在まで連絡はない。", "target_word": "現在", "complexity_tier": "T3", "furigana": "げんざい", "sentence_source": "generated"}, {"text": "過去と現在を比べてみた。", "target_word": "現在", "complexity_tier": "T3", "furigana": "げんざい", "sentence_source": "generated"}, {"text": "現在、店は休んでいます。", "target_word": "現在", "complexity_tier": "T3", "furigana": "げんざい", "sentence_source": "generated"}, {"text": "現在の生活に満足している。", "target_word": "現在", "complexity_tier": "T3", "furigana": "げんざい", "sentence_source": "generated"}, {"text": "現在は図書館で働いている。", "target_word": "現在", "complexity_tier": "T3", "furigana": "げんざい", "sentence_source": "generated"}], "morphological_forms": [{"form": "現在形", "label": "派生"}, {"form": "現在地", "label": "派生"}, {"form": "現在進行形", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 今この時・話している時点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code