INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51492, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "会社などで、事務や仕事をするための部屋や建物。", "primary_collocate": null, "pronunciation": "おふぃす", "ipa": "ofisɯ", "syllable_count": 3, "sentences": [{"text": "現在、オフィスでの定型業務の自動化が進み、AIがホワイトカラーの雇用を代替する時代となっている。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "多忙な現代の専門職に就く我々にとって、オフィスや書斎で迎える限られた昼食の時間はいかにして精神的・肉体的充足へと転換され得るだろうか。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "父は毎朝オフィスへ行く。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "新しいオフィスはとても広い。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "あたら ひろ", "sentence_source": "generated"}, {"text": "オフィスで昼ご飯を食べた。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "ひる はん た", "sentence_source": "generated"}, {"text": "駅の近くにオフィスがある。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "えき ちか", "sentence_source": "generated"}, {"text": "オフィスの窓から海が見える。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "まど うみ み", "sentence_source": "generated"}, {"text": "彼女はオフィスで働いている。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "かのじょ はたら", "sentence_source": "generated"}, {"text": "オフィスを掃除しました。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "そうじ", "sentence_source": "generated"}, {"text": "今日はオフィスに誰もいない。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "きょう だれ", "sentence_source": "generated"}], "morphological_forms": [{"form": "オフィス街", "label": "派生"}, {"form": "オフィスビル", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 仕事をするための部屋や建物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"