INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35035, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "度", "is_correct": true, "explanation": "正解。「ど」と読む。"}, {"text": "戸", "is_correct": false, "explanation": "「と」と読み、一モーラ目が清音で違う（ど→と）。"}, {"text": "野", "is_correct": false, "explanation": "「の」と読み、子音が違う一モーラ差（ど→の）。"}, {"text": "銅", "is_correct": false, "explanation": "「どう」と読み、長母音の有無が違う（ど→どう）。"}, {"text": "碁", "is_correct": false, "explanation": "「ご」と読み、子音が違う一モーラ差（ど→ご）。"}], "explanations": {"度": "正解。「ど」と読む。", "戸": "「と」と読み、一モーラ目が清音で違う（ど→と）。", "野": "「の」と読み、子音が違う一モーラ差（ど→の）。", "銅": "「どう」と読み、長母音の有無が違う（ど→どう）。", "碁": "「ご」と読み、子音が違う一モーラ差（ど→ご）。"}, "sentence_index": null, "correct_answer": "度"}, "level_3": {"options": [{"text": "度", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "者", "is_correct": false, "explanation": "意味：「習熟者分析」では人を指し、程度の意味にならない。"}, {"text": "家", "is_correct": false, "explanation": "意味：「習熟家」は人を表し、分析の対象として不自然。"}, {"text": "会", "is_correct": false, "explanation": "連語：「習熟会分析」という結びつきはない。"}], "explanations": {"度": "正解。文の意味に合う。", "者": "意味：「習熟者分析」では人を指し、程度の意味にならない。", "家": "意味：「習熟家」は人を表し、分析の対象として不自然。", "会": "連語：「習熟会分析」という結びつきはない。"}, "sentence_index": 0, "correct_answer": "度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その映画は何度を見ても面白い。", "explanation": "助詞の誤り：回数の「何度」に「を」は付かない。"}, {"text": "その映画は三本度見た。", "explanation": "助数詞の誤り：回数は「三度」で、「本」と重ねない。"}, {"text": "その映画は何回度見ても面白い。", "explanation": "助数詞の誤り：「回」と「度」を重ねない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
