INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35035, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "度", "is_correct": true, "explanation": "正解。「ど」と読む。"}, {"text": "炉", "is_correct": false, "explanation": "「ろ」と読み、音が近いが別の語。"}, {"text": "胴", "is_correct": false, "explanation": "「どう」と読み、音が近いが別の語。"}, {"text": "祖", "is_correct": false, "explanation": "「そ」と読み、音が近いが別の語。"}, {"text": "夜", "is_correct": false, "explanation": "「よ」と読み、音が近いが別の語。"}], "explanations": {"度": "正解。「ど」と読む。", "炉": "「ろ」と読み、音が近いが別の語。", "胴": "「どう」と読み、音が近いが別の語。", "祖": "「そ」と読み、音が近いが別の語。", "夜": "「よ」と読み、音が近いが別の語。"}, "sentence_index": null, "correct_answer": "度"}, "level_3": {"options": [{"text": "度", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "色", "is_correct": false, "explanation": "意味：「色が過ぎる」とは言わない。"}, {"text": "声", "is_correct": false, "explanation": "意味：「声が過ぎる」という表現はない。"}, {"text": "目", "is_correct": false, "explanation": "意味：「目が過ぎる」という表現はない。"}], "explanations": {"度": "正解。文の意味に合う。", "色": "意味：「色が過ぎる」とは言わない。", "声": "意味：「声が過ぎる」という表現はない。", "目": "意味：「目が過ぎる」という表現はない。"}, "sentence_index": 6, "correct_answer": "度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三度目を挑戦で試験に合格した。", "explanation": "助詞の誤り：「三度目の挑戦」の「の」を「を」にはできない。"}, {"text": "三回度目の挑戦で試験に合格した。", "explanation": "助数詞の誤り：「回」と「度」を重ねない。"}, {"text": "試験に三度目の合格した挑戦で。", "explanation": "語順の誤り：「三度目の」が「挑戦」を修飾できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
