INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39265, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学習", "is_correct": true, "explanation": "正解。「がくしゅう」と読む。"}, {"text": "隔週", "is_correct": false, "explanation": "「かくしゅう」と読み、清濁の違い（が→か）。"}, {"text": "学友", "is_correct": false, "explanation": "「がくゆう」と読み、一モーラ差（しゅ→ゆ）。"}, {"text": "学長", "is_correct": false, "explanation": "「がくちょう」と読み、一モーラ差（しゅ→ちょ）。"}, {"text": "学僧", "is_correct": false, "explanation": "「がくそう」と読み、一モーラ差（しゅ→そ）。"}], "explanations": {"学習": "正解。「がくしゅう」と読む。", "隔週": "「かくしゅう」と読み、清濁の違い（が→か）。", "学友": "「がくゆう」と読み、一モーラ差（しゅ→ゆ）。", "学長": "「がくちょう」と読み、一モーラ差（しゅ→ちょ）。", "学僧": "「がくそう」と読み、一モーラ差（しゅ→そ）。"}, "sentence_index": null, "correct_answer": "学習"}, "level_3": {"options": [{"text": "学習", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "運動", "is_correct": false, "explanation": "意味：「運動者の認知特性」は教育の文脈に合わない。"}, {"text": "消費", "is_correct": false, "explanation": "意味：「消費者」は教材の対象として不自然。"}, {"text": "経営", "is_correct": false, "explanation": "意味：「経営者」は学ぶ人を表さない。"}], "explanations": {"学習": "正解。文の意味に合う。", "運動": "意味：「運動者の認知特性」は教育の文脈に合わない。", "消費": "意味：「消費者」は教材の対象として不自然。", "経営": "意味：「経営者」は学ぶ人を表さない。"}, "sentence_index": 0, "correct_answer": "学習"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学習を計画の立てよう。", "explanation": "助詞の誤り：「学習の計画を」が正しい。"}, {"text": "学習の計画を一枚立てよう。", "explanation": "助数詞の誤り：計画に「枚」は使わない。"}, {"text": "学習の計画を立てていよう。", "explanation": "アスペクトの誤り：意志を表すなら「立てよう」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
