INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38119, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "如何に", "is_correct": true, "explanation": "正解。「いかに」と読む。"}, {"text": "如何", "is_correct": false, "explanation": "「いかが」と読み、三モーラ目が違う（に→が）。"}, {"text": "筏", "is_correct": false, "explanation": "「いかだ」と読み、三モーラ目が違う（に→だ）。"}, {"text": "遺憾", "is_correct": false, "explanation": "「いかん」と読み、三モーラ目が違う（に→ん）。"}, {"text": "怒り", "is_correct": false, "explanation": "「いかり」と読み、三モーラ目が違う（に→り）。"}], "explanations": {"如何に": "正解。「いかに」と読む。", "如何": "「いかが」と読み、三モーラ目が違う（に→が）。", "筏": "「いかだ」と読み、三モーラ目が違う（に→だ）。", "遺憾": "「いかん」と読み、三モーラ目が違う（に→ん）。", "怒り": "「いかり」と読み、三モーラ目が違う（に→り）。"}, "sentence_index": null, "correct_answer": "如何に"}, "level_3": {"options": [{"text": "如何に", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "決して", "is_correct": false, "explanation": "意味：否定を伴う副詞で、方法を問えない。"}, {"text": "たぶん", "is_correct": false, "explanation": "意味：推量を表し、「〜か」の問いに合わない。"}, {"text": "すでに", "is_correct": false, "explanation": "アスペクト：完了を表し、方法を問う文に合わない。"}], "explanations": {"如何に": "正解。文の意味に合う。", "決して": "意味：否定を伴う副詞で、方法を問えない。", "たぶん": "意味：推量を表し、「〜か」の問いに合わない。", "すでに": "アスペクト：完了を表し、方法を問う文に合わない。"}, "sentence_index": 0, "correct_answer": "如何に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時間が如何に使うかが大切だ。", "explanation": "助詞の誤り：「使う」の目的語は「を」。"}, {"text": "時間を如何に使ったかが大切だっている。", "explanation": "活用の誤り：「だっている」は非文。"}, {"text": "如何に時間を大切だ使うか。", "explanation": "語順の誤り：係り受けが壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, gen