INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38119, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "如何に", "is_correct": true, "explanation": "正解。「いかに」と読む。"}, {"text": "以下", "is_correct": false, "explanation": "「いか」と読み、音が近いが別の語。"}, {"text": "位階", "is_correct": false, "explanation": "「いかい」と読み、音が近いが別の語。"}, {"text": "威嚇", "is_correct": false, "explanation": "「いかく」と読み、音が近いが別の語。"}], "explanations": {"如何に": "正解。「いかに」と読む。", "以下": "「いか」と読み、音が近いが別の語。", "位階": "「いかい」と読み、音が近いが別の語。", "威嚇": "「いかく」と読み、音が近いが別の語。"}, "sentence_index": null, "correct_answer": "如何に"}, "level_3": {"options": [{"text": "如何に", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "すでに", "is_correct": false, "explanation": "意味：完了を表し、「〜べきか」の問いに合わない。"}, {"text": "全然", "is_correct": false, "explanation": "連語：否定と結びつく語で、ここでは不自然。"}, {"text": "もう", "is_correct": false, "explanation": "意味：方法を問う意味にならない。"}], "explanations": {"如何に": "正解。文の意味に合う。", "すでに": "意味：完了を表し、「〜べきか」の問いに合わない。", "全然": "連語：否定と結びつく語で、ここでは不自然。", "もう": "意味：方法を問う意味にならない。"}, "sentence_index": 6, "correct_answer": "如何に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達を如何に話すか考える。", "explanation": "助詞の誤り：相手は「と」で表す。"}, {"text": "友達と如何に話したか考えている前に。", "explanation": "語順・係り受けの誤り：文として成立しない。"}, {"text": "如何に友達と話すか考えるでした。", "explanation": "活用の誤り：「考えるでした」は非文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
