INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35329, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "進む", "is_correct": true, "explanation": "正解。「すすむ」と読む。"}, {"text": "涼む", "is_correct": false, "explanation": "「すずむ」と読み、清濁の違い（す→ず）。"}, {"text": "濯ぐ", "is_correct": false, "explanation": "「すすぐ」と読み、最後のモーラが違う（む→ぐ）。"}, {"text": "荒む", "is_correct": false, "explanation": "「すさむ」と読み、二モーラ目が違う（す→さ）。"}], "explanations": {"進む": "正解。「すすむ」と読む。", "涼む": "「すずむ」と読み、清濁の違い（す→ず）。", "濯ぐ": "「すすぐ」と読み、最後のモーラが違う（む→ぐ）。", "荒む": "「すさむ」と読み、二モーラ目が違う（す→さ）。"}, "sentence_index": null, "correct_answer": "進む"}, "level_3": {"options": [{"text": "進み", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "止まり", "is_correct": false, "explanation": "意味：「自動化が止まり」では時代の説明と矛盾する。"}, {"text": "戻り", "is_correct": false, "explanation": "意味：自動化が戻るとは言わない。"}, {"text": "休み", "is_correct": false, "explanation": "連語：「自動化が休む」は不自然。"}], "explanations": {"進み": "正解。文の意味に合う。", "止まり": "意味：「自動化が止まり」では時代の説明と矛盾する。", "戻り": "意味：自動化が戻るとは言わない。", "休み": "連語：「自動化が休む」は不自然。"}, "sentence_index": 0, "correct_answer": "進み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工事を予定どおり進んだ。", "explanation": "助詞の誤り：自動詞「進む」に「を」は使えない。"}, {"text": "工事が予定どおり進めた。", "explanation": "自他の誤り：「工事が」には自動詞「進む」を使う。"}, {"text": "予定どおり工事が進むだ。", "explanation": "活用の誤り：「進むだ」は非文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35329, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "道をまっすぐ進むでください。", "corrected_sentence": "道をまっすぐ進んでください。", "error_description": "活用の誤り：「ください」の前はて形「進んで」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "進み", "is_correct": true, "explanation": "「ます」に続く連用形。"}, {"text": "進ん", "is_correct": false, "explanation": "「ます」の前には来ない音便形。"}, {"text": "進ま", "is_correct": false, "explanation": "未然形で「ます」に続かない。"}, {"text": "進む", "is_correct": false, "explanation": "終止形で「ます」に続かない。"}], "correct_form": "進み", "base_form": "進む", "form_label": "活用", "sentence_index": 1, "explanations": {"進み": "「ます」に続く連用形。", "進ん": "「ます」の前には来ない音便形。", "進ま": "未然形で「ます」に続かない。", "進む": "終止形で「ます」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35329, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置で文法的に正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「仕上げる」の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "対象を表せず非文。"}, {"text": "で", "is_correct": false, "explanation": "手段の意になり不自然。"}], "correct_answer": "を", "explanations": {"を": "この位置で文法的に正しい助詞。", "が": "「仕上げる」の目的語にならない。", "に": "対象を表せず非文。", "で": "手段の意になり不自然。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遅れた", "is_correct": true, "explanation": "対義：予定より進まないこと。"}, {"text": "終わった", "is_correct": false, "explanation": "工事が終わるのは進むことの反対ではない。"}, {"text": "始まった", "is_correct": false, "explanation": "開始を表し、対義ではない。"}, {"text": "続いた", "is_correct": false, "explanation": "継続を表し、対義ではない。"}], "correct_answer": "遅れた", "explanations": {"遅れた": "対義：予定より進まないこと。", "終わった": "工事が終わるのは進むことの反対ではない。", "始まった": "開始を表し、対義ではない。", "続いた": "継続を表し、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35329, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "進む", "is_correct": true, "explanation": "正解。「すすむ」と読む。"}, {"text": "住む", "is_correct": false, "explanation": "「すむ」と読み、音が近いが別の語。"}, {"text": "煤", "is_correct": false, "explanation": "「すす」と読み、音が近いが別の語。"}, {"text": "鈴", "is_correct": false, "explanation": "「すず」と読み、音が近いが別の語。"}], "explanations": {"進む": "正解。「すすむ」と読む。", "住む": "「すむ」と読み、音が近いが別の語。", "煤": "「すす」と読み、音が近いが別の語。", "鈴": "「すず」と読み、音が近いが別の語。"}, "sentence_index": null, "correct_answer": "進む"}, "level_3": {"options": [{"text": "進ん", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "遊ん", "is_correct": false, "explanation": "意味：宿題が遊ぶことはない。"}, {"text": "休ん", "is_correct": false, "explanation": "意味：宿題が休むことはない。"}, {"text": "読ん", "is_correct": false, "explanation": "項構造：宿題が主語では「読んでいる」は成り立たない。"}], "explanations": {"進ん": "正解。文の意味に合う。", "遊ん": "意味：宿題が遊ぶことはない。", "休ん": "意味：宿題が休むことはない。", "読ん": "項構造：宿題が主語では「読んでいる」は成り立たない。"}, "sentence_index": 6, "correct_answer": "進ん"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は次の試合を進んだ。", "explanation": "助詞の誤り：目標は「に」で表す。"}, {"text": "彼は次の試合に進んでいた前。", "explanation": "語順の誤り：文として成立しない。"}, {"text": "彼は次の試合に進むだった。", "explanation": "活用の誤り：「進むだった」は非文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35329, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前で進むのが怖かった。", "corrected_sentence": "前に進むのが怖かった。", "error_description": "助詞の誤り：方向は「で」ではなく「に」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "進む", "is_correct": true, "explanation": "「の」に続く連体形。"}, {"text": "進み", "is_correct": false, "explanation": "連用形は「の」に続かない。"}, {"text": "進んで", "is_correct": false, "explanation": "て形は「の」に続かない。"}, {"text": "進もう", "is_correct": false, "explanation": "意志形は「の」に続かない。"}], "correct_form": "進む", "base_form": "進む", "form_label": "活用", "sentence_index": 7, "explanations": {"進む": "「の」に続く連体形。", "進み": "連用形は「の」に続かない。", "進んで": "て形は「の」に続かない。", "進もう": "意志形は「の」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35329, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "この位置で文法的に正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「怖い」の対象は「が」で表す。"}, {"text": "に", "is_correct": false, "explanation": "対象を表せず非文。"}, {"text": "で", "is_correct": false, "explanation": "手段の意になり非文。"}], "correct_answer": "が", "explanations": {"が": "この位置で文法的に正しい助詞。", "を": "「怖い」の対象は「が」で表す。", "に": "対象を表せず非文。", "で": "手段の意になり非文。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "退いた", "is_correct": true, "explanation": "対義：前へ進むの反対で、後ろへ下がること。"}, {"text": "勝った", "is_correct": false, "explanation": "勝つと次に進むので対義ではない。"}, {"text": "出た", "is_correct": false, "explanation": "試合に出るのは対義ではない。"}, {"text": "選ばれた", "is_correct": false, "explanation": "選ばれて進むので対義ではない。"}], "correct_answer": "退いた", "explanations": {"退いた": "対義：前へ進むの反対で、後ろへ下がること。", "勝った": "勝つと次に進むので対義ではない。", "出た": "試合に出るのは対義ではない。", "選ばれた": "選ばれて進むので対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39449, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "現在", "is_correct": true, "explanation": "正解。「げんざい」と読む。"}, {"text": "健在", "is_correct": false, "explanation": "「けんざい」と読み、一モーラ目の清濁が違う（げ→け）。"}, {"text": "限界", "is_correct": false, "explanation": "「げんかい」と読み、三モーラ目が違う（ざ→か）。"}, {"text": "洗剤", "is_correct": false, "explanation": "「せんざい」と読み、一モーラ目が違う（げ→せ）。"}, {"text": "減税", "is_correct": false, "explanation": "「げんぜい」と読み、三モーラ目が違う（ざ→ぜ）。"}], "explanations": {"現在": "正解。「げんざい」と読む。", "健在": "「けんざい」と読み、一モーラ目の清濁が違う（げ→け）。", "限界": "「げんかい」と読み、三モーラ目が違う（ざ→か）。", "洗剤": "「せんざい」と読み、一モーラ目が違う（げ→せ）。", "減税": "「げんぜい」と読み、三モーラ目が違う（ざ→ぜ）。"}, "sentence_index": null, "correct_answer": "現在"}, "level_3": {"options": [{"text": "現在", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "昔", "is_correct": false, "explanation": "意味：「時代となっている」と合わない。"}, {"text": "昨日", "is_correct": false, "explanation": "意味：一日だけでは時代の変化を表せない。"}, {"text": "来年", "is_correct": false, "explanation": "アスペクト：未来なのに「なっている」と合わない。"}], "explanations": {"現在": "正解。文の意味に合う。", "昔": "意味：「時代となっている」と合わない。", "昨日": "意味：一日だけでは時代の変化を表せない。", "来年": "アスペクト：未来なのに「なっている」と合わない。"}, "sentence_index": 0, "correct_answer": "現在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は現在に、東京に住んでいる。", "explanation": "助詞の誤り：副詞的な「現在」に「に」は不要。"}, {"text": "彼は現在、東京に住んだ。", "explanation": "アスペクトの誤り：今の状態は「住んでいる」。"}, {"text": "彼は現代、東京に住んでいる。", "explanation": "語彙の誤り：個人の今の状態には「現代」ではなく「現在」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
