INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39449, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "この位置で文法的に正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "理由を表せず非文。"}, {"text": "が", "is_correct": false, "explanation": "理由を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、理由にならない。"}], "correct_answer": "から", "explanations": {"から": "この位置で文法的に正しい助詞。", "を": "理由を表せず非文。", "が": "理由を表せない。", "へ": "方向を表し、理由にならない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "過去", "is_correct": true, "explanation": "対義：今より前の時。"}, {"text": "今", "is_correct": false, "explanation": "類義であり対義ではない。"}, {"text": "最近", "is_correct": false, "explanation": "今に近い時で対義ではない。"}, {"text": "当時", "is_correct": false, "explanation": "特定の時点を指すが、今の対義語ではない。"}], "correct_answer": "過去", "explanations": {"過去": "対義：今より前の時。", "今": "類義であり対義ではない。", "最近": "今に近い時で対義ではない。", "当時": "特定の時点を指すが、今の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39449, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "現在", "is_correct": true, "explanation": "正解。「げんざい」と読む。"}, {"text": "減退", "is_correct": false, "explanation": "「げんたい」と読み、音が近いが別の語。"}, {"text": "現代", "is_correct": false, "explanation": "「げんだい」と読み、音が近いが別の語。"}, {"text": "散在", "is_correct": false, "explanation": "「さんざい」と読み、音が近いが別の語。"}], "explanations": {"現在": "正解。「げんざい」と読む。", "減退": "「げんたい」と読み、音が近いが別の語。", "現代": "「げんだい」と読み、音が近いが別の語。", "散在": "「さんざい」と読み、音が近いが別の語。"}, "sentence_index": null, "correct_answer": "現在"}, "level_3": {"options": [{"text": "現在", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "名前", "is_correct": false, "explanation": "意味：「過去と名前」は時の対比にならない。"}, {"text": "毎日", "is_correct": false, "explanation": "意味：時の対比にならない。"}, {"text": "場所", "is_correct": false, "explanation": "意味：時ではなく比較が成り立たない。"}], "explanations": {"現在": "正解。文の意味に合う。", "名前": "意味：「過去と名前」は時の対比にならない。", "毎日": "意味：時の対比にならない。", "場所": "意味：時ではなく比較が成り立たない。"}, "sentence_index": 6, "correct_answer": "現在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "現在を図書館で働いている。", "explanation": "助詞の誤り：「現在」に「を」は付かない。"}, {"text": "現在は図書館に働いている。", "explanation": "助詞の誤り：動作の場所は「で」。"}, {"text": "現在は図書館で働いた。", "explanation": "アスペクトの誤り：今の状態は「働いている」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
