INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51492, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "オフィス", "is_correct": true, "explanation": "正解。「おふぃす」と読む。"}, {"text": "落とす", "is_correct": false, "explanation": "「おとす」と読み、二モーラ目が違う（ふぃ→と）。"}, {"text": "下ろす", "is_correct": false, "explanation": "「おろす」と読み、二モーラ目が違う（ふぃ→ろ）。"}, {"text": "脅す", "is_correct": false, "explanation": "「おどす」と読み、二モーラ目が違う（ふぃ→ど）。"}], "explanations": {"オフィス": "正解。「おふぃす」と読む。", "落とす": "「おとす」と読み、二モーラ目が違う（ふぃ→と）。", "下ろす": "「おろす」と読み、二モーラ目が違う（ふぃ→ろ）。", "脅す": "「おどす」と読み、二モーラ目が違う（ふぃ→ど）。"}, "sentence_index": null, "correct_answer": "オフィス"}, "level_3": {"options": [{"text": "オフィス", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "公園", "is_correct": false, "explanation": "意味：定型業務の自動化の場として合わない。"}, {"text": "海", "is_correct": false, "explanation": "意味：業務を行う場所ではない。"}, {"text": "台所", "is_correct": false, "explanation": "意味：会社の業務の場ではない。"}], "explanations": {"オフィス": "正解。文の意味に合う。", "公園": "意味：定型業務の自動化の場として合わない。", "海": "意味：業務を行う場所ではない。", "台所": "意味：会社の業務の場ではない。"}, "sentence_index": 0, "correct_answer": "オフィス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しいオフィスをとても広い。", "explanation": "助詞の誤り：形容詞の主題は「は」。"}, {"text": "新しいオフィスはとても広かっている。", "explanation": "活用の誤り：「広かっている」は非文。"}, {"text": "新しい一匹のオフィスは広い。", "explanation": "助数詞の誤り：建物に「匹」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c0097a-2107-41f4-930d-a48305be5056') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
