INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37187, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が操作しなくても、機械などが自分で動くこと。", "primary_collocate": null, "pronunciation": "じどう", "ipa": "dʑidoː", "syllable_count": 3, "sentences": [{"text": "現在、オフィスでの定型業務の自動化が進み、AIがホワイトカラーの雇用を代替する時代となっている。", "target_word": "自動", "complexity_tier": "T3", "furigana": "げんざい ていけい ぎょうむ じどう か すす こよう だいたい じだい", "sentence_source": "mined"}, {"text": "これは、日照や風通しなどの環境データを変数としてアルゴリズムに入力し、最適な街区配置を自動的に生成する手法です。", "target_word": "自動", "complexity_tier": "T3", "furigana": "にっしょう かざとお かんきょう へんすう にゅうりょく さいてき がいく はいち じどう てき せいせい しゅほう", "sentence_source": "mined"}, {"text": "このドアは自動で開きます。", "target_word": "自動", "complexity_tier": "T3", "furigana": "じどう ひら", "sentence_source": "generated"}, {"text": "電気は夜に自動でつく。", "target_word": "自動", "complexity_tier": "T3", "furigana": "でんき よる じどう", "sentence_source": "generated"}, {"text": "自動の洗濯機はとても便利だ。", "target_word": "自動", "complexity_tier": "T3", "furigana": "じどう せんたくき べんり", "sentence_source": "generated"}, {"text": "このカメラは自動で写真をとる。", "target_word": "自動", "complexity_tier": "T3", "furigana": "じどう しゃしん", "sentence_source": "generated"}, {"text": "駅の改札は自動になっている。", "target_word": "自動", "complexity_tier": "T3", "furigana": "えき かいさつ じどう", "sentence_source": "generated"}, {"text": "データは毎日自動で保存される。", "target_word": "自動", "complexity_tier": "T3", "furigana": "まいにち じどう ほぞん", "sentence_source": "generated"}, {"text": "この機械は自動と手動を選べる。", "target_word": "自動", "complexity_tier": "T3", "furigana": "きかい じどう しゅどう えら", "sentence_source": "generated"}, {"text": "部屋の温度を自動で調整する。", "target_word": "自動", "complexity_tier": "T3", "furigana": "へや おんど じどう ちょうせい", "sentence_source": "generated"}], "morphological_forms": [{"form": "自動的", "label": "派生"}, {"form": "自動化", "label": "派生"}, {"form": "自動車", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 機械が人の操作なしに動くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33268c7d-6a9e-4208-aea5-f237b3a0425e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37475, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "周りの状況や変化に合わせて、自分を合った状態に変えること。", "primary_collocate": null, "pronunciation": "てきおう", "ipa": "tekioː", "syllable_count": 4, "sentences": [{"text": "変化に適応し、自らの価値を高め続ける姿勢が、これからの職場では強く求められる。", "target_word": "適応", "complexity_tier": "T3", "furigana": "へんか てきおう みずか かち たか つづ しせい しょくば つよ もと", "sentence_source": "mined"}, {"text": "むしろ、それらの相互作用が織りなす複雑適応システムにおいては、正負のフィードバックを介した非線形なダイナミクスが、予測不可能なマクロな秩序、すなわち創発をもたらすのである。", "target_word": "適応", "complexity_tier": "T3", "furigana": "そうご さよう お ふくざつ てきおう せいふ かい ひせんけい よそく ふかのう ちつじょ そうはつ", "sentence_source": "mined"}, {"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "適応", "complexity_tier": "T3", "furigana": "むすう しゅたい かぎ じょうほう もと た てきおう く かえ かてい いと とっぱつてき けんげん ほか", "sentence_source": "mined"}, {"text": "新しい学校に適応するのは大変だ。", "target_word": "適応", "complexity_tier": "T3", "furigana": "あたら がっこう てきおう たいへん", "sentence_source": "generated"}, {"text": "動物は寒さに適応している。", "target_word": "適応", "complexity_tier": "T3", "furigana": "どうぶつ さむ てきおう", "sentence_source": "generated"}, {"text": "彼は新しい環境に早く適応できた。", "target_word": "適応", "complexity_tier": "T3", "furigana": "かれ あたら かんきょう はや てきおう", "sentence_source": "generated"}, {"text": "子どもは適応する力が強い。", "target_word": "適応", "complexity_tier": "T3", "furigana": "こ てきおう ちから つよ", "sentence_source": "generated"}, {"text": "外国の生活への適応に時間がかかった。", "target_word": "適応", "complexity_tier": "T3", "furigana": "がいこく せいかつ てきおう じかん", "sentence_source": "generated"}, {"text": "植物は砂漠の暑さに適応した。", "target_word": "適応", "complexity_tier": "T3", "furigana": "しょくぶつ さばく あつ てきおう", "sentence_source": "generated"}, {"text": "適応には少し時間が必要だ。", "target_word": "適応", "complexity_tier": "T3", "furigana": "てきおう すこ じかん ひつよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "適応する", "label": "派生"}, {"form": "適応力", "label": "派生"}, {"form": "適応性", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 環境の変化に合わせて自分を変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: 5 words above tier T3 (max 3): 織りなす (Zipf 2.63), 正負 (Zipf 2.09), 非線形 (Zipf 2.6), ダイナミクス (Zipf 2.32), 創発 (Zipf 2.41)']::text[], '33268c7d-6a9e-4208-aea5-f237b3a0425e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36329, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事に取り組むときの心構えや態度。", "primary_collocate": null, "pronunciation": "しせい", "ipa": "ɕiseː", "syllable_count": 3, "sentences": [{"text": "変化に適応し、自らの価値を高め続ける姿勢が、これからの職場では強く求められる。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "へんか てきおう みずか かち たか つづ しせい しょくば つよ もと", "sentence_source": "mined"}, {"text": "まさに、大地と対話するその姿勢こそが、未来を担う魂の育成に他ならないのだろう。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "だいち たいわ しせい みらい にな たましい いくせい ほか", "sentence_source": "mined"}, {"text": "彼の前向きな姿勢が好きだ。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "かれ まえむ しせい す", "sentence_source": "generated"}, {"text": "学ぶ姿勢を大切にしている。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "まな しせい たいせつ", "sentence_source": "generated"}, {"text": "先生は生徒の学ぶ姿勢をほめた。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "せんせい せいと しせい", "sentence_source": "generated"}, {"text": "その姿勢は多くの人に伝わった。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "しせい おお ひと つた", "sentence_source": "generated"}, {"text": "仕事に取り組む姿勢が変わった。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "しごと と く しせい か", "sentence_source": "generated"}, {"text": "彼女はいつも真面目な姿勢でいる。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "かのじょ まじめ しせい", "sentence_source": "generated"}, {"text": "協力する姿勢を見せてほしい。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "きょうりょく しせい み", "sentence_source": "generated"}, {"text": "会社の姿勢が問われている。", "target_word": "姿勢", "complexity_tier": "T3", "furigana": "かいしゃ しせい と", "sentence_source": "generated"}], "morphological_forms": [{"form": "前向きな姿勢", "label": "派生"}, {"form": "低姿勢", "label": "派生"}, {"form": "高姿勢", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事に取り組む心構えや態度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33268c7d-6a9e-4208-aea5-f237b3a0425e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36593, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "複雑ではなく、要素や仕組みが少ないさま。わかりやすいこと。", "primary_collocate": null, "pronunciation": "たんじゅん", "ipa": "taɲdʑɯɴ", "syllable_count": 4, "sentences": [{"text": "企業は、単純な作業だけでなく、創造性や対人スキルを求められる役割へ従業員をシフトさせなければならない。", "target_word": "単純", "complexity_tier": "T3", "furigana": "きぎょう たんじゅん さぎょう そうぞうせい たいじん もと やくわり じゅうぎょういん", "sentence_source": "mined"}, {"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "単純", "complexity_tier": "T3", "furigana": "きんゆう しじょう しゃかい けいざいてき ぶんみゃく ここ きぎょう とうしか しゅたい きょくしょてき いし けってい けっ たんじゅん せんけい とら", "sentence_source": "mined"}, {"text": "このゲームのルールは単純だ。", "target_word": "単純", "complexity_tier": "T3", "furigana": "たんじゅん", "sentence_source": "generated"}, {"text": "答えは思ったより単純だった。", "target_word": "単純", "complexity_tier": "T3", "furigana": "こた おも たんじゅん", "sentence_source": "generated"}, {"text": "単純に考えればいい。", "target_word": "単純", "complexity_tier": "T3", "furigana": "たんじゅん かんが", "sentence_source": "generated"}, {"text": "この機械は仕組みが単純だ。", "target_word": "単純", "complexity_tier": "T3", "furigana": "きかい しく たんじゅん", "sentence_source": "generated"}, {"text": "単純な問題から始めよう。", "target_word": "単純", "complexity_tier": "T3", "furigana": "たんじゅん もんだい はじ", "sentence_source": "generated"}, {"text": "説明が単純でわかりやすい。", "target_word": "単純", "complexity_tier": "T3", "furigana": "せつめい たんじゅん", "sentence_source": "generated"}, {"text": "その計算はとても単純です。", "target_word": "単純", "complexity_tier": "T3", "furigana": "けいさん たんじゅん", "sentence_source": "generated"}, {"text": "話はそんなに単純ではない。", "target_word": "単純", "complexity_tier": "T3", "furigana": "はなし たんじゅん", "sentence_source": "generated"}], "morphological_forms": [{"form": "単純な", "label": "活用"}, {"form": "単純に", "label": "活用"}, {"form": "単純だ", "label": "活用"}, {"form": "単純さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | 複雑でなく仕組みが少ないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: 5 words above tier T2 (max 3): サプライ (Zipf 3.19), 文脈 (Zipf 3.63), ミクロ (Zipf 3.34), 局所 (Zipf 3.35), 線形 (Zipf 2.97)']::text[], '33268c7d-6a9e-4208-aea5-f237b3a0425e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35619, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事と物事の間にあるつながりや結びつき。", "primary_collocate": null, "pronunciation": "かんけい", "ipa": "kaŋkeː", "syllable_count": 4, "sentences": [{"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな冷徹さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "関係", "complexity_tier": "T3", "furigana": "かそう くうかん じょう こうちく せいせいぶつ した や きょうじ か か ぬく れいてつ あいだ た ま きんちょう かんけい み と そうぞうせい ほんしつ と", "sentence_source": "mined"}, {"text": "「国際関係」の「外交」をします。", "target_word": "関係", "complexity_tier": "T3", "furigana": "こくさい かんけい がいこう", "sentence_source": "mined"}, {"text": "二つの国の関係はよくなった。", "target_word": "関係", "complexity_tier": "T3", "furigana": "ふた くに かんけい", "sentence_source": "generated"}, {"text": "天気と気分には関係がある。", "target_word": "関係", "complexity_tier": "T3", "furigana": "てんき きぶん かんけい", "sentence_source": "generated"}, {"text": "この話は私と関係がない。", "target_word": "関係", "complexity_tier": "T3", "furigana": "はなし わたし かんけい", "sentence_source": "generated"}, {"text": "友だちとの関係を大切にする。", "target_word": "関係", "complexity_tier": "T3", "furigana": "とも かんけい たいせつ", "sentence_source": "generated"}, {"text": "勉強時間と成績の関係を調べた。", "target_word": "関係", "complexity_tier": "T3", "furigana": "べんきょう じかん せいせき かんけい しら", "sentence_source": "generated"}, {"text": "二人はどんな関係ですか。", "target_word": "関係", "complexity_tier": "T3", "furigana": "ふたり かんけい", "sentence_source": "generated"}, {"text": "親子の関係が少し変わった。", "target_word": "関係", "complexity_tier": "T3", "furigana": "おやこ かんけい すこ か", "sentence_source": "generated"}, {"text": "この事件に関係した人を探す。", "target_word": "関係", "complexity_tier": "T3", "furigana": "じけん かんけい ひと さが", "sentence_source": "generated"}], "morphological_forms": [{"form": "関係する", "label": "派生"}, {"form": "関係者", "label": "派生"}, {"form": "人間関係", "label": "派生"}, {"form": "無関係", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事の間のつながりや結びつき", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 見て取れ (Zipf 2.23)']::text[], '33268c7d-6a9e-4208-aea5-f237b3a0425e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37317, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や人に何かを加えたり、取り付けたりすること。", "primary_collocate": null, "pronunciation": "つける", "ipa": "tsɯkeɾɯ", "syllable_count": 3, "sentences": [{"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "づけ", "complexity_tier": "T3", "furigana": "かんかくてき ちけん ちくせき たんいつ ひんしゅ きじゅん きゅうらい ぶんるい たいけい そうたいか びさい くかく こせい かいそうてき いち がいねん げんみつ どうてき しょうか かち ひょうか きじゅん てつがくてき じっせんてき さいていぎ", "sentence_source": "mined"}, {"text": "「国家性」のバッジをつけます。", "target_word": "つけ", "complexity_tier": "T3", "furigana": "こっかせい", "sentence_source": "mined"}, {"text": "かばんに名札を付けた。", "target_word": "付け", "complexity_tier": "T3", "furigana": "なふだ つ", "sentence_source": "generated"}, {"text": "服にボタンを付けている。", "target_word": "付け", "complexity_tier": "T3", "furigana": "ふく つ", "sentence_source": "generated"}, {"text": "パンにバターを付けて食べる。", "target_word": "付け", "complexity_tier": "T3", "furigana": "つ た", "sentence_source": "generated"}, {"text": "部屋にカーテンを付けたい。", "target_word": "付け", "complexity_tier": "T3", "furigana": "へや つ", "sentence_source": "generated"}, {"text": "自転車にライトを付けられる。", "target_word": "付け", "complexity_tier": "T3", "furigana": "じてんしゃ つ", "sentence_source": "generated"}, {"text": "箱にリボンを付けないでください。", "target_word": "付け", "complexity_tier": "T3", "furigana": "はこ つ", "sentence_source": "generated"}, {"text": "答えに名前を付けて出す。", "target_word": "付け", "complexity_tier": "T3", "furigana": "こた なまえ つ だ", "sentence_source": "generated"}, {"text": "壁に時計を付けてもらった。", "target_word": "付け", "complexity_tier": "T3", "furigana": "かべ とけい つ", "sentence_source": "generated"}], "morphological_forms": [{"form": "付けた", "label": "活用"}, {"form": "付けて", "label": "活用"}, {"form": "付けない", "label": "活用"}, {"form": "付けられる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 物に何かを加えたり取り付けたりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: アペラシオン (Zipf 1.01)']::text[], '33268c7d-6a9e-4208-aea5-f237b3a0425e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37187, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自動", "is_correct": true, "explanation": "正解。読みは「じどう」。"}, {"text": "指導", "is_correct": false, "explanation": "読みは「しどう」。「じ」と「し」の清濁の違い。"}, {"text": "地蔵", "is_correct": false, "explanation": "読みは「じぞう」。「ど」が「ぞ」に変わる一モーラ差。"}, {"text": "時効", "is_correct": false, "explanation": "読みは「じこう」。「ど」が「こ」に変わる一モーラ差。"}, {"text": "自由", "is_correct": false, "explanation": "読みは「じゆう」。「ど」が「ゆ」に変わる一モーラ差。"}], "explanations": {"自動": "正解。読みは「じどう」。", "指導": "読みは「しどう」。「じ」と「し」の清濁の違い。", "地蔵": "読みは「じぞう」。「ど」が「ぞ」に変わる一モーラ差。", "時効": "読みは「じこう」。「ど」が「こ」に変わる一モーラ差。", "自由": "読みは「じゆう」。「ど」が「ゆ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "自動"}, "level_3": {"options": [{"text": "自動", "is_correct": true, "explanation": "「自動化」で、人の手を使わずに機械が行うようになること。"}, {"text": "手動", "is_correct": false, "explanation": "「手動化が進み」は意味が通らない。AIが雇用を代替する話と合わない。"}, {"text": "活動", "is_correct": false, "explanation": "「活動化」は一般的でなく、文脈にも合わない。"}, {"text": "移動", "is_correct": false, "explanation": "「移動化」という語はなく、業務の文脈に合わない。"}], "explanations": {"自動": "「自動化」で、人の手を使わずに機械が行うようになること。", "手動": "「手動化が進み」は意味が通らない。AIが雇用を代替する話と合わない。", "活動": "「活動化」は一般的でなく、文脈にも合わない。", "移動": "「移動化」という語はなく、業務の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "自動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電気は夜に自動で三冊つく。", "explanation": "助数詞の誤り：「冊」は本を数える語で、ここには使えない。"}, {"text": "電気は夜を自動でつく。", "explanation": "助詞の混同：時を表すには「夜に」とすべき。"}, {"text": "電気は自動で夜につけてある。", "explanation": "活用・アスペクトの誤り：自然に点灯する意味なら「つく」で、「つけてある」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37187, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このドアは自動を開きます。", "corrected_sentence": "このドアは自動で開きます。", "error_description": "助詞の誤り：方法を表すのは「自動で」で、「自動を」ではない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37187, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「生成する」の目的語「配置」を示す。"}, {"text": "が", "is_correct": false, "explanation": "他動詞「生成する」の目的語は「が」で示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語の位置では非文になる。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を表し、ここでは意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「生成する」の目的語「配置」を示す。", "が": "他動詞「生成する」の目的語は「が」で示せない。", "へ": "方向を表し、目的語の位置では非文になる。", "と": "並列・相手を表し、ここでは意味が通らない。"}, "error_tags": {"が": "object_marking", "へ": "direction", "と": "listing"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "手動", "is_correct": true, "explanation": "「自動」の反対で、人が手で操作すること。"}, {"text": "機械", "is_correct": false, "explanation": "機械そのものを指し、反対の意味ではない。"}, {"text": "速度", "is_correct": false, "explanation": "速さの意味で、反対語ではない。"}, {"text": "電動", "is_correct": false, "explanation": "電気で動くことで、むしろ自動に近い。"}], "correct_answer": "手動", "explanations": {"手動": "「自動」の反対で、人が手で操作すること。", "機械": "機械そのものを指し、反対の意味ではない。", "速度": "速さの意味で、反対語ではない。", "電動": "電気で動くことで、むしろ自動に近い。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37187, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "自動", "is_correct": true, "explanation": "正解。読みは「じどう」。"}, {"text": "始動", "is_correct": false, "explanation": "読みは「しどう」。「じ」と「し」の清濁の差。"}, {"text": "地頭", "is_correct": false, "explanation": "読みは「じとう」。「ど」が「と」になる清濁の差。"}, {"text": "自由", "is_correct": false, "explanation": "読みは「じゆう」。「ど」が「ゆ」になる一モーラ差。"}, {"text": "地蔵", "is_correct": false, "explanation": "読みは「じぞう」。「ど」が「ぞ」になる一モーラ差。"}], "explanations": {"自動": "正解。読みは「じどう」。", "始動": "読みは「しどう」。「じ」と「し」の清濁の差。", "地頭": "読みは「じとう」。「ど」が「と」になる清濁の差。", "自由": "読みは「じゆう」。「ど」が「ゆ」になる一モーラ差。", "地蔵": "読みは「じぞう」。「ど」が「ぞ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "自動"}, "level_3": {"options": [{"text": "自動", "is_correct": true, "explanation": "人が通さなくても機械で開閉する改札を表す。"}, {"text": "自然", "is_correct": false, "explanation": "「改札は自然になっている」は意味が通らない。"}, {"text": "自習", "is_correct": false, "explanation": "自習は勉強のことで、改札には合わない。"}, {"text": "自宅", "is_correct": false, "explanation": "改札が自宅になることはない。"}], "explanations": {"自動": "人が通さなくても機械で開閉する改札を表す。", "自然": "「改札は自然になっている」は意味が通らない。", "自習": "自習は勉強のことで、改札には合わない。", "自宅": "改札が自宅になることはない。"}, "sentence_index": 6, "correct_answer": "自動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部屋の温度で自動を調整する。", "explanation": "助詞の混同：調整する対象は「温度を」、方法は「自動で」。"}, {"text": "部屋の温度を自動で昨日調整するだろう。", "explanation": "アスペクトの誤り：「昨日」と未来の推量が合わない。"}, {"text": "部屋の温度を自動で一枚調整する。", "explanation": "助数詞の誤り：「枚」は薄い物を数える語で、ここには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
