INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37187, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "方法・手段を表し、「自動で保存される」となる。"}, {"text": "を", "is_correct": false, "explanation": "受身の「保存される」の前に方法を「を」で示せない。"}, {"text": "が", "is_correct": false, "explanation": "「自動が保存される」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、手段の位置では非文。"}], "correct_answer": "で", "explanations": {"で": "方法・手段を表し、「自動で保存される」となる。", "を": "受身の「保存される」の前に方法を「を」で示せない。", "が": "「自動が保存される」は意味が通らない。", "へ": "方向を表し、手段の位置では非文。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "手動", "is_correct": true, "explanation": "自動の反対で、人の手で操作すること。"}, {"text": "温度", "is_correct": false, "explanation": "温かさの度合いで、反対語ではない。"}, {"text": "部屋", "is_correct": false, "explanation": "場所を表し、関係がない。"}, {"text": "自宅", "is_correct": false, "explanation": "自分の家で、反対語ではない。"}], "correct_answer": "手動", "explanations": {"手動": "自動の反対で、人の手で操作すること。", "温度": "温かさの度合いで、反対語ではない。", "部屋": "場所を表し、関係がない。", "自宅": "自分の家で、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37475, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "適応", "is_correct": true, "explanation": "正解。読みは「てきおう」。"}, {"text": "適当", "is_correct": false, "explanation": "読みは「てきとう」。「お」が「と」に変わる一モーラ差。"}, {"text": "適合", "is_correct": false, "explanation": "読みは「てきごう」。「お」が「ご」に変わる一モーラ差。"}, {"text": "適用", "is_correct": false, "explanation": "読みは「てきよう」。「お」が「よ」に変わる一モーラ差。"}], "explanations": {"適応": "正解。読みは「てきおう」。", "適当": "読みは「てきとう」。「お」が「と」に変わる一モーラ差。", "適合": "読みは「てきごう」。「お」が「ご」に変わる一モーラ差。", "適用": "読みは「てきよう」。「お」が「よ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "適応"}, "level_3": {"options": [{"text": "適応", "is_correct": true, "explanation": "変化に合わせて自分を変えること。"}, {"text": "散歩", "is_correct": false, "explanation": "「変化に散歩し」は意味が通らない。"}, {"text": "出発", "is_correct": false, "explanation": "「変化に出発し」は文法的に成り立たない。"}, {"text": "到着", "is_correct": false, "explanation": "「変化に到着し」は意味が通らない。"}], "explanations": {"適応": "変化に合わせて自分を変えること。", "散歩": "「変化に散歩し」は意味が通らない。", "出発": "「変化に出発し」は文法的に成り立たない。", "到着": "「変化に到着し」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "適応"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい学校を適応するのは大変だ。", "explanation": "助詞の混同：適応する対象は「に」で示す。"}, {"text": "新しい学校に適応してあるのは大変だ。", "explanation": "アスペクトの誤り：「てある」は自動詞的な「適応する」と合わない。"}, {"text": "新しい学校に三本の適応をするのは大変だ。", "explanation": "助数詞の誤り：「本」は合わず、適応は数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
