INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37475, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "適応", "is_correct": true, "explanation": "正解。読みは「てきおう」。"}, {"text": "適温", "is_correct": false, "explanation": "読みは「てきおん」。最後の「う」が「ん」になる一モーラ差。"}, {"text": "摘要", "is_correct": false, "explanation": "読みは「てきよう」。「お」が「よ」になる一モーラ差。"}, {"text": "帝王", "is_correct": false, "explanation": "読みは「ていおう」。「き」が「い」になる一モーラ差。"}], "explanations": {"適応": "正解。読みは「てきおう」。", "適温": "読みは「てきおん」。最後の「う」が「ん」になる一モーラ差。", "摘要": "読みは「てきよう」。「お」が「よ」になる一モーラ差。", "帝王": "読みは「ていおう」。「き」が「い」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "適応"}, "level_3": {"options": [{"text": "適応", "is_correct": true, "explanation": "新しい環境に合わせる力のこと。"}, {"text": "身長", "is_correct": false, "explanation": "「身長の力」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の力が強い」は子どもについて言えない。"}, {"text": "料理", "is_correct": false, "explanation": "「料理の力」は子どもの性質として不自然。"}], "explanations": {"適応": "新しい環境に合わせる力のこと。", "身長": "「身長の力」は意味が通らない。", "天気": "「天気の力が強い」は子どもについて言えない。", "料理": "「料理の力」は子どもの性質として不自然。"}, "sentence_index": 6, "correct_answer": "適応"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "適応を少し時間が必要だ。", "explanation": "助詞の混同：「適応には」とすべき。"}, {"text": "適応には二匹の時間が必要だ。", "explanation": "助数詞の誤り：「匹」は動物を数える語。"}, {"text": "適応には昨日少し時間が必要だろう。", "explanation": "アスペクトの誤り：「昨日」と推量が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
