INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36329, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "姿勢", "is_correct": true, "explanation": "正解。読みは「しせい」。"}, {"text": "史跡", "is_correct": false, "explanation": "読みは「しせき」。最後の「い」が「き」になる一モーラ差。"}, {"text": "異性", "is_correct": false, "explanation": "読みは「いせい」。最初の「し」が「い」になる一モーラ差。"}, {"text": "時勢", "is_correct": false, "explanation": "読みは「じせい」。最初のモーラが濁る清濁の差。"}, {"text": "視線", "is_correct": false, "explanation": "読みは「しせん」。最後の「い」が「ん」になる一モーラ差。"}], "explanations": {"姿勢": "正解。読みは「しせい」。", "史跡": "読みは「しせき」。最後の「い」が「き」になる一モーラ差。", "異性": "読みは「いせい」。最初の「し」が「い」になる一モーラ差。", "時勢": "読みは「じせい」。最初のモーラが濁る清濁の差。", "視線": "読みは「しせん」。最後の「い」が「ん」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "姿勢"}, "level_3": {"options": [{"text": "姿勢", "is_correct": true, "explanation": "仕事に取り組む態度が変わったこと。"}, {"text": "身長", "is_correct": false, "explanation": "仕事に取り組む身長は意味が通らない。"}, {"text": "住所", "is_correct": false, "explanation": "仕事に取り組む住所は意味が通らない。"}, {"text": "値段", "is_correct": false, "explanation": "仕事に取り組む値段は不自然。"}], "explanations": {"姿勢": "仕事に取り組む態度が変わったこと。", "身長": "仕事に取り組む身長は意味が通らない。", "住所": "仕事に取り組む住所は意味が通らない。", "値段": "仕事に取り組む値段は不自然。"}, "sentence_index": 6, "correct_answer": "姿勢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社の姿勢に問われている。", "explanation": "助詞の混同：問われる対象は「が」（または「を」）で示し、「に」は使えない。"}, {"text": "会社の姿勢が二台問われている。", "explanation": "助数詞の誤り：「台」は機械を数える語。"}, {"text": "会社の姿勢が明日問われていた。", "explanation": "アスペクトの誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36329, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仕事に取り組む姿勢を変わった。", "corrected_sentence": "仕事に取り組む姿勢が変わった。", "error_description": "助詞の混同：自動詞「変わる」の主語は「が」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
