INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36593, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "単純", "is_correct": true, "explanation": "正解。読みは「たんじゅん」。"}, {"text": "温順", "is_correct": false, "explanation": "読みは「おんじゅん」。最初のモーラ「た」が「お」に変わる一モーラ差。"}, {"text": "因循", "is_correct": false, "explanation": "読みは「いんじゅん」。「た」が「い」に変わる一モーラ差。"}, {"text": "短銃", "is_correct": false, "explanation": "読みは「たんじゅう」。最後の「ん」が「う」に変わる一モーラ差。"}], "explanations": {"単純": "正解。読みは「たんじゅん」。", "温順": "読みは「おんじゅん」。最初のモーラ「た」が「お」に変わる一モーラ差。", "因循": "読みは「いんじゅん」。「た」が「い」に変わる一モーラ差。", "短銃": "読みは「たんじゅう」。最後の「ん」が「う」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "単純"}, "level_3": {"options": [{"text": "単純", "is_correct": true, "explanation": "複雑でない、決まった作業を表す。"}, {"text": "静か", "is_correct": false, "explanation": "作業が静かでも、創造性との対比が成り立たない。"}, {"text": "有名", "is_correct": false, "explanation": "作業が有名というのは不自然。"}, {"text": "元気", "is_correct": false, "explanation": "作業が元気というのは意味が通らない。"}], "explanations": {"単純": "複雑でない、決まった作業を表す。", "静か": "作業が静かでも、創造性との対比が成り立たない。", "有名": "作業が有名というのは不自然。", "元気": "作業が元気というのは意味が通らない。"}, "sentence_index": 0, "correct_answer": "単純"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "答えを思ったより単純だった。", "explanation": "助詞の混同：主語は「は」または「が」で示す。"}, {"text": "答えは思ったより単純だっている。", "explanation": "活用の誤り：「だった」に「ている」は付かない。"}, {"text": "答えは一匹思ったより単純だった。", "explanation": "助数詞の誤り：「匹」は動物を数える語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36593, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このゲームのルールを単純だ。", "corrected_sentence": "このゲームのルールは単純だ。", "error_description": "助詞の混同：主題は「は」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "単純", "is_correct": true, "explanation": "後に「な」が続く語幹で、「単純な線形モデル」となる。"}, {"text": "単純さ", "is_correct": false, "explanation": "名詞形で、後に「な」は続かない。"}, {"text": "単純に", "is_correct": false, "explanation": "連用形で、後に「な」は続かない。"}, {"text": "単純だ", "is_correct": false, "explanation": "終止形で、後に「な」は続かない。"}], "correct_form": "単純", "base_form": "単純だ", "form_label": "活用", "sentence_index": 1, "explanations": {"単純": "後に「な」が続く語幹で、「単純な線形モデル」となる。", "単純さ": "名詞形で、後に「な」は続かない。", "単純に": "連用形で、後に「な」は続かない。", "単純だ": "終止形で、後に「な」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36593, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "複雑", "is_correct": true, "explanation": "「単純」の反対で、要素や仕組みが多く入り組んでいること。"}, {"text": "簡単", "is_correct": false, "explanation": "似た意味で、反対語ではない。"}, {"text": "大切", "is_correct": false, "explanation": "重要の意味で、反対語ではない。"}, {"text": "静か", "is_correct": false, "explanation": "音がない様子で、関係がない。"}], "correct_answer": "複雑", "explanations": {"複雑": "「単純」の反対で、要素や仕組みが多く入り組んでいること。", "簡単": "似た意味で、反対語ではない。", "大切": "重要の意味で、反対語ではない。", "静か": "音がない様子で、関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36593, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "単純", "is_correct": true, "explanation": "正解。読みは「たんじゅん」。"}, {"text": "単身", "is_correct": false, "explanation": "読みは「たんしん」。「じゅ」が「し」になる一モーラ差。"}, {"text": "担任", "is_correct": false, "explanation": "読みは「たんにん」。「じゅ」が「に」になる一モーラ差。"}, {"text": "炭塵", "is_correct": false, "explanation": "読みは「たんじん」。「じゅ」が「じ」になる一モーラ差。"}], "explanations": {"単純": "正解。読みは「たんじゅん」。", "単身": "読みは「たんしん」。「じゅ」が「し」になる一モーラ差。", "担任": "読みは「たんにん」。「じゅ」が「に」になる一モーラ差。", "炭塵": "読みは「たんじん」。「じゅ」が「じ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "単純"}, "level_3": {"options": [{"text": "単純", "is_correct": true, "explanation": "やさしい問題から始めるという意味。"}, {"text": "親切", "is_correct": false, "explanation": "問題が親切というのは不自然。"}, {"text": "元気", "is_correct": false, "explanation": "問題が元気というのは意味が通らない。"}, {"text": "丈夫", "is_correct": false, "explanation": "問題が丈夫というのは意味が通らない。"}], "explanations": {"単純": "やさしい問題から始めるという意味。", "親切": "問題が親切というのは不自然。", "元気": "問題が元気というのは意味が通らない。", "丈夫": "問題が丈夫というのは意味が通らない。"}, "sentence_index": 6, "correct_answer": "単純"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "話はそんなに単純くない。", "explanation": "活用の誤り：形状詞「単純」に「くない」は付かず、「単純ではない」とする。"}, {"text": "話をそんなに単純ではない。", "explanation": "助詞の混同：主題は「は」で示す。"}, {"text": "話は三本そんなに単純ではない。", "explanation": "助数詞の誤り：「本」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36593, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "単純な問題を始めよう。", "corrected_sentence": "単純な問題から始めよう。", "error_description": "助詞の混同：開始点は「から」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "単純", "is_correct": true, "explanation": "後に「で」が続き、「単純で」となる。"}, {"text": "単純な", "is_correct": false, "explanation": "連体形で、後に「で」は続かない。"}, {"text": "単純に", "is_correct": false, "explanation": "連用形で、後に「で」は続かない。"}, {"text": "単純さ", "is_correct": false, "explanation": "名詞形で、「単純さで」は意味が変わり不自然。"}], "correct_form": "単純", "base_form": "単純だ", "form_label": "活用", "sentence_index": 7, "explanations": {"単純": "後に「で」が続き、「単純で」となる。", "単純な": "連体形で、後に「で」は続かない。", "単純に": "連用形で、後に「で」は続かない。", "単純さ": "名詞形で、「単純さで」は意味が変わり不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36593, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "複雑", "is_correct": true, "explanation": "単純の反対で、入り組んでいること。"}, {"text": "簡素", "is_correct": false, "explanation": "単純に近い意味で、反対語ではない。"}, {"text": "正直", "is_correct": false, "explanation": "人の性格を表し、関係がない。"}, {"text": "便利", "is_correct": false, "explanation": "使いやすい意味で、反対語ではない。"}], "correct_answer": "複雑", "explanations": {"複雑": "単純の反対で、入り組んでいること。", "簡素": "単純に近い意味で、反対語ではない。", "正直": "人の性格を表し、関係がない。", "便利": "使いやすい意味で、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35619, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "関係", "is_correct": true, "explanation": "正解。読みは「かんけい」。"}, {"text": "慣例", "is_correct": false, "explanation": "読みは「かんれい」。「け」が「れ」に変わる一モーラ差。"}, {"text": "完成", "is_correct": false, "explanation": "読みは「かんせい」。「け」が「せ」に変わる一モーラ差。"}, {"text": "簡潔", "is_correct": false, "explanation": "読みは「かんけつ」。「い」が「つ」に変わる一モーラ差。"}, {"text": "半径", "is_correct": false, "explanation": "読みは「はんけい」。「か」が「は」に変わる一モーラ差。"}], "explanations": {"関係": "正解。読みは「かんけい」。", "慣例": "読みは「かんれい」。「け」が「れ」に変わる一モーラ差。", "完成": "読みは「かんせい」。「け」が「せ」に変わる一モーラ差。", "簡潔": "読みは「かんけつ」。「い」が「つ」に変わる一モーラ差。", "半径": "読みは「はんけい」。「か」が「は」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "関係"}, "level_3": {"options": [{"text": "関係", "is_correct": true, "explanation": "「緊張関係」で、二つの間の張りつめたつながり。"}, {"text": "料理", "is_correct": false, "explanation": "「緊張料理」という語はない。"}, {"text": "天気", "is_correct": false, "explanation": "「緊張天気」は意味が通らない。"}, {"text": "住所", "is_correct": false, "explanation": "「緊張住所」は意味が通らない。"}], "explanations": {"関係": "「緊張関係」で、二つの間の張りつめたつながり。", "料理": "「緊張料理」という語はない。", "天気": "「緊張天気」は意味が通らない。", "住所": "「緊張住所」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "関係"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天気と気分には関係が一匹ある。", "explanation": "助数詞の誤り：「匹」は動物を数える語で合わない。"}, {"text": "天気と気分には関係をある。", "explanation": "助詞の混同：「ある」の主語は「が」で示す。"}, {"text": "天気と気分には関係があってある。", "explanation": "活用の誤り：「あってある」は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ebbd16-a3c0-4c8f-8d81-a7b0ecfcfbfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validatio