INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36817, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "楽しく過ごすために、好きなことをする。", "primary_collocate": null, "pronunciation": "あそぶ", "ipa": "asobɯ", "syllable_count": 3, "sentences": [{"text": "厳冬の冷たさなど意に介さず、ただ純粋に外で遊ぶための準備に余念がないのだ。", "target_word": "遊ぶ", "complexity_tier": "T3", "furigana": "げんとう つめ い かい じゅんすい そと あそ じゅんび よねん", "sentence_source": "mined"}, {"text": "私はゲームの世界であそびます。", "target_word": "あそび", "complexity_tier": "T3", "furigana": "わたし せかい", "sentence_source": "mined"}, {"text": "子どもたちが公園で遊んでいる。", "target_word": "遊ん", "complexity_tier": "T3", "furigana": "こ こうえん あそ", "sentence_source": "generated"}, {"text": "週末は友だちと遊びたい。", "target_word": "遊び", "complexity_tier": "T3", "furigana": "しゅうまつ とも あそ", "sentence_source": "generated"}, {"text": "昨日は弟と家で遊んだ。", "target_word": "遊ん", "complexity_tier": "T3", "furigana": "きのう おとうと いえ あそ", "sentence_source": "generated"}, {"text": "雨の日は外で遊べない。", "target_word": "遊べ", "complexity_tier": "T3", "furigana": "あめ ひ そと あそ", "sentence_source": "generated"}, {"text": "遊ぶ時間がもっと欲しい。", "target_word": "遊ぶ", "complexity_tier": "T3", "furigana": "あそ じかん ほ", "sentence_source": "generated"}, {"text": "宿題の後で遊ぼうよ。", "target_word": "遊ぼ", "complexity_tier": "T3", "furigana": "しゅくだい あと あそ", "sentence_source": "generated"}, {"text": "犬はボールで遊ぶのが好きだ。", "target_word": "遊ぶ", "complexity_tier": "T3", "furigana": "いぬ あそ す", "sentence_source": "generated"}, {"text": "一緒に遊んでくれてありがとう。", "target_word": "遊ん", "complexity_tier": "T3", "furigana": "いっしょ あそ", "sentence_source": "generated"}], "morphological_forms": [{"form": "遊んだ", "label": "活用"}, {"form": "遊んで", "label": "活用"}, {"form": "遊ばない", "label": "活用"}, {"form": "遊び", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 好きなことをして楽しく過ごす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 厳冬 (Zipf 2.45)']::text[], '9f89d774-4aeb-4430-a9a7-ad9ad6bd66b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51728, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物などの壁に設けられた、外の光や空気を取り入れるための開口部。", "primary_collocate": null, "pronunciation": "まど", "ipa": "mado", "syllable_count": 2, "sentences": [{"text": "凛とした寒気が窓ガラスを伝い、室内の空気を凍てつかせようとしている。", "target_word": "窓", "complexity_tier": "T3", "furigana": "りん かんき まど つた しつない くうき い", "sentence_source": "mined"}, {"text": "これらにより、壁を薄くして大きな窓を設けることが可能となり、内部は光に満ちあふれました。", "target_word": "窓", "complexity_tier": "T3", "furigana": "かべ うす おお まど もう かのう ないぶ ひかり み", "sentence_source": "mined"}, {"text": "暑いので窓を開けてください。", "target_word": "窓", "complexity_tier": "T3", "furigana": "あつ まど あ", "sentence_source": "generated"}, {"text": "窓から海が見える。", "target_word": "窓", "complexity_tier": "T3", "furigana": "まど うみ み", "sentence_source": "generated"}, {"text": "寝る前に窓を閉めた。", "target_word": "窓", "complexity_tier": "T3", "furigana": "ね まえ まど し", "sentence_source": "generated"}, {"text": "この部屋は窓が大きい。", "target_word": "窓", "complexity_tier": "T3", "furigana": "へや まど おお", "sentence_source": "generated"}, {"text": "窓の外で鳥が鳴いている。", "target_word": "窓", "complexity_tier": "T3", "furigana": "まど そと とり な", "sentence_source": "generated"}, {"text": "母が窓をきれいにふいた。", "target_word": "窓", "complexity_tier": "T3", "furigana": "はは まど", "sentence_source": "generated"}, {"text": "風で窓がガタガタ鳴った。", "target_word": "窓", "complexity_tier": "T3", "furigana": "かぜ まど な", "sentence_source": "generated"}, {"text": "窓側の席に座りたい。", "target_word": "窓", "complexity_tier": "T3", "furigana": "まどがわ せき すわ", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "助数詞"}, {"form": "窓ガラス", "label": "派生"}, {"form": "窓口", "label": "派生"}, {"form": "窓際", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 光や空気を入れる壁の開口部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 凍てつか (Zipf 1.03)']::text[], '9f89d774-4aeb-4430-a9a7-ad9ad6bd66b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37041, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物や空間の、外側ではなく内側の部分。", "primary_collocate": null, "pronunciation": "ないぶ", "ipa": "naibɯ", "syllable_count": 3, "sentences": [{"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "内部", "complexity_tier": "T3", "furigana": "さいしゅうだんかい こうおん じょうき とも ぼうちょう きじ おうごんいろ こうしつ もろ まと ないぶ みずみず だんりょく と しょうか", "sentence_source": "mined"}, {"text": "これらにより、壁を薄くして大きな窓を設けることが可能となり、内部は光に満ちあふれました。", "target_word": "内部", "complexity_tier": "T3", "furigana": "かべ うす おお まど もう かのう ないぶ ひかり み", "sentence_source": "mined"}, {"text": "箱の内部はとても暗かった。", "target_word": "内部", "complexity_tier": "T3", "furigana": "はこ ないぶ くら", "sentence_source": "generated"}, {"text": "機械の内部を見てみよう。", "target_word": "内部", "complexity_tier": "T3", "furigana": "きかい ないぶ み", "sentence_source": "generated"}, {"text": "建物の内部に入れない。", "target_word": "内部", "complexity_tier": "T3", "furigana": "たてもの ないぶ はい", "sentence_source": "generated"}, {"text": "内部の温度が上がっている。", "target_word": "内部", "complexity_tier": "T3", "furigana": "ないぶ おんど あ", "sentence_source": "generated"}, {"text": "この城は内部も美しい。", "target_word": "内部", "complexity_tier": "T3", "furigana": "しろ ないぶ うつく", "sentence_source": "generated"}, {"text": "地球の内部はとても熱い。", "target_word": "内部", "complexity_tier": "T3", "furigana": "ちきゅう ないぶ あつ", "sentence_source": "generated"}, {"text": "内部から変な音がする。", "target_word": "内部", "complexity_tier": "T3", "furigana": "ないぶ へん おと", "sentence_source": "generated"}, {"text": "車の内部をきれいにした。", "target_word": "内部", "complexity_tier": "T3", "furigana": "くるま ないぶ", "sentence_source": "generated"}], "morphological_forms": [{"form": "内部的", "label": "派生"}, {"form": "内部構造", "label": "派生"}, {"form": "内部告発", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物や空間の内側の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: ベーキング (Zipf 1.24), クラスト (Zipf 2.0), 瑞々しく (Zipf 1.76), クラム (Zipf 2.34)']::text[], '9f89d774-4aeb-4430-a9a7-ad9ad6bd66b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35513, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あるものに特定の名前や言葉を使って、それを指し示すこと。", "primary_collocate": null, "pronunciation": "よぶ", "ipa": "jobɯ", "syllable_count": 2, "sentences": [{"text": "これを「オーブンスプリング」と呼びます。", "target_word": "呼び", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "特に注目すべきは、天井の重量を分散させる「リブ・ヴォールト」と、壁の外側から支える「フライング・バットレス」と呼ばれる技術です。", "target_word": "呼ば", "complexity_tier": "T3", "furigana": "とく ちゅうもく てんじょう じゅうりょう ぶんさん かべ そとがわ ささ よ ぎじゅつ", "sentence_source": "mined"}, {"text": "みんなは彼を「ケン」と呼ぶ。", "target_word": "呼ぶ", "complexity_tier": "T3", "furigana": "かれ よ", "sentence_source": "generated"}, {"text": "この花はサクラと呼ばれている。", "target_word": "呼ば", "complexity_tier": "T3", "furigana": "はな よ", "sentence_source": "generated"}, {"text": "祖母を「ばあば」と呼んでいる。", "target_word": "呼ん", "complexity_tier": "T3", "furigana": "そぼ よ", "sentence_source": "generated"}, {"text": "この山は「白い山」と呼ばれる。", "target_word": "呼ば", "complexity_tier": "T3", "furigana": "やま しろ やま よ", "sentence_source": "generated"}, {"text": "私のことはユミと呼んでね。", "target_word": "呼ん", "complexity_tier": "T3", "furigana": "わたし よ", "sentence_source": "generated"}, {"text": "昔はこの町を何と呼んだの？", "target_word": "呼ん", "complexity_tier": "T3", "furigana": "むかし まち なん よ", "sentence_source": "generated"}, {"text": "日本では「お正月」と呼ぶ。", "target_word": "呼ぶ", "complexity_tier": "T3", "furigana": "にほん しょうがつ よ", "sentence_source": "generated"}, {"text": "先生を名前で呼んではいけない。", "target_word": "呼ん", "complexity_tier": "T3", "furigana": "せんせい なまえ よ", "sentence_source": "generated"}], "morphological_forms": [{"form": "呼んだ", "label": "活用"}, {"form": "呼ばれる", "label": "活用"}, {"form": "呼んで", "label": "活用"}, {"form": "呼び名", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 特定の名前で物や人を言い表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f89d774-4aeb-4430-a9a7-ad9ad6bd66b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38479, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "建物や道路など、大きなものを作ること。", "primary_collocate": null, "pronunciation": "けんせつ", "ipa": "keɴsetsɯ", "syllable_count": 4, "sentences": [{"text": "たくさんの人が、いっしょに建設をしています。", "target_word": "建設", "complexity_tier": "T3", "furigana": "ひと けんせつ", "sentence_source": "mined"}, {"text": "この建設には、当時の建築工学の知恵が結集されています。", "target_word": "建設", "complexity_tier": "T3", "furigana": "けんせつ とうじ けんちくこうがく ちえ けっしゅう", "sentence_source": "mined"}, {"text": "駅の近くで橋の建設が始まった。", "target_word": "建設", "complexity_tier": "T3", "furigana": "えき ちか はし けんせつ はじ", "sentence_source": "generated"}, {"text": "新しい学校を建設している。", "target_word": "建設", "complexity_tier": "T3", "furigana": "あたら がっこう けんせつ", "sentence_source": "generated"}, {"text": "建設の音がうるさい。", "target_word": "建設", "complexity_tier": "T3", "furigana": "けんせつ おと", "sentence_source": "generated"}, {"text": "このビルは建設中です。", "target_word": "建設", "complexity_tier": "T3", "furigana": "けんせつちゅう", "sentence_source": "generated"}, {"text": "道路の建設に三年かかった。", "target_word": "建設", "complexity_tier": "T3", "furigana": "どうろ けんせつ さんねん", "sentence_source": "generated"}, {"text": "父は建設の仕事をしている。", "target_word": "建設", "complexity_tier": "T3", "furigana": "ちち けんせつ しごと", "sentence_source": "generated"}, {"text": "町は空港を建設したい。", "target_word": "建設", "complexity_tier": "T3", "furigana": "まち くうこう けんせつ", "sentence_source": "generated"}, {"text": "ダムの建設に反対する人もいる。", "target_word": "建設", "complexity_tier": "T3", "furigana": "けんせつ はんたい ひと", "sentence_source": "generated"}], "morphological_forms": [{"form": "建設する", "label": "派生"}, {"form": "建設中", "label": "派生"}, {"form": "建設的", "label": "派生"}, {"form": "建設会社", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 建物や道路など大きな物を造る", "collocate_grounding": {"status": "no_source"