INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37599, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "科学の原理を使って、役に立つものや仕組みを作る学問。", "primary_collocate": null, "pronunciation": "こうがく", "ipa": "koːgakɯ", "syllable_count": 4, "sentences": [{"text": "ロボット工学の深淵を志す者がまず体現すべきは、DIYの精神に根ざした泥臭い試行錯誤のプロセスに他ならない。", "target_word": "工学", "complexity_tier": "T3", "furigana": "こうがく しんえん こころざ もの たいげん せいしん ね どろくさ しこうさくご ほか", "sentence_source": "mined"}, {"text": "この建設には、当時の建築工学の知恵が結集されています。", "target_word": "工学", "complexity_tier": "T3", "furigana": "けんせつ とうじ けんちくこうがく ちえ けっしゅう", "sentence_source": "mined"}, {"text": "兄は大学で工学を学んでいる。", "target_word": "工学", "complexity_tier": "T3", "furigana": "あに だいがく こうがく まな", "sentence_source": "generated"}, {"text": "工学に興味があります。", "target_word": "工学", "complexity_tier": "T3", "furigana": "こうがく きょうみ", "sentence_source": "generated"}, {"text": "将来は工学の道に進みたい。", "target_word": "工学", "complexity_tier": "T3", "furigana": "しょうらい こうがく みち すす", "sentence_source": "generated"}, {"text": "工学は生活を便利にする。", "target_word": "工学", "complexity_tier": "T3", "furigana": "こうがく せいかつ べんり", "sentence_source": "generated"}, {"text": "姉は工学の研究をしている。", "target_word": "工学", "complexity_tier": "T3", "furigana": "あね こうがく けんきゅう", "sentence_source": "generated"}, {"text": "工学を勉強するのは楽しい。", "target_word": "工学", "complexity_tier": "T3", "furigana": "こうがく べんきょう たの", "sentence_source": "generated"}, {"text": "この橋には工学の知識が必要だ。", "target_word": "工学", "complexity_tier": "T3", "furigana": "はし こうがく ちしき ひつよう", "sentence_source": "generated"}, {"text": "工学の先生に質問した。", "target_word": "工学", "complexity_tier": "T3", "furigana": "こうがく せんせい しつもん", "sentence_source": "generated"}], "morphological_forms": [{"form": "工学部", "label": "派生"}, {"form": "工学者", "label": "派生"}, {"form": "機械工学", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 