INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36817, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遊ぶ", "is_correct": true, "explanation": "「あそぶ」：楽しく過ごすこと。正解。"}, {"text": "あそこ", "is_correct": false, "explanation": "「あそこ」：遠くの場所を指す語。「ぶ」が「こ」に変わる一モーラ差。"}, {"text": "麻布", "is_correct": false, "explanation": "「あざぶ」：東京の地名。「そ」が「ざ」に変わる一モーラ差。"}, {"text": "阿蘇", "is_correct": false, "explanation": "「あそ」：熊本の山の名。最後の「ぶ」がない。"}], "explanations": {"遊ぶ": "「あそぶ」：楽しく過ごすこと。正解。", "あそこ": "「あそこ」：遠くの場所を指す語。「ぶ」が「こ」に変わる一モーラ差。", "麻布": "「あざぶ」：東京の地名。「そ」が「ざ」に変わる一モーラ差。", "阿蘇": "「あそ」：熊本の山の名。最後の「ぶ」がない。"}, "sentence_index": null, "correct_answer": "遊ぶ"}, "level_3": {"options": [{"text": "遊ぶ", "is_correct": true, "explanation": "意味：外で楽しく過ごす準備をしているので「遊ぶ」が合う。"}, {"text": "謝る", "is_correct": false, "explanation": "意味：外で謝るための準備は文脈に合わない。"}, {"text": "忘れる", "is_correct": false, "explanation": "項構造：「忘れる」は目的語が必要で、準備の目的にならない。"}, {"text": "怒る", "is_correct": false, "explanation": "意味：純粋に怒るための準備は不自然。"}], "explanations": {"遊ぶ": "意味：外で楽しく過ごす準備をしているので「遊ぶ」が合う。", "謝る": "意味：外で謝るための準備は文脈に合わない。", "忘れる": "項構造：「忘れる」は目的語が必要で、準備の目的にならない。", "怒る": "意味：純粋に怒るための準備は不自然。"}, "sentence_index": 0, "correct_answer": "遊ぶ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は友だちを遊びたい。", "explanation": "助詞の混同：一緒に遊ぶ相手は「と」で示す。「を」は不可。"}, {"text": "昨日は友だちと遊んでいる。", "explanation": "アスペクトの誤り：「昨日」には過去形「遊んだ」が必要。"}, {"text": "週末は友だちで遊びたい。", "explanation": "助詞の混同：一緒に遊ぶ相手は「と」で示す。「で」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id 