INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36817, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちが公園を遊んでいる。", "corrected_sentence": "子どもたちが公園で遊んでいる。", "error_description": "助詞の混同：遊ぶ場所は「で」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "あそび", "is_correct": true, "explanation": "「ます」には連用形「あそび」が続く。"}, {"text": "あそば", "is_correct": false, "explanation": "「あそば」は未然形で「ない」などに続き、「ます」には続かない。"}, {"text": "あそん", "is_correct": false, "explanation": "「あそん」は「で」「だ」に続く形で、「ます」には続かない。"}, {"text": "あそぶ", "is_correct": false, "explanation": "辞書形に「ます」は続かない。"}], "correct_form": "あそび", "base_form": "遊ぶ", "form_label": "活用", "sentence_index": 1, "explanations": {"あそび": "「ます」には連用形「あそび」が続く。", "あそば": "「あそば」は未然形で「ない」などに続き、「ます」には続かない。", "あそん": "「あそん」は「で」「だ」に続く形で、「ます」には続かない。", "あそぶ": "辞書形に「ます」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36817, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "遊ぶ場所を示す「で」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示し、場所の「世界」には使えない。"}, {"text": "が", "is_correct": false, "explanation": "「世界が遊ぶ」となり意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、遊ぶ場所を示せない。"}], "correct_answer": "で", "explanations": {"で": "遊ぶ場所を示す「で」。", "を": "「を」は目的語を示し、場所の「世界」には使えない。", "が": "「世界が遊ぶ」となり意味が通らない。", "から": "起点を表し、遊ぶ場所を示せない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "から": "source_vs_goal"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "働く", "is_correct": true, "explanation": "遊ぶ（楽しく過ごす）の反対で、仕事をすること。"}, {"text": "走る", "is_correct": false, "explanation": "動作だが遊ぶの反対ではない。"}, {"text": "笑う", "is_correct": false, "explanation": "楽しさに関わるが反対の意味ではない。"}, {"text": "歌う", "is_correct": false, "explanation": "楽しむ動作の一つで、反対ではない。"}], "correct_answer": "働く", "explanations": {"働く": "遊ぶ（楽しく過ごす）の反対で、仕事をすること。", "走る": "動作だが遊ぶの反対ではない。", "笑う": "楽しさに関わるが反対の意味ではない。", "歌う": "楽しむ動作の一つで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
