INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36817, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日は弟と家で遊んだ。", "corrected_sentence": "明日は弟と家で遊ぶ。", "error_description": "アスペクトの誤り：「明日」には過去形ではなく「遊ぶ」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "遊ぼ", "is_correct": true, "explanation": "「う」に続けて意向形「遊ぼう」を作る。"}, {"text": "遊ば", "is_correct": false, "explanation": "「遊ばう」という形はない。"}, {"text": "遊べ", "is_correct": false, "explanation": "「遊べう」という形はない。"}, {"text": "遊ん", "is_correct": false, "explanation": "「遊んう」という形はない。"}], "correct_form": "遊ぼ", "base_form": "遊ぶ", "form_label": "活用", "sentence_index": 7, "explanations": {"遊ぼ": "「う」に続けて意向形「遊ぼう」を作る。", "遊ば": "「遊ばう」という形はない。", "遊べ": "「遊べう」という形はない。", "遊ん": "「遊んう」という形はない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
