INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51728, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "窓", "is_correct": true, "explanation": "「まど」：壁の開口部。正解。"}, {"text": "孫", "is_correct": false, "explanation": "「まご」：子の子。「ど」と「ご」の一モーラ差。"}, {"text": "豆", "is_correct": false, "explanation": "「まめ」：植物の種。「ど」と「め」の一モーラ差。"}, {"text": "的", "is_correct": false, "explanation": "「まと」：矢を当てる目標。「ど」と「と」の清濁の違い。"}, {"text": "町", "is_correct": false, "explanation": "「まち」：人が住む所。「ど」と「ち」の一モーラ差。"}, {"text": "角", "is_correct": false, "explanation": "「かど」：曲がり角。「ま」と「か」の一モーラ差。"}], "explanations": {"窓": "「まど」：壁の開口部。正解。", "孫": "「まご」：子の子。「ど」と「ご」の一モーラ差。", "豆": "「まめ」：植物の種。「ど」と「め」の一モーラ差。", "的": "「まと」：矢を当てる目標。「ど」と「と」の清濁の違い。", "町": "「まち」：人が住む所。「ど」と「ち」の一モーラ差。", "角": "「かど」：曲がり角。「ま」と「か」の一モーラ差。"}, "sentence_index": null, "correct_answer": "窓"}, "level_3": {"options": [{"text": "窓", "is_correct": true, "explanation": "意味：寒気が伝うのは窓のガラス。"}, {"text": "机", "is_correct": false, "explanation": "意味：「机ガラス」は普通ない。"}, {"text": "靴", "is_correct": false, "explanation": "連語：「靴ガラス」は不自然。"}, {"text": "皿", "is_correct": false, "explanation": "意味：寒気が皿のガラスを伝うのは文脈に合わない。"}], "explanations": {"窓": "意味：寒気が伝うのは窓のガラス。", "机": "意味：「机ガラス」は普通ない。", "靴": "連語：「靴ガラス」は不自然。", "皿": "意味：寒気が皿のガラスを伝うのは文脈に合わない。"}, "sentence_index": 0, "correct_answer": "窓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一本の窓から海が見える。", "explanation": "助数詞の誤り：窓は「枚」や「つ」で数える。"}, {"text": "窓が海を見える。", "explanation": "助詞の混同：「窓から海が見える」が正しい。"}, {"text": "窓を海が見える。", "explanation": "助詞の混同：見える場所の起点は「から」で示す。「を」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
