INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51728, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「設ける」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「窓が設ける」となり主語と目的語が逆になる。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示し、目的語にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示し、この位置では非文。"}], "correct_answer": "を", "explanations": {"を": "「設ける」の目的語を示す「を」。", "が": "「窓が設ける」となり主語と目的語が逆になる。", "で": "手段・場所を示し、目的語にならない。", "から": "起点を示し、この位置では非文。"}, "error_tags": {"が": "topic_vs_subject", "で": "instrument", "から": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51728, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "窓", "is_correct": true, "explanation": "「まど」：光や風を入れる所。正解。"}, {"text": "的", "is_correct": false, "explanation": "「まと」：目標。「ど」と「と」の清濁の違い。"}, {"text": "松", "is_correct": false, "explanation": "「まつ」：木の名前。「ど」と「つ」の一モーラ差。"}, {"text": "井戸", "is_correct": false, "explanation": "「いど」：水をくむ穴。「ま」と「い」の一モーラ差。"}, {"text": "孫", "is_correct": false, "explanation": "「まご」：子の子。「ど」と「ご」の一モーラ差。"}], "explanations": {"窓": "「まど」：光や風を入れる所。正解。", "的": "「まと」：目標。「ど」と「と」の清濁の違い。", "松": "「まつ」：木の名前。「ど」と「つ」の一モーラ差。", "井戸": "「いど」：水をくむ穴。「ま」と「い」の一モーラ差。", "孫": "「まご」：子の子。「ど」と「ご」の一モーラ差。"}, "sentence_index": null, "correct_answer": "窓"}, "level_3": {"options": [{"text": "窓", "is_correct": true, "explanation": "意味：窓の外で鳥が鳴く場面に合う。"}, {"text": "鍋", "is_correct": false, "explanation": "意味：鍋の外で鳥が鳴くのは不自然。"}, {"text": "靴", "is_correct": false, "explanation": "意味：「靴の外」は場所として不自然。"}, {"text": "皿", "is_correct": false, "explanation": "意味：皿の外で鳥が鳴くとは言わない。"}], "explanations": {"窓": "意味：窓の外で鳥が鳴く場面に合う。", "鍋": "意味：鍋の外で鳥が鳴くのは不自然。", "靴": "意味：「靴の外」は場所として不自然。", "皿": "意味：皿の外で鳥が鳴くとは言わない。"}, "sentence_index": 6, "correct_answer": "窓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓側に席を座りたい。", "explanation": "助詞の混同：「席に座る」が正しい。"}, {"text": "窓側が席に座りたい。", "explanation": "助詞の混同：名詞をつなぐのは「の」。「が」は誤り。"}, {"text": "二匹の窓側の席に座りたい。", "explanation": "助数詞の誤り：席や窓に「匹」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
