INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37041, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "内部", "is_correct": true, "explanation": "「ないぶ」：内側の部分。正解。"}, {"text": "ナイフ", "is_correct": false, "explanation": "「ないふ」：刃物。「ぶ」と「ふ」の清濁の違い。"}, {"text": "大分", "is_correct": false, "explanation": "「だいぶ」：かなり。「な」と「だ」の一モーラ差。"}, {"text": "細部", "is_correct": false, "explanation": "「さいぶ」：細かい部分。「な」と「さ」の一モーラ差。"}], "explanations": {"内部": "「ないぶ」：内側の部分。正解。", "ナイフ": "「ないふ」：刃物。「ぶ」と「ふ」の清濁の違い。", "大分": "「だいぶ」：かなり。「な」と「だ」の一モーラ差。", "細部": "「さいぶ」：細かい部分。「な」と「さ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "内部"}, "level_3": {"options": [{"text": "内部", "is_correct": true, "explanation": "意味：外側のクラストに対し、内側の部分を指す。"}, {"text": "未来", "is_correct": false, "explanation": "意味：パンの未来が瑞々しいとは言わない。"}, {"text": "理由", "is_correct": false, "explanation": "意味：「理由は瑞々しく」は意味をなさない。"}, {"text": "場合", "is_correct": false, "explanation": "連語：「場合は…クラムへと昇華する」は不自然。"}], "explanations": {"内部": "意味：外側のクラストに対し、内側の部分を指す。", "未来": "意味：パンの未来が瑞々しいとは言わない。", "理由": "意味：「理由は瑞々しく」は意味をなさない。", "場合": "連語：「場合は…クラムへと昇華する」は不自然。"}, "sentence_index": 0, "correct_answer": "内部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "機械が内部を見てみよう。", "explanation": "助詞の混同：見る人ではなく機械が主語になってしまう。「機械の内部」が正しい。"}, {"text": "機械の内部が見てみよう。", "explanation": "助詞の混同：見る対象は「を」で示す。「が」は誤り。"}, {"text": "機械の内部へ見てみよう。", "explanation": "助詞の混同：見る対象は「を」で示す。「へ」は方向で誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
