INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37041, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "「内部を光に満ちあふれ」は自動詞に合わず非文。"}, {"text": "で", "is_correct": false, "explanation": "「内部で光に満ちあふれ」は場所になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、この位置では非文。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。", "を": "「内部を光に満ちあふれ」は自動詞に合わず非文。", "で": "「内部で光に満ちあふれ」は場所になり不自然。", "へ": "方向を示し、この位置では非文。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外部", "is_correct": true, "explanation": "内側の部分に対し、外側の部分を表す。"}, {"text": "中心", "is_correct": false, "explanation": "内側に近く、反対ではない。"}, {"text": "中身", "is_correct": false, "explanation": "内側の物で、反対ではない。"}, {"text": "奥", "is_correct": false, "explanation": "内側の深い所で、反対ではない。"}], "correct_answer": "外部", "explanations": {"外部": "内側の部分に対し、外側の部分を表す。", "中心": "内側に近く、反対ではない。", "中身": "内側の物で、反対ではない。", "奥": "内側の深い所で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37041, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "内部", "is_correct": true, "explanation": "「ないぶ」：物の内側。正解。"}, {"text": "細部", "is_correct": false, "explanation": "「さいぶ」：細かい所。「な」と「さ」の一モーラ差。"}, {"text": "内科", "is_correct": false, "explanation": "「ないか」：体の中の病気を治す医学。「ぶ」と「か」の一モーラ差。"}, {"text": "内示", "is_correct": false, "explanation": "「ないじ」：正式発表前に知らせること。「ぶ」と「じ」の一モーラ差。"}], "explanations": {"内部": "「ないぶ」：物の内側。正解。", "細部": "「さいぶ」：細かい所。「な」と「さ」の一モーラ差。", "内科": "「ないか」：体の中の病気を治す医学。「ぶ」と「か」の一モーラ差。", "内示": "「ないじ」：正式発表前に知らせること。「ぶ」と「じ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "内部"}, "level_3": {"options": [{"text": "内部", "is_correct": true, "explanation": "意味：城の内側も美しいという意味になる。"}, {"text": "時間", "is_correct": false, "explanation": "意味：城の時間が美しいとは言わない。"}, {"text": "理由", "is_correct": false, "explanation": "意味：「理由も美しい」は文脈に合わない。"}, {"text": "意味", "is_correct": false, "explanation": "意味：「城は意味も美しい」は不自然。"}], "explanations": {"内部": "意味：城の内側も美しいという意味になる。", "時間": "意味：城の時間が美しいとは言わない。", "理由": "意味：「理由も美しい」は文脈に合わない。", "意味": "意味：「城は意味も美しい」は不自然。"}, "sentence_index": 6, "correct_answer": "内部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "車の内部にきれいにした。", "explanation": "助詞の混同：きれいにする物は「を」で示す。"}, {"text": "車の内部がきれいにした。", "explanation": "助詞の混同：きれいにする物は「を」で示す。"}, {"text": "車に内部をきれいにした。", "explanation": "助詞の混同：名詞をつなぐのは「の」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37041, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "内部へ変な音がする。", "corrected_sentence": "内部から変な音がする。", "error_description": "助詞の混同：音の出どころは「から」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37041, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞をつなぐ「の」。"}, {"text": "を", "is_correct": false, "explanation": "「地球を内部は」は非文。"}, {"text": "で", "is_correct": false, "explanation": "「地球で内部は」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、名詞をつなげない。"}], "correct_answer": "の", "explanations": {"の": "名詞をつなぐ「の」。", "を": "「地球を内部は」は非文。", "で": "「地球で内部は」は不自然。", "へ": "方向を示し、名詞をつなげない。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外部", "is_correct": true, "explanation": "内側に対し外側を表す、反対の語。"}, {"text": "内側", "is_correct": false, "explanation": "ほぼ同じ意味で、反対ではない。"}, {"text": "中央", "is_correct": false, "explanation": "まん中の意味で、反対ではない。"}, {"text": "底", "is_correct": false, "explanation": "下の部分で、反対ではない。"}], "correct_answer": "外部", "explanations": {"外部": "内側に対し外側を表す、反対の語。", "内側": "ほぼ同じ意味で、反対ではない。", "中央": "まん中の意味で、反対ではない。", "底": "下の部分で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35513, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "呼ぶ", "is_correct": true, "explanation": "「よぶ」：名前で言い表す。正解。"}, {"text": "読む", "is_correct": false, "explanation": "「よむ」：文字を見て理解する。「ぶ」と「む」の一モーラ差。"}, {"text": "飛ぶ", "is_correct": false, "explanation": "「とぶ」：空を動く。「よ」と「と」の一モーラ差。"}, {"text": "横", "is_correct": false, "explanation": "「よこ」：左右の方向。「ぶ」と「こ」の一モーラ差。"}, {"text": "夜", "is_correct": false, "explanation": "「よる」：日が沈んだ後。「ぶ」と「る」の一モーラ差。"}], "explanations": {"呼ぶ": "「よぶ」：名前で言い表す。正解。", "読む": "「よむ」：文字を見て理解する。「ぶ」と「む」の一モーラ差。", "飛ぶ": "「とぶ」：空を動く。「よ」と「と」の一モーラ差。", "横": "「よこ」：左右の方向。「ぶ」と「こ」の一モーラ差。", "夜": "「よる」：日が沈んだ後。「ぶ」と「る」の一モーラ差。"}, "sentence_index": null, "correct_answer": "呼ぶ"}, "level_3": {"options": [{"text": "呼び", "is_correct": true, "explanation": "意味：名前をつけて言い表すので「呼びます」。"}, {"text": "歩き", "is_correct": false, "explanation": "項構造：「〜と歩きます」は名前を表せない。"}, {"text": "泳ぎ", "is_correct": false, "explanation": "意味：「オーブンスプリングと泳ぎます」は意味をなさない。"}, {"text": "寝", "is_correct": false, "explanation": "意味：「〜と寝ます」は名前の説明にならない。"}], "explanations": {"呼び": "意味：名前をつけて言い表すので「呼びます」。", "歩き": "項構造：「〜と歩きます」は名前を表せない。", "泳ぎ": "意味：「オーブンスプリングと泳ぎます」は意味をなさない。", "寝": "意味：「〜と寝ます」は名前の説明にならない。"}, "sentence_index": 0, "correct_answer": "呼び"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この花はサクラを呼ばれている。", "explanation": "助詞の混同：名前は「と」で示す。"}, {"text": "この花はサクラと呼ばっている。", "explanation": "活用の誤り：受身は「呼ばれている」。"}, {"text": "この花はサクラと呼ぶれている。", "explanation": "活用の誤り：受身は未然形「呼ば」＋「れる」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35513, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "みんなは彼を「ケン」に呼ぶ。", "corrected_sentence": "みんなは彼を「ケン」と呼ぶ。", "error_description": "助詞の混同：呼び名は「と」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "呼ば", "is_correct": true, "explanation": "受身「れる」には未然形「呼ば」が続く。"}, {"text": "呼び", "is_correct": false, "explanation": "「呼びれる」という形はない。"}, {"text": "呼べ", "is_correct": false, "explanation": "「呼べれる」は誤った形。"}, {"text": "呼ん", "is_correct": false, "explanation": "「呼んれる」という形はない。"}], "correct_form": "呼ば", "base_form": "呼ぶ", "form_label": "活用", "sentence_index": 1, "explanations": {"呼ば": "受身「れる」には未然形「呼ば」が続く。", "呼び": "「呼びれる」という形はない。", "呼べ": "「呼べれる」は誤った形。", "呼ん": "「呼んれる」という形はない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
