INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35513, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "呼ぶ", "is_correct": true, "explanation": "「よぶ」：名前で言う。正解。"}, {"text": "酔う", "is_correct": false, "explanation": "「よう」：酒で気分が変わる。「ぶ」と「う」の一モーラ差。"}, {"text": "嫁", "is_correct": false, "explanation": "「よめ」：息子の妻。「ぶ」と「め」の一モーラ差。"}, {"text": "瘤", "is_correct": false, "explanation": "「こぶ」：体のふくらみ。「よ」と「こ」の一モーラ差。"}], "explanations": {"呼ぶ": "「よぶ」：名前で言う。正解。", "酔う": "「よう」：酒で気分が変わる。「ぶ」と「う」の一モーラ差。", "嫁": "「よめ」：息子の妻。「ぶ」と「め」の一モーラ差。", "瘤": "「こぶ」：体のふくらみ。「よ」と「こ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "呼ぶ"}, "level_3": {"options": [{"text": "呼ん", "is_correct": true, "explanation": "意味：名前で言ってほしいので「呼んでね」。"}, {"text": "済ん", "is_correct": false, "explanation": "意味：「ユミと済んでね」は意味をなさない。"}, {"text": "混ん", "is_correct": false, "explanation": "意味：「ユミと混んでね」は意味をなさない。"}, {"text": "澄ん", "is_correct": false, "explanation": "意味：「ユミと澄んでね」は意味をなさない。"}], "explanations": {"呼ん": "意味：名前で言ってほしいので「呼んでね」。", "済ん": "意味：「ユミと済んでね」は意味をなさない。", "混ん": "意味：「ユミと混んでね」は意味をなさない。", "澄ん": "意味：「ユミと澄んでね」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "呼ん"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生に名前で呼んではいけない。", "explanation": "助詞の混同：呼ぶ相手は「を」で示す。"}, {"text": "先生を名前で呼んだはいけない。", "explanation": "活用の誤り：「〜てはいけない」にはて形が必要。"}, {"text": "先生を名前に呼んではいけない。", "explanation": "助詞の混同：呼ぶ手段の名前は「で」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
