INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38479, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "建設", "is_correct": true, "explanation": "「けんせつ」：大きな物を造ること。正解。"}, {"text": "関節", "is_correct": false, "explanation": "「かんせつ」：骨のつなぎ目。「け」と「か」の一モーラ差。"}, {"text": "親切", "is_correct": false, "explanation": "「しんせつ」：思いやり。「け」と「し」の一モーラ差。"}, {"text": "面接", "is_correct": false, "explanation": "「めんせつ」：会って話す試験。「け」と「め」の一モーラ差。"}, {"text": "牽制", "is_correct": false, "explanation": "「けんせい」：相手をおさえること。「つ」と「い」の一モーラ差。"}], "explanations": {"建設": "「けんせつ」：大きな物を造ること。正解。", "関節": "「かんせつ」：骨のつなぎ目。「け」と「か」の一モーラ差。", "親切": "「しんせつ」：思いやり。「け」と「し」の一モーラ差。", "面接": "「めんせつ」：会って話す試験。「け」と「め」の一モーラ差。", "牽制": "「けんせい」：相手をおさえること。「つ」と「い」の一モーラ差。"}, "sentence_index": null, "correct_answer": "建設"}, "level_3": {"options": [{"text": "建設", "is_correct": true, "explanation": "意味：みんなで建物などを造っている。"}, {"text": "睡眠", "is_correct": false, "explanation": "意味：一緒に睡眠をしているは不自然。"}, {"text": "欠席", "is_correct": false, "explanation": "意味：一緒に欠席をしていますは文脈に合わない。"}, {"text": "失敗", "is_correct": false, "explanation": "意味：一緒に失敗をしていますは文意に合わない。"}], "explanations": {"建設": "意味：みんなで建物などを造っている。", "睡眠": "意味：一緒に睡眠をしているは不自然。", "欠席": "意味：一緒に欠席をしていますは文脈に合わない。", "失敗": "意味：一緒に失敗をしていますは文意に合わない。"}, "sentence_index": 0, "correct_answer": "建設"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい学校が建設している。", "explanation": "助詞の混同：造る物は「を」で示す。"}, {"text": "新しい学校に建設している。", "explanation": "助詞の混同：造る物は「を」で示す。"}, {"text": "新しい学校を建設でしている。", "explanation": "語形の誤り：「建設する」に「で」は入らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
