INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38479, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "対象を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「建設をは」は非文。"}, {"text": "が", "is_correct": false, "explanation": "「建設がは」は非文。"}, {"text": "から", "is_correct": false, "explanation": "起点を示し、この位置では不自然。"}], "correct_answer": "に", "explanations": {"に": "対象を示す「に」。", "を": "「建設をは」は非文。", "が": "「建設がは」は非文。", "から": "起点を示し、この位置では不自然。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "から": "source_vs_goal"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破壊", "is_correct": true, "explanation": "造ることに対し、壊すことを表す。"}, {"text": "工事", "is_correct": false, "explanation": "造る作業で、反対ではない。"}, {"text": "計画", "is_correct": false, "explanation": "前もって考えることで、反対ではない。"}, {"text": "修理", "is_correct": false, "explanation": "直すことで、反対ではない。"}], "correct_answer": "破壊", "explanations": {"破壊": "造ることに対し、壊すことを表す。", "工事": "造る作業で、反対ではない。", "計画": "前もって考えることで、反対ではない。", "修理": "直すことで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
