INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37599, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "工学", "is_correct": true, "explanation": "「こうがく」：科学を応用する学問。正解。"}, {"text": "郊外", "is_correct": false, "explanation": "「こうがい」：町の外側。「く」と「い」の一モーラ差。"}, {"text": "総額", "is_correct": false, "explanation": "「そうがく」：合計の金額。「こ」と「そ」の一モーラ差。"}, {"text": "広角", "is_correct": false, "explanation": "「こうかく」：広い角度。「が」と「か」の清濁の違い。"}, {"text": "小額", "is_correct": false, "explanation": "「しょうがく」：少ない金額。「こ」と「しょ」の一モーラ差。"}], "explanations": {"工学": "「こうがく」：科学を応用する学問。正解。", "郊外": "「こうがい」：町の外側。「く」と「い」の一モーラ差。", "総額": "「そうがく」：合計の金額。「こ」と「そ」の一モーラ差。", "広角": "「こうかく」：広い角度。「が」と「か」の清濁の違い。", "小額": "「しょうがく」：少ない金額。「こ」と「しょ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "工学"}, "level_3": {"options": [{"text": "工学", "is_correct": true, "explanation": "意味：ロボットを作る学問は工学。"}, {"text": "料理", "is_correct": false, "explanation": "連語：「ロボット料理」は不自然。"}, {"text": "天気", "is_correct": false, "explanation": "意味：「ロボット天気」は意味をなさない。"}, {"text": "家族", "is_correct": false, "explanation": "意味：「ロボット家族の深淵を志す」は文脈に合わない。"}], "explanations": {"工学": "意味：ロボットを作る学問は工学。", "料理": "連語：「ロボット料理」は不自然。", "天気": "意味：「ロボット天気」は意味をなさない。", "家族": "意味：「ロボット家族の深淵を志す」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "工学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工学を興味があります。", "explanation": "助詞の混同：興味の対象は「に」で示す。"}, {"text": "工学が興味があります。", "explanation": "助詞の混同：興味の対象は「に」で示す。"}, {"text": "工学で興味があります。", "explanation": "助詞の混同：興味の対象は「に」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EX