INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37599, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "工学", "is_correct": true, "explanation": "「こうがく」：物を作る学問。正解。"}, {"text": "法学", "is_correct": false, "explanation": "「ほうがく」：法律の学問。「こ」と「ほ」の一モーラ差。"}, {"text": "同額", "is_correct": false, "explanation": "「どうがく」：同じ金額。「こ」と「ど」の一モーラ差。"}, {"text": "郊外", "is_correct": false, "explanation": "「こうがい」：都市の周り。「く」と「い」の一モーラ差。"}], "explanations": {"工学": "「こうがく」：物を作る学問。正解。", "法学": "「ほうがく」：法律の学問。「こ」と「ほ」の一モーラ差。", "同額": "「どうがく」：同じ金額。「こ」と「ど」の一モーラ差。", "郊外": "「こうがい」：都市の周り。「く」と「い」の一モーラ差。"}, "sentence_index": null, "correct_answer": "工学"}, "level_3": {"options": [{"text": "工学", "is_correct": true, "explanation": "意味：工学の研究は自然。"}, {"text": "昼休み", "is_correct": false, "explanation": "意味：昼休みの研究は文脈に合わない。"}, {"text": "夕飯", "is_correct": false, "explanation": "意味：夕飯の研究をしているは不自然。"}, {"text": "週末", "is_correct": false, "explanation": "意味：週末の研究は研究の分野にならない。"}], "explanations": {"工学": "意味：工学の研究は自然。", "昼休み": "意味：昼休みの研究は文脈に合わない。", "夕飯": "意味：夕飯の研究をしているは不自然。", "週末": "意味：週末の研究は研究の分野にならない。"}, "sentence_index": 6, "correct_answer": "工学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工学に先生に質問した。", "explanation": "助詞の混同：名詞をつなぐのは「の」。"}, {"text": "工学の先生を質問した。", "explanation": "助詞の混同：質問する相手は「に」。"}, {"text": "工学を先生に質問した。", "explanation": "助詞の混同：名詞をつなぐのは「の」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b18177cf-717d-40a0-87b8-ee4a25ad7ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
