INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38639, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を行うときの決まった形や方法。また、建物や芸術などに共通する特徴的な型。", "primary_collocate": null, "pronunciation": "ようしき", "ipa": "joːɕiki", "syllable_count": 4, "sentences": [{"text": "戦後の都市計画において、ブルータリズムは機能性を重視した新たな住宅様式として普及しました。", "target_word": "様式", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "中世ヨーロッパで発展したゴシック様式の大聖堂は、その圧倒的な高さと美しさで人々を魅了しました。", "target_word": "様式", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "この寺は古い様式で建てられている。", "target_word": "様式", "complexity_tier": "T3", "furigana": "てら ふる ようしき た", "sentence_source": "generated"}, {"text": "申込書の様式を確認してください。", "target_word": "様式", "complexity_tier": "T3", "furigana": "もうしこみしょ ようしき かくにん", "sentence_source": "generated"}, {"text": "生活の様式が大きく変わった。", "target_word": "様式", "complexity_tier": "T3", "furigana": "せいかつ ようしき おお か", "sentence_source": "generated"}, {"text": "様式は自由に選べます。", "target_word": "様式", "complexity_tier": "T3", "furigana": "ようしき じゆう えら", "sentence_source": "generated"}, {"text": "この絵は独特な様式を持っている。", "target_word": "様式", "complexity_tier": "T3", "furigana": "え どくとく ようしき も", "sentence_source": "generated"}, {"text": "和と洋の様式が混ざった家だ。", "target_word": "様式", "complexity_tier": "T3", "furigana": "わ よう ようしき ま いえ", "sentence_source": "generated"}, {"text": "決まった様式で書く必要がある。", "target_word": "様式", "complexity_tier": "T3", "furigana": "き ようしき か ひつよう", "sentence_source": "generated"}, {"text": "新しい様式の音楽が生まれた。", "target_word": "様式", "complexity_tier": "T3", "furigana": "あたら ようしき おんがく う", "sentence_source": "generated"}], "morphological_forms": [{"form": "様式美", "label": "派生"}, {"form": "生活様式", "label": "派生"}, {"form": "建築様式", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 決まった形式・芸術の型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca67e41-f463-4c4c-aaf0-3621251427b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36731, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "関心を持って、あるものごとに特に目を向けること。", "primary_collocate": null, "pronunciation": "ちゅうもく", "ipa": "tɕɯːmokɯ", "syllable_count": 4, "sentences": [{"text": "近年、センサーやデータ解析技術を活用した「精密農業」が注目されています。", "target_word": "注目", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "特に注目すべきは、天井の重量を分散させる「リブ・ヴォールト」と、壁の外側から支える「フライング・バットレス」と呼ばれる技術です。", "target_word": "注目", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "彼の新しい曲が注目を集めている。", "target_word": "注目", "complexity_tier": "T3", "furigana": "かれ あたら きょく ちゅうもく あつ", "sentence_source": "generated"}, {"text": "みんなが彼女に注目した。", "target_word": "注目", "complexity_tier": "T3", "furigana": "かのじょ ちゅうもく", "sentence_source": "generated"}, {"text": "この点に注目してください。", "target_word": "注目", "complexity_tier": "T3", "furigana": "てん ちゅうもく", "sentence_source": "generated"}, {"text": "注目の試合が明日始まる。", "target_word": "注目", "complexity_tier": "T3", "furigana": "ちゅうもく しあい あした はじ", "sentence_source": "generated"}, {"text": "その選手は世界から注目されている。", "target_word": "注目", "complexity_tier": "T3", "furigana": "せんしゅ せかい ちゅうもく", "sentence_source": "generated"}, {"text": "先生の話に注目しよう。", "target_word": "注目", "complexity_tier": "T3", "furigana": "せんせい はなし ちゅうもく", "sentence_source": "generated"}, {"text": "注目を浴びるのは苦手だ。", "target_word": "注目", "complexity_tier": "T3", "furigana": "ちゅうもく あ にがて", "sentence_source": "generated"}, {"text": "今年注目の本を読んだ。", "target_word": "注目", "complexity_tier": "T3", "furigana": "ことし ちゅうもく ほん よ", "sentence_source": "generated"}], "morphological_forms": [{"form": "注目する", "label": "派生"}, {"form": "注目される", "label": "活用"}, {"form": "注目度", "label": "派生"}, {"form": "注目株", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 関心を持って目を向けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca67e41-f463-4c4c-aaf0-3621251427b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36119, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "気体や液体などの体積が増えて大きくなること。また、範囲や規模が広がること。", "primary_collocate": null, "pronunciation": "ぼうちょう", "ipa": "boːtɕoː", "syllable_count": 4, "sentences": [{"text": "高温のオーブンへ投入された瞬間、生地は熱エネルギーによって急激に膨張します。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "空気は温めると膨張する。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "くうき あたた ぼうちょう", "sentence_source": "generated"}, {"text": "鉄道のレールは夏に膨張する。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "てつどう なつ ぼうちょう", "sentence_source": "generated"}, {"text": "風船の中の気体が膨張した。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "ふうせん なか きたい ぼうちょう", "sentence_source": "generated"}, {"text": "宇宙は今も膨張している。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "うちゅう いま ぼうちょう", "sentence_source": "generated"}, {"text": "都市の膨張が問題になっている。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "とし ぼうちょう もんだい", "sentence_source": "generated"}, {"text": "水は凍ると膨張する。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "みず こお ぼうちょう", "sentence_source": "generated"}, {"text": "熱による膨張を考えて作る。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "ねつ ぼうちょう かんが つく", "sentence_source": "generated"}, {"text": "予算の膨張を止めたい。", "target_word": "膨張", "complexity_tier": "T3", "furigana": "よさん ぼうちょう と", "sentence_source": "generated"}], "morphological_forms": [{"form": "膨張する", "label": "派生"}, {"form": "膨張した", "label": "活用"}, {"form": "熱膨張", "label": "派生"}, {"form": "膨張率", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 体積や規模が大きくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: ベーキング (Zipf 1.24), 瑞々しく (Zipf 1.76)']::text[], 'fca67e41-f463-4c4c-aaf0-3621251427b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51480, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "微生物や細胞などに栄養を与え、適した環境で増やし育てること。", "primary_collocate": null, "pronunciation": "ばいよう", "ipa": "baijoː", "syllable_count": 4, "sentences": [{"text": "その過程は、微生物を培養する「種起こし」から始まります。", "target_word": "培養", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "数日かけて培養されたルヴァン種は、独特の酸味と芳醇な香りを纏い、パンの骨格を形成する。", "target_word": "培養", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "研究室で細菌を培養している。", "target_word": "培養", "complexity_tier": "T3", "furigana": "けんきゅうしつ さいきん ばいよう", "sentence_source": "generated"}, {"text": "細胞の培養には時間がかかる。", "target_word": "培養", "complexity_tier": "T3", "furigana": "さいぼう ばいよう じかん", "sentence_source": "generated"}, {"text": "培養した酵母でパンを作る。", "target_word": "培養", "complexity_tier": "T3", "furigana": "ばいよう こうぼ つく", "sentence_source": "generated"}, {"text": "温度を保って培養する。", "target_word": "培養", "complexity_tier": "T3", "furigana": "おんど たも ばいよう", "sentence_source": "generated"}, {"text": "培養の結果をノートに書いた。", "target_word": "培養", "complexity_tier": "T3", "furigana": "ばいよう けっか か", "sentence_source": "generated"}, {"text": "この菌は培養が難しい。", "target_word": "培養", "complexity_tier": "T3", "furigana": "きん ばいよう むずか", "sentence_source": "generated"}, {"text": "彼は皮膚の細胞を培養した。", "target_word": "培養", "complexity_tier": "T3", "furigana": "かれ ひふ さいぼう ばいよう", "sentence_source": "generated"}, {"text": "培養に使う液を用意した。", "target_word": "培養", "complexity_tier": "T3", "furigana": "ばいよう つか えき ようい", "sentence_source": "generated"}], "morphological_forms": [{"form": "培養する", "label": "派生"}, {"form": "培養された", "label": "活用"}, {"form": "培養液", "label": "派生"}, {"form": "培養肉", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 微生物や細胞を育てること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: 4 words above tier T3 (max 3): ルヴァン (Zipf 2.53), 酸味 (Zipf 3.39), 芳醇 (Zipf 2.57), 纏い (Zipf 2.78)']::text[], 'fca67e41-f463-4c4c-aaf0-3621251427b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51482, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "温度や気温が高いこと。", "primary_collocate": null, "pronunciation": "こうおん", "ipa": "koːoɴ", "syllable_count": 4, "sentences": [{"text": "高温のオーブンへ投入された瞬間、生地は熱エネルギーによって急激に膨張します。", "target_word": "高温", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "高温", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "今日は高温に注意してください。", "target_word": "高温", "complexity_tier": "T3", "furigana": "きょう こうおん ちゅうい", "sentence_source": "generated"}, {"text": "この部品は高温に弱い。", "target_word": "高温", "complexity_tier": "T3", "furigana": "ぶひん こうおん よわ", "sentence_source": "generated"}, {"text": "高温で短い時間焼く。", "target_word": "高温", "complexity_tier": "T3", "furigana": "こうおん みじか じかん や", "sentence_source": "generated"}, {"text": "夏の高温が続いている。", "target_word": "高温", "complexity_tier": "T3", "furigana": "なつ こうおん つづ", "sentence_source": "generated"}, {"text": "高温の場所に置かないで。", "target_word": "高温", "complexity_tier": "T3", "furigana": "こうおん ばしょ お", "sentence_source": "generated"}, {"text": "日本の夏は高温で湿気が多い。", "target_word": "高温", "complexity_tier": "T3", "furigana": "にほん なつ こうおん しっけ おお", "sentence_source": "generated"}, {"text": "鉄は高温になると赤くなる。", "target_word": "高温", "complexity_tier": "T3", "furigana": "てつ こうおん あか", "sentence_source": "generated"}, {"text": "高温の油に気をつけよう。", "target_word": "高温", "complexity_tier": "T3", "furigana": "こうおん あぶら き", "sentence_source": "generated"}], "morphological_forms": [{"form": "高温多湿", "label": "派生"}, {"form": "高温期", "label": "派生"}, {"form": "高温注意", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 温度が高い状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: ベーキング (Zipf 1.24), 瑞々しく (Zipf 1.76)']::text[], 'fca67e41-f463-4c4c-aaf0-3621251427b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
