INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41335, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "食べ物や飲み物を口にしたときに感じる、香りや味わいの特徴。", "primary_collocate": null, "pronunciation": "ふうみ", "ipa": "ɸɯːmi", "syllable_count": 3, "sentences": [{"text": "一連の科学的な変化を経て、風味豊かなパンが完成するのです。", "target_word": "風味", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "さらに、アミノ酸や有機酸が複雑に絡み合い、主食に奥深い風味と旨味の層を付与する。", "target_word": "風味", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "このお茶は風味がとてもいい。", "target_word": "風味", "complexity_tier": "T3", "furigana": "ちゃ ふうみ", "sentence_source": "generated"}, {"text": "バターの風味が口に広がった。", "target_word": "風味", "complexity_tier": "T3", "furigana": "ふうみ くち ひろ", "sentence_source": "generated"}, {"text": "レモンで風味をつけてみた。", "target_word": "風味", "complexity_tier": "T3", "furigana": "ふうみ", "sentence_source": "generated"}, {"text": "古いコーヒーは風味が落ちる。", "target_word": "風味", "complexity_tier": "T3", "furigana": "ふる ふうみ お", "sentence_source": "generated"}, {"text": "祖母のみそ汁は独特の風味がある。", "target_word": "風味", "complexity_tier": "T3", "furigana": "そぼ しる どくとく ふうみ", "sentence_source": "generated"}, {"text": "この風味は母の味に似ている。", "target_word": "風味", "complexity_tier": "T3", "furigana": "ふうみ はは あじ に", "sentence_source": "generated"}, {"text": "新鮮な野菜は風味が強い。", "target_word": "風味", "complexity_tier": "T3", "furigana": "しんせん やさい ふうみ つよ", "sentence_source": "generated"}, {"text": "風味を生かすため、塩は少しにした。", "target_word": "風味", "complexity_tier": "T3", "furigana": "ふうみ い しお すこ", "sentence_source": "generated"}], "morphological_forms": [{"form": "風味豊か", "label": "派生"}, {"form": "風味付け", "label": "派生"}, {"form": "風味がよい", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 食べ物の香りと味わいの特徴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c14caa3-e76e-467a-9dee-316b0111ba35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39423, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事の状態や程度が、短い時間に大きく変わる様子。", "primary_collocate": null, "pronunciation": "きゅうげき", "ipa": "kʲɯːɡeki", "syllable_count": 4, "sentences": [{"text": "高温のオーブンへ投入された瞬間、生地は熱エネルギーによって急激に膨張します。", "target_word": "急激", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "しかし、産業革命以降の急激な人間活動、とりわけ化石燃料の大量消費と森林破壊は、この循環に深刻な破綻をもたらした。", "target_word": "急激", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "気温が急激に下がった。", "target_word": "急激", "complexity_tier": "T3", "furigana": "きおん きゅうげき さ", "sentence_source": "generated"}, {"text": "急激な変化に体がついていけない。", "target_word": "急激", "complexity_tier": "T3", "furigana": "きゅうげき へんか からだ", "sentence_source": "generated"}, {"text": "町の人口が急激に増えている。", "target_word": "急激", "complexity_tier": "T3", "furigana": "まち じんこう きゅうげき ふ", "sentence_source": "generated"}, {"text": "急激な運動は体によくない。", "target_word": "急激", "complexity_tier": "T3", "furigana": "きゅうげき うんどう からだ", "sentence_source": "generated"}, {"text": "円の価値が急激に変わった。", "target_word": "急激", "complexity_tier": "T3", "furigana": "えん かち きゅうげき か", "sentence_source": "generated"}, {"text": "その変化はあまりに急激だった。", "target_word": "急激", "complexity_tier": "T3", "furigana": "へんか きゅうげき", "sentence_source": "generated"}, {"text": "急激なダイエットは危ない。", "target_word": "急激", "complexity_tier": "T3", "furigana": "きゅうげき あぶ", "sentence_source": "generated"}, {"text": "夕方から風が急激に強くなった。", "target_word": "急激", "complexity_tier": "T3", "furigana": "ゆうがた かぜ きゅうげき つよ", "sentence_source": "generated"}], "morphological_forms": [{"form": "急激に", "label": "活用"}, {"form": "急激な", "label": "活用"}, {"form": "急激だ", "label": "活用"}, {"form": "急激さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 短時間に大きく変わる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c14caa3-e76e-467a-9dee-316b0111ba35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52752, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人間の精神や心の本質。また、物事の中心となる大切な部分。", "primary_collocate": null, "pronunciation": "たましい", "ipa": "tamaɕiː", "syllable_count": 4, "sentences": [{"text": "靴紐を固く結び、踵で床を鳴らせば、鈍い音が魂の鼓動と共鳴する。", "target_word": "魂", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "まさに、大地と対話するその姿勢こそが、未来を担う魂の育成に他ならないのだろう。", "target_word": "魂", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "彼は作品に魂を込めた。", "target_word": "魂", "complexity_tier": "T3", "furigana": "かれ さくひん たましい こ", "sentence_source": "generated"}, {"text": "その歌は私の魂を動かした。", "target_word": "魂", "complexity_tier": "T3", "furigana": "うた わたし たましい うご", "sentence_source": "generated"}, {"text": "魂の叫びが聞こえるようだ。", "target_word": "魂", "complexity_tier": "T3", "furigana": "たましい さけ き", "sentence_source": "generated"}, {"text": "職人の魂がこの皿に宿っている。", "target_word": "魂", "complexity_tier": "T3", "furigana": "しょくにん たましい さら やど", "sentence_source": "generated"}, {"text": "死んでも魂は残ると信じている。", "target_word": "魂", "complexity_tier": "T3", "furigana": "し たましい のこ しん", "sentence_source": "generated"}, {"text": "彼女の魂は強くて優しい。", "target_word": "魂", "complexity_tier": "T3", "furigana": "かのじょ たましい つよ やさ", "sentence_source": "generated"}, {"text": "音楽は魂の言葉だと思う。", "target_word": "魂", "complexity_tier": "T3", "furigana": "おんがく たましい ことば おも", "sentence_source": "generated"}, {"text": "魂のない絵は人の心に届かない。", "target_word": "魂", "complexity_tier": "T3", "furigana": "たましい え ひと こころ とど", "sentence_source": "generated"}], "morphological_forms": [{"form": "魂を込める", "label": "派生"}, {"form": "大和魂", "label": "派生"}, {"form": "負けじ魂", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人の心や精神の本質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 6 words above tier T2 (max 3): 固く (Zipf 3.62), 踵 (Zipf 3.15), 鳴らせ (Zipf 3.25), 鈍い (Zipf 3.23), 鼓動 (Zipf 3.46), 共鳴 (Zipf 3.38)']::text[], '6c14caa3-e76e-467a-9dee-316b0111ba35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36903, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "鼻で感じる、空気中に漂うもののにおい。香りや悪臭など。", "primary_collocate": null, "pronunciation": "におい", "ipa": "ɲioi", "syllable_count": 3, "sentences": [{"text": "革の匂いが漂う暗闇の奥底で、長き眠りについていたそれを引きずり出した瞬間、埃っぽい記憶の粒子が舞い上がる。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "軋む音とともに、懐かしいシナモンの匂いが記憶の奥から鮮やかに蘇り、私は思わず息を呑んだ。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "台所からカレーの匂いがする。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "だいどころ におい", "sentence_source": "generated"}, {"text": "花のいい匂いが部屋に広がった。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "はな におい へや ひろ", "sentence_source": "generated"}, {"text": "雨の匂いをかぐと夏を思い出す。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "あめ におい なつ おも だ", "sentence_source": "generated"}, {"text": "この匂いは何だろう。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "におい なん", "sentence_source": "generated"}, {"text": "犬は匂いで人を見分けられる。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "いぬ におい ひと みわ", "sentence_source": "generated"}, {"text": "焼きたてのパンの匂いが好きだ。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "や におい す", "sentence_source": "generated"}, {"text": "変な匂いがして窓を開けた。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "へん におい まど あ", "sentence_source": "generated"}, {"text": "祖母の家は畳の匂いがした。", "target_word": "匂い", "complexity_tier": "T3", "furigana": "そぼ いえ たたみ におい", "sentence_source": "generated"}], "morphological_forms": [{"form": "匂う", "label": "派生"}, {"form": "匂いがする", "label": "派生"}, {"form": "匂い袋", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 鼻で感じるにおい・香り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 5 words above tier T2 (max 3): 奥底 (Zipf 3.21), 長き (Zipf 3.3), 引きずり出し (Zipf 2.55), 埃 (Zipf 3.54), 舞い上がる (Zipf 2.61)','sentence 1 above tier T2: contains vocabulary far above tier T2: 軋む (Zipf 2.32)']::text[], '6c14caa3-e76e-467a-9dee-316b0111ba35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35927, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物が振動して生じ、耳に聞こえるもの。", "primary_collocate": null, "pronunciation": "おと", "ipa": "oto", "syllable_count": 2, "sentences": [{"text": "靴紐を固く結び、踵で床を鳴らせば、鈍い音が魂の鼓動と共鳴する。", "target_word": "音", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "軋む音とともに、懐かしいシナモンの匂いが記憶の奥から鮮やかに蘇り、私は思わず息を呑んだ。", "target_word": "音", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "外で大きな音がした。", "target_word": "音", "complexity_tier": "T3", "furigana": "そと おお おと", "sentence_source": "generated"}, {"text": "雨の音を聞きながら寝た。", "target_word": "音", "complexity_tier": "T3", "furigana": "あめ おと き ね", "sentence_source": "generated"}, {"text": "ドアを閉める音がうるさい。", "target_word": "音", "complexity_tier": "T3", "furigana": "し おと", "sentence_source": "generated"}, {"text": "テレビの音を小さくしてください。", "target_word": "音", "complexity_tier": "T3", "furigana": "おと ちい", "sentence_source": "generated"}, {"text": "ピアノの音がきれいに響いている。", "target_word": "音", "complexity_tier": "T3", "furigana": "おと ひび", "sentence_source": "generated"}, {"text": "この時計は音がしない。", "target_word": "音", "complexity_tier": "T3", "furigana": "とけい おと", "sentence_source": "generated"}, {"text": "夜中に変な音が聞こえた。", "target_word": "音", "complexity_tier": "T3", "furigana": "よなか へん おと き", "sentence_source": "generated"}, {"text": "波の音は心を落ち着かせる。", "target_word": "音", "complexity_tier": "T3", "furigana": "なみ おと こころ お つ", "sentence_source": "generated"}], "morphological_forms": [{"form": "物音", "label": "派生"}, {"form": "足音", "label": "派生"}, {"form": "音を立てる", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 耳に聞こえる物の響き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 7 words above tier T1 (max 2): 固く (Zipf 3.62), 結び (Zipf 3.91), 踵 (Zipf 3.15), 鳴らせ (Zipf 3.25), 鈍い (Zipf 3.23), 鼓動 (Zipf 3.46)','sentence 1 above tier T1: contains vocabulary far above tier T1: 軋む (Zipf 2.32)']::text[], '6c14caa3-e76e-467a-9dee-316b0111ba35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52346, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "情報や気持ちなどを伝えるための手段や、仲立ちとなるもの。", "primary_collocate": null, "pronunciation": "ばいたい", "ipa": "baitai", "syllable_count": 4, "sentences": [{"text": "深紅とも、あるいは乾いた血の色とも形容すべきそのブーツは、もはや単なる履物という枠組みを超え、私の内面に潜む情動を可視化する媒体となっているのだ。\n\n指先でなぞる革の質感は、過ぎ去りし季節の冷たさと、それに抗った熱気を同時に記憶している。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "ワインという液体媒体において、テロワールは単なる気象・地質学的変数の集合体ではなく、地質学的記憶が液相内に結晶化した記号系として機能する。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "新聞は情報を伝える媒体だ。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "しんぶん じょうほう つた ばいたい", "sentence_source": "generated"}, {"text": "若者は新しい媒体でニュースを見る。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "わかもの あたら ばいたい み", "sentence_source": "generated"}, {"text": "音楽は気持ちを伝える媒体になる。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "おんがく き も つた ばいたい", "sentence_source": "generated"}, {"text": "データを別の媒体に保存した。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "べつ ばいたい ほぞん", "sentence_source": "generated"}, {"text": "この媒体は多くの人に読まれている。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "ばいたい おお ひと よ", "sentence_source": "generated"}, {"text": "空気は音を伝える媒体である。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "くうき おと つた ばいたい", "sentence_source": "generated"}, {"text": "広告をどの媒体に出すか考えた。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "こうこく ばいたい だ かんが", "sentence_source": "generated"}, {"text": "紙の媒体を使う人は減っている。", "target_word": "媒体", "complexity_tier": "T3", "furigana": "かみ ばいたい つか ひと へ", "sentence_source": "generated"}], "morphological_forms": [{"form": "広告媒体", "label": "派生"}, {"form": "記録媒体", "label": "派生"}, {"form": "媒体を通じて", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 情報や作用を伝える手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 10 words above tier T3 (max 3): 深紅 (Zipf 2.91), 形容 (Zipf 3.21), 履物 (Zipf 2.6), 潜む (Zipf 3.39), 情動 (Zipf 2.72), なぞる (Zipf 2.97)','sentence 1 above tier T3: contains vocabulary far above tier T3: テロワール (Zipf 1.81)']::text[], '6c14caa3-e76e-467a-9dee-316b0111ba35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41335, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "風味", "is_correct": true, "explanation": "正解。読みは「ふうみ」。"}, {"text": "風刺", "is_correct": false, "explanation": "読みは「ふうし」。「み」が「し」に変わる一モーラ差。"}, {"text": "風雨", "is_correct": false, "explanation": "読みは「ふうう」。「み」が「う」に変わる一モーラ差。"}, {"text": "夫婦", "is_correct": false, "explanation": "読みは「ふうふ」。「み」が「ふ」に変わる一モーラ差。"}, {"text": "興味", "is_correct": false, "explanation": "読みは「きょうみ」。「ふ」が「きょ」に変わる一モーラ差。"}, {"text": "富貴", "is_correct": false, "explanation": "読みは「ふうき」。「み」が「き」に変わる一モーラ差。"}], "explanations": {"風味": "正解。読みは「ふうみ」。", "風刺": "読みは「ふうし」。「み」が「し」に変わる一モーラ差。", "風雨": "読みは「ふうう」。「み」が「う」に変わる一モーラ差。", "夫婦": "読みは「ふうふ」。「み」が「ふ」に変わる一モーラ差。", "興味": "読みは「きょうみ」。「ふ」が「きょ」に変わる一モーラ差。", "富貴": "読みは「ふうき」。「み」が「き」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "風味"}, "level_3": {"options": [{"text": "風味", "is_correct": true, "explanation": "パンの香りと味わいが豊かという意味で「風味」が入る。"}, {"text": "音", "is_correct": false, "explanation": "「音豊かなパン」とは言わない。"}, {"text": "重量", "is_correct": false, "explanation": "「重量豊か」は不自然な表現。"}, {"text": "値段", "is_correct": false, "explanation": "「値段豊か」とは言わない。"}], "explanations": {"風味": "パンの香りと味わいが豊かという意味で「風味」が入る。", "音": "「音豊かなパン」とは言わない。", "重量": "「重量豊か」は不自然な表現。", "値段": "「値段豊か」とは言わない。"}, "sentence_index": 0, "correct_answer": "風味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "バターの風味が耳に聞こえた。", "explanation": "「風味」は耳で聞くものではない。"}, {"text": "バターの風味を三冊買った。", "explanation": "「風味」は冊で数える物ではない。"}, {"text": "彼の風味はとても速く走る。", "explanation": "「風味」は人の能力ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f516f50-7063-491d-b66b-340af3540cd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
