INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39423, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "急激", "is_correct": true, "explanation": "正解。読みは「きゅうげき」。"}, {"text": "襲撃", "is_correct": false, "explanation": "読みは「しゅうげき」。「きゅ」が「しゅ」に変わる一モーラ差。"}, {"text": "遊撃", "is_correct": false, "explanation": "読みは「ゆうげき」。「きゅ」が「ゆ」に変わる一モーラ差。"}, {"text": "攻撃", "is_correct": false, "explanation": "読みは「こうげき」。「きゅ」が「こ」に変わる一モーラ差。"}, {"text": "銃撃", "is_correct": false, "explanation": "読みは「じゅうげき」。「きゅ」が「じゅ」に変わる一モーラ差。"}, {"text": "仇敵", "is_correct": false, "explanation": "読みは「きゅうてき」。「げ」が「て」に変わる一モーラ差。"}], "explanations": {"急激": "正解。読みは「きゅうげき」。", "襲撃": "読みは「しゅうげき」。「きゅ」が「しゅ」に変わる一モーラ差。", "遊撃": "読みは「ゆうげき」。「きゅ」が「ゆ」に変わる一モーラ差。", "攻撃": "読みは「こうげき」。「きゅ」が「こ」に変わる一モーラ差。", "銃撃": "読みは「じゅうげき」。「きゅ」が「じゅ」に変わる一モーラ差。", "仇敵": "読みは「きゅうてき」。「げ」が「て」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "急激"}, "level_3": {"options": [{"text": "急激", "is_correct": true, "explanation": "高温で一気にふくらむ様子なので「急激」が入る。"}, {"text": "正直", "is_correct": false, "explanation": "「正直に膨張する」は物の変化には使えない。"}, {"text": "丁寧", "is_correct": false, "explanation": "「丁寧に膨張する」は物の変化には使えない。"}, {"text": "退屈", "is_correct": false, "explanation": "「退屈に膨張する」は意味を成さない。"}], "explanations": {"急激": "高温で一気にふくらむ様子なので「急激」が入る。", "正直": "「正直に膨張する」は物の変化には使えない。", "丁寧": "「丁寧に膨張する」は物の変化には使えない。", "退屈": "「退屈に膨張する」は意味を成さない。"}, "sentence_index": 0, "correct_answer": "急激"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "急激な人に体がついていけない。", "explanation": "「急激」は人の性質ではなく変化の速さを表す。"}, {"text": "急激なりんごを食べた。", "explanation": "「急激」は物の性質を表さない。"}, {"text": "急激な色の服を着た。", "explanation": "「急激」は色を形容しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f516f50-7063-491d-b66b-340af3540cd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_versi