INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52752, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "この位置に自然に入る助詞。"}, {"text": "を", "is_correct": false, "explanation": "「姿勢を…育成に他ならない」は非文。"}, {"text": "に", "is_correct": false, "explanation": "「姿勢に…他ならない」は主語がなくなり非文。"}, {"text": "で", "is_correct": false, "explanation": "「姿勢で」では述語と結びつかない。"}], "correct_answer": "が", "explanations": {"が": "この位置に自然に入る助詞。", "を": "「姿勢を…育成に他ならない」は非文。", "に": "「姿勢に…他ならない」は主語がなくなり非文。", "で": "「姿勢で」では述語と結びつかない。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肉体", "is_correct": true, "explanation": "目に見える体で、「魂」と対になる。"}, {"text": "精神", "is_correct": false, "explanation": "心の働きで、むしろ近い意味。"}, {"text": "心", "is_correct": false, "explanation": "魂とほぼ同じ側にある語。"}, {"text": "命", "is_correct": false, "explanation": "生きる力で、対義ではない。"}], "correct_answer": "肉体", "explanations": {"肉体": "目に見える体で、「魂」と対になる。", "精神": "心の働きで、むしろ近い意味。", "心": "魂とほぼ同じ側にある語。", "命": "生きる力で、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f516f50-7063-491d-b66b-340af3540cd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52752, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "魂", "is_correct": true, "explanation": "正解。読みは「たましい」。"}, {"text": "正しい", "is_correct": false, "explanation": "読みは「ただしい」。「ま」が「だ」に変わる一モーラ差。"}, {"text": "浅ましい", "is_correct": false, "explanation": "読みは「あさましい」。「た」が「あさ」に変わる。"}, {"text": "喧しい", "is_correct": false, "explanation": "読みは「やかましい」。「た」が「やか」に変わる。"}], "explanations": {"魂": "正解。読みは「たましい」。", "正しい": "読みは「ただしい」。「ま」が「だ」に変わる一モーラ差。", "浅ましい": "読みは「あさましい」。「た」が「あさ」に変わる。", "喧しい": "読みは「やかましい」。「た」が「やか」に変わる。"}, "sentence_index": null, "correct_answer": "魂"}, "level_3": {"options": [{"text": "魂", "is_correct": true, "explanation": "死後に残ると信じられる心の本質なので「魂」が入る。"}, {"text": "財布", "is_correct": false, "explanation": "財布が死後に残ると信じるのは文意に合わない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は死と関係がない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は死後に残ると信じるものではない。"}], "explanations": {"魂": "死後に残ると信じられる心の本質なので「魂」が入る。", "財布": "財布が死後に残ると信じるのは文意に合わない。", "時計": "時計は死と関係がない。", "宿題": "宿題は死後に残ると信じるものではない。"}, "sentence_index": 6, "correct_answer": "魂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "魂の切れた絵は人の心に届かない。", "explanation": "「魂」は電池のように切れるものではない。"}, {"text": "魂を三本描いた。", "explanation": "「魂」は「本」で数えない。"}, {"text": "魂がおいしい絵は人の心に届かない。", "explanation": "「魂」は味で表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f516f50-7063-491d-b66b-340af3540cd2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
