INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52450, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "空中にゆっくりと浮かんでいるように存在する。また、その場に満ちているような感じがする。", "primary_collocate": null, "pronunciation": "ただよう", "ipa": "tadajoɯ", "syllable_count": 4, "sentences": [{"text": "革の匂いが漂う暗闇の奥底で、長き眠りについていたそれを引きずり出した瞬間、埃っぽい記憶の粒子が舞い上がる。", "target_word": "漂う", "complexity_tier": "T3", "furigana": "かわ におい ただよう くらやみ おくそこ", "sentence_source": "mined"}, {"text": "凍てつく空気の中、ボタンを一つひとつ留める仕草には、未知の領域へ挑む戦士のような厳粛ささえ漂っていた。", "target_word": "漂っ", "complexity_tier": "T3", "furigana": "いてつく くうき ただよって", "sentence_source": "mined"}, {"text": "台所からカレーの匂いが漂ってきた。", "target_word": "漂っ", "complexity_tier": "T3", "furigana": "だいどころ におい ただよって", "sentence_source": "generated"}, {"text": "教室に重い空気が漂っている。", "target_word": "漂っ", "complexity_tier": "T3", "furigana": "きょうしつ おもい くうき ただよって", "sentence_source": "generated"}, {"text": "海の上に小さな船が漂う。", "target_word": "漂う", "complexity_tier": "T3", "furigana": "うみ うえ ちいさな ふね ただよう", "sentence_source": "generated"}, {"text": "花の香りが漂う庭が好きだ。", "target_word": "漂う", "complexity_tier": "T3", "furigana": "はな かおり ただよう にわ すき", "sentence_source": "generated"}, {"text": "雲が空にゆっくり漂っている。", "target_word": "漂っ", "complexity_tier": "T3", "furigana": "くも そら ただよって", "sentence_source": "generated"}, {"text": "町には祭りの気分が漂っていた。", "target_word": "漂っ", "complexity_tier": "T3", "furigana": "まち まつり きぶん ただよって", "sentence_source": "generated"}, {"text": "木の葉が川に漂っている。", "target_word": "漂っ", "complexity_tier": "T3", "furigana": "き は かわ ただよって", "sentence_source": "generated"}, {"text": "二人の間に気まずさが漂う。", "target_word": "漂う", "complexity_tier": "T3", "furigana": "ふたり あいだ き ただよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "漂った", "label": "活用"}, {"form": "漂って", "label": "活用"}, {"form": "漂わない", "label": "活用"}, {"form": "漂い", "label": "派生"}], "register": "formal", "sense_fingerprint": "動詞 | 匂いや雰囲気が辺りに満ちる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 奥底 (Zipf 3.21), 長き (Zipf 3.3), 引きずり出し (Zipf 2.55), 舞い上がる (Zipf 2.61)']::text[], 'e086ccc6-4de1-467a-b578-2c224d3390e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52078, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "深く濃い赤色。血のような、とても濃い赤。", "primary_collocate": null, "pronunciation": "しんく", "ipa": "ɕiŋkɯ", "syllable_count": 3, "sentences": [{"text": "深紅とも、あるいは乾いた血の色とも形容すべきそのブーツは、もはや単なる履物という枠組みを超え、私の内面に潜む情動を可視化する媒体となっているのだ。\n\n指先でなぞる革の質感は、過ぎ去りし季節の冷たさと、それに抗った熱気を同時に記憶している。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "しんく", "sentence_source": "mined"}, {"text": "それはまさに、自然の営みと時間が凝縮したかような深紅を纏うリンゴであった。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "しぜん いとなみ じかん ぎょうしゅく しんく まとう", "sentence_source": "mined"}, {"text": "彼女は深紅のドレスを着ていた。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "かのじょ しんく き", "sentence_source": "generated"}, {"text": "夕日が空を深紅に染めた。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "ゆうひ そら しんく そめた", "sentence_source": "generated"}, {"text": "庭に深紅のバラが咲いている。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "にわ しんく さいて", "sentence_source": "generated"}, {"text": "秋になると葉が深紅に変わる。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "あき は しんく かわる", "sentence_source": "generated"}, {"text": "この絵は深紅が印象的だ。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "え しんく いんしょうてき", "sentence_source": "generated"}, {"text": "深紅のカーテンが部屋を飾る。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "しんく へや かざる", "sentence_source": "generated"}, {"text": "姉の好きな色は深紅です。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "あね すき いろ しんく", "sentence_source": "generated"}, {"text": "深紅の夕焼けに目を奪われた。", "target_word": "深紅", "complexity_tier": "T3", "furigana": "しんく ゆうやけ め うばわれた", "sentence_source": "generated"}], "morphological_forms": [{"form": "深紅色", "label": "派生"}, {"form": "深紅の", "label": "派生"}, {"form": "深紅に", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 血のように深く濃い赤色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e086ccc6-4de1-467a-b578-2c224d3390e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37781, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "あとに否定の表現を伴って、強く打ち消す気持ちを表す。絶対に。", "primary_collocate": null, "pronunciation": "けっして", "ipa": "keɕɕite", "syllable_count": 4, "sentences": [{"text": "私がこの赤い靴を履くという行為は、決して寒さ凌ぎの方便ではない。", "target_word": "決して", "complexity_tier": "T3", "furigana": "わたし あかい くつ はく こうい けっして さむさしのぎ ほうべん", "sentence_source": "mined"}, {"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "決して", "complexity_tier": "T3", "furigana": "きんゆう しじょう けっして", "sentence_source": "mined"}, {"text": "約束は決して忘れません。", "target_word": "決して", "complexity_tier": "T3", "furigana": "やくそく けっして わすれません", "sentence_source": "generated"}, {"text": "この問題は決して簡単ではない。", "target_word": "決して", "complexity_tier": "T3", "furigana": "もんだい けっして かんたん", "sentence_source": "generated"}, {"text": "決してあきらめないでください。", "target_word": "決して", "complexity_tier": "T3", "furigana": "けっして", "sentence_source": "generated"}, {"text": "彼は決してうそをつかない。", "target_word": "決して", "complexity_tier": "T3", "furigana": "かれ けっして", "sentence_source": "generated"}, {"text": "その道は決して安全とは言えない。", "target_word": "決して", "complexity_tier": "T3", "furigana": "みち けっして あんぜん いえない", "sentence_source": "generated"}, {"text": "決して一人で山に行ってはいけない。", "target_word": "決して", "complexity_tier": "T3", "furigana": "けっして ひとり やま いって", "sentence_source": "generated"}, {"text": "私は決して怒っていません。", "target_word": "決して", "complexity_tier": "T3", "furigana": "わたし けっして おこって", "sentence_source": "generated"}, {"text": "このことは決して誰にも話さない。", "target_word": "決して", "complexity_tier": "T3", "furigana": "けっして だれ はなさない", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "副詞 | 否定と共に使う強い打ち消し", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: 5 words above tier T2 (max 3): サプライ (Zipf 3.19), 文脈 (Zipf 3.63), ミクロ (Zipf 3.34), 局所 (Zipf 3.35), 線形 (Zipf 2.97)']::text[], 'e086ccc6-4de1-467a-b578-2c224d3390e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51614, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "時間や出来事が通り過ぎて、もう戻らない状態になる。", "primary_collocate": null, "pronunciation": "すぎさる", "ipa": "sɯɡisaɾɯ", "syllable_count": 4, "sentences": [{"text": "深紅とも、あるいは乾いた血の色とも形容すべきそのブーツは、もはや単なる履物という枠組みを超え、私の内面に潜む情動を可視化する媒体となっているのだ。\n\n指先でなぞる革の質感は、過ぎ去りし季節の冷たさと、それに抗った熱気を同時に記憶している。", "target_word": "過ぎ去り", "complexity_tier": "T3", "furigana": "すぎさりし", "sentence_source": "mined"}, {"text": "色褪せた外壁や苔むした庭は、過ぎ去った長い年月を静かに物語っている。", "target_word": "過ぎ去っ", "complexity_tier": "T3", "furigana": "いろあせた がいへき こけむした にわ すぎさった ながい ねんげつ しずか ものがたって", "sentence_source": "mined"}, {"text": "楽しい夏休みが過ぎ去った。", "target_word": "過ぎ去っ", "complexity_tier": "T3", "furigana": "たのしい なつやすみ すぎさった", "sentence_source": "generated"}, {"text": "過ぎ去った日々を思い出す。", "target_word": "過ぎ去っ", "complexity_tier": "T3", "furigana": "すぎさった ひび おもいだす", "sentence_source": "generated"}, {"text": "嵐が過ぎ去って、空が晴れた。", "target_word": "過ぎ去っ", "complexity_tier": "T3", "furigana": "あらし すぎさって そら はれた", "sentence_source": "generated"}, {"text": "時間は静かに過ぎ去っていく。", "target_word": "過ぎ去っ", "complexity_tier": "T3", "furigana": "じかん しずか すぎさって", "sentence_source": "generated"}, {"text": "過ぎ去った時は戻らない。", "target_word": "過ぎ去っ", "complexity_tier": "T3", "furigana": "すぎさった とき もどらない", "sentence_source": "generated"}, {"text": "冬が過ぎ去り、春が来た。", "target_word": "過ぎ去り", "complexity_tier": "T3", "furigana": "ふゆ すぎさり はる きた", "sentence_source": "generated"}, {"text": "青春はすぐに過ぎ去るものだ。", "target_word": "過ぎ去る", "complexity_tier": "T3", "furigana": "せいしゅん すぎさる", "sentence_source": "generated"}, {"text": "過ぎ去ったことは気にしないで。", "target_word": "過ぎ去っ", "complexity_tier": "T3", "furigana": "すぎさった き", "sentence_source": "generated"}], "morphological_forms": [{"form": "過ぎ去った", "label": "活用"}, {"form": "過ぎ去って", "label": "活用"}, {"form": "過ぎ去り", "label": "活用"}, {"form": "過ぎ去らない", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 時が過ぎてもう戻らなくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e086ccc6-4de1-467a-b578-2c224d3390e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38879, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物の表面や材質の触った感じや見た感じ。", "primary_collocate": null, "pronunciation": "しつかん", "ipa": "ɕitsɯkaɴ", "syllable_count": 4, "sentences": [{"text": "深紅とも、あるいは乾いた血の色とも形容すべきそのブーツは、もはや単なる履物という枠組みを超え、私の内面に潜む情動を可視化する媒体となっているのだ。\n\n指先でなぞる革の質感は、過ぎ去りし季節の冷たさと、それに抗った熱気を同時に記憶している。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん", "sentence_source": "mined"}, {"text": "クレヨンのざらついた質感と鮮やかな色彩が交わる瞬間、言葉にできない感情が視覚化されていく。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん あざやか しきさい まじわる しゅんかん", "sentence_source": "mined"}, {"text": "この布はやわらかい質感だ。", "target_word": "質感", "complexity_tier": "T3", "furigana": "ぬの しつかん", "sentence_source": "generated"}, {"text": "木の質感が好きです。", "target_word": "質感", "complexity_tier": "T3", "furigana": "き しつかん すき", "sentence_source": "generated"}, {"text": "紙の質感を指で確かめた。", "target_word": "質感", "complexity_tier": "T3", "furigana": "かみ しつかん ゆび たしかめた", "sentence_source": "generated"}, {"text": "このかばんは質感が良い。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん よい", "sentence_source": "generated"}, {"text": "質感の違いに気がついた。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん ちがい き", "sentence_source": "generated"}, {"text": "石の冷たい質感が伝わる。", "target_word": "質感", "complexity_tier": "T3", "furigana": "いし つめたい しつかん つたわる", "sentence_source": "generated"}, {"text": "画家は質感をうまく描いた。", "target_word": "質感", "complexity_tier": "T3", "furigana": "がか しつかん えがいた", "sentence_source": "generated"}, {"text": "この皿は質感にこだわっている。", "target_word": "質感", "complexity_tier": "T3", "furigana": "さら しつかん", "sentence_source": "generated"}], "morphological_forms": [{"form": "質感がある", "label": "派生"}, {"form": "質感表現", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 材質から受ける触った感じ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: 6 words above tier T4 (max 5): 深紅 (Zipf 2.91), 履物 (Zipf 2.6), 情動 (Zipf 2.72), なぞる (Zipf 2.97), 過ぎ去り (Zipf 2.72), 抗っ (Zipf 2.47)']::text[], 'e086ccc6-4de1-467a-b578-2c224d3390e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35073, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "程度が大きいさま。非常に。たいへん。", "primary_collocate": null, "pronunciation": "とても", "ipa": "totemo", "syllable_count": 3, "sentences": [{"text": "中国には、とてもながい城壁があります。", "target_word": "とても", "complexity_tier": "T3", "furigana": "ちゅうごく じょうへき", "sentence_source": "mined"}, {"text": "今日はとても暑い。", "target_word": "とても", "complexity_tier": "T3", "furigana": "きょう あつい", "sentence_source": "generated"}, {"text": "このケーキはとてもおいしい。", "target_word": "とても", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "彼はとても親切な人です。", "target_word": "とても", "complexity_tier": "T3", "furigana": "かれ しんせつ ひと", "sentence_source": "generated"}, {"text": "テストはとても難しかった。", "target_word": "とても", "complexity_tier": "T3", "furigana": "むずかしかった", "sentence_source": "generated"}, {"text": "とても楽しい一日でした。", "target_word": "とても", "complexity_tier": "T3", "furigana": "たのしい いちにち", "sentence_source": "generated"}, {"text": "この本はとても面白い。", "target_word": "とても", "complexity_tier": "T3", "furigana": "ほん おもしろい", "sentence_source": "generated"}, {"text": "妹はとても速く走る。", "target_word": "とても", "complexity_tier": "T3", "furigana": "いもうと はやく はしる", "sentence_source": "generated"}, {"text": "とても静かな夜だった。", "target_word": "とても", "complexity_tier": "T3", "furigana": "しずか よる", "sentence_source": "generated"}, {"text": "その知らせにとても驚いた。", "target_word": "とても", "complexity_tier": "T3", "furigana": "しらせ おどろいた", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "副詞 | 程度が非常に大きいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e086ccc6-4de1-467a-b578-2c224d3390e9') ON CONFLICT (sense_id, asset_type) DO UP