INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52450, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "漂う", "is_correct": true, "explanation": "正解。「ただよう」と読む。"}, {"text": "偏る", "is_correct": false, "explanation": "「かたよる」。一つの方向に寄ること。音が近い。"}, {"text": "戦う", "is_correct": false, "explanation": "「たたかう」。争うこと。音が近い。"}, {"text": "正す", "is_correct": false, "explanation": "「ただす」。間違いを直すこと。音が近い。"}], "explanations": {"漂う": "正解。「ただよう」と読む。", "偏る": "「かたよる」。一つの方向に寄ること。音が近い。", "戦う": "「たたかう」。争うこと。音が近い。", "正す": "「ただす」。間違いを直すこと。音が近い。"}, "sentence_index": null, "correct_answer": "漂う"}, "level_3": {"options": [{"text": "漂う", "is_correct": true, "explanation": "正解。匂いが辺りに満ちている様子を表す。"}, {"text": "落ちる", "is_correct": false, "explanation": "意味：匂いが落ちる暗闇は成り立たない。"}, {"text": "割れる", "is_correct": false, "explanation": "意味：匂いが割れることはない。"}, {"text": "壊れる", "is_correct": false, "explanation": "意味：匂いが壊れることはない。"}], "explanations": {"漂う": "正解。匂いが辺りに満ちている様子を表す。", "落ちる": "意味：匂いが落ちる暗闇は成り立たない。", "割れる": "意味：匂いが割れることはない。", "壊れる": "意味：匂いが壊れることはない。"}, "sentence_index": 0, "correct_answer": "漂う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室に重い空気を漂っている。", "explanation": "助詞の混同：「漂う」は自動詞なので「を」ではなく「が」を使う。"}, {"text": "昨日、教室に重い空気が漂っている。", "explanation": "アスペクトの誤り：「昨日」には「漂っていた」が必要。"}, {"text": "重い空気が教室にの漂っている。", "explanation": "語順・係り受けの誤り：「にの」は文法的に成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52450, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台所からカレーの匂いを漂ってきた。", "corrected_sentence": "台所からカレーの匂いが漂ってきた。", "error_description": "「漂う」は自動詞なので、主語に「が」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "漂っ", "is_correct": true, "explanation": "「ていた」に続くので促音便のて形が必要。"}, {"text": "漂う", "is_correct": false, "explanation": "辞書形は「ていた」に接続できない。"}, {"text": "漂わ", "is_correct": false, "explanation": "未然形は「ない」などに続き、「ていた」には続かない。"}, {"text": "漂え", "is_correct": false, "explanation": "仮定形・命令形で、「ていた」には続かない。"}], "correct_form": "漂っ", "base_form": "漂う", "form_label": "て形（促音便）", "sentence_index": 1, "explanations": {"漂っ": "「ていた」に続くので促音便のて形が必要。", "漂う": "辞書形は「ていた」に接続できない。", "漂わ": "未然形は「ない」などに続き、「ていた」には続かない。", "漂え": "仮定形・命令形で、「ていた」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52450, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「留める」の目的語「ボタン」を表す。"}, {"text": "が", "is_correct": false, "explanation": "「仕草」の中の動作の目的語なので主格は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「ボタンの一つひとつ留める」は動詞の目的語を示せず非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「留める」の目的語「ボタン」を表す。", "が": "「仕草」の中の動作の目的語なので主格は不自然。", "の": "「ボタンの一つひとつ留める」は動詞の目的語を示せず非文。", "へ": "方向を表し、目的語にならない。"}, "error_tags": {"が": "object_marking", "の": "object_marking", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52450, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "漂う", "is_correct": true, "explanation": "正解。「ただよう」と読む。"}, {"text": "叩く", "is_correct": false, "explanation": "「たたく」。打つこと。音が近い。"}, {"text": "畳", "is_correct": false, "explanation": "「たたみ」。床に敷くもの。音が近い。"}, {"text": "多大", "is_correct": false, "explanation": "「ただい」。とても大きいこと。音が近い。"}], "explanations": {"漂う": "正解。「ただよう」と読む。", "叩く": "「たたく」。打つこと。音が近い。", "畳": "「たたみ」。床に敷くもの。音が近い。", "多大": "「ただい」。とても大きいこと。音が近い。"}, "sentence_index": null, "correct_answer": "漂う"}, "level_3": {"options": [{"text": "漂っ", "is_correct": true, "explanation": "正解。雲が空にゆっくり浮かんでいる様子。"}, {"text": "走っ", "is_correct": false, "explanation": "意味：雲が「走っている」はゆっくりと合わない。"}, {"text": "座っ", "is_correct": false, "explanation": "意味：雲が座ることはない。"}, {"text": "眠っ", "is_correct": false, "explanation": "意味：雲は眠らない。"}], "explanations": {"漂っ": "正解。雲が空にゆっくり浮かんでいる様子。", "走っ": "意味：雲が「走っている」はゆっくりと合わない。", "座っ": "意味：雲が座ることはない。", "眠っ": "意味：雲は眠らない。"}, "sentence_index": 6, "correct_answer": "漂っ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人の間に気まずさを漂う。", "explanation": "助詞の混同：自動詞なので「が」が必要。"}, {"text": "二人の間に気まずさが漂うた。", "explanation": "活用の誤り：過去形は「漂った」。"}, {"text": "気まずさが二人の漂う間に。", "explanation": "語順の誤り：文の構造が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52450, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町には祭りの気分が漂いていた。", "corrected_sentence": "町には祭りの気分が漂っていた。", "error_description": "「漂う」のて形は促音便の「漂って」になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "漂っ", "is_correct": true, "explanation": "「ていた」の前は促音便のて形。"}, {"text": "漂い", "is_correct": false, "explanation": "連用形だが「漂いていた」とは言わない。"}, {"text": "漂お", "is_correct": false, "explanation": "意向形の語幹で、「ていた」に続かない。"}, {"text": "漂わ", "is_correct": false, "explanation": "未然形は「ていた」に続かない。"}], "correct_form": "漂っ", "base_form": "漂う", "form_label": "て形（促音便）", "sentence_index": 7, "explanations": {"漂っ": "「ていた」の前は促音便のて形。", "漂い": "連用形だが「漂いていた」とは言わない。", "漂お": "意向形の語幹で、「ていた」に続かない。", "漂わ": "未然形は「ていた」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52450, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「漂う」の主語「気分」を表す。"}, {"text": "を", "is_correct": false, "explanation": "「漂う」は自動詞なので目的語をとらない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表し、主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、ここでは非文。"}], "correct_answer": "が", "explanations": {"が": "自動詞「漂う」の主語「気分」を表す。", "を": "「漂う」は自動詞なので目的語をとらない。", "で": "場所や手段を表し、主語にならない。", "へ": "方向を表し、ここでは非文。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52078, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深紅", "is_correct": true, "explanation": "正解。「しんく」と読む。"}, {"text": "寝具", "is_correct": false, "explanation": "「しんぐ」。布団など。「く」と「ぐ」の清濁の違い。"}, {"text": "進化", "is_correct": false, "explanation": "「しんか」。最後の一モーラ「く」と「か」が違う。"}, {"text": "真空", "is_correct": false, "explanation": "「しんくう」。最後が長音になる違い。"}], "explanations": {"深紅": "正解。「しんく」と読む。", "寝具": "「しんぐ」。布団など。「く」と「ぐ」の清濁の違い。", "進化": "「しんか」。最後の一モーラ「く」と「か」が違う。", "真空": "「しんくう」。最後が長音になる違い。"}, "sentence_index": null, "correct_answer": "深紅"}, "level_3": {"options": [{"text": "深紅", "is_correct": true, "explanation": "正解。乾いた血のような濃い赤色を表す。"}, {"text": "純白", "is_correct": false, "explanation": "意味：血の色と並べるのに白は合わない。"}, {"text": "紺色", "is_correct": false, "explanation": "意味：血の色とは結びつかない。"}, {"text": "黄金", "is_correct": false, "explanation": "意味：乾いた血の色とは違う。"}], "explanations": {"深紅": "正解。乾いた血のような濃い赤色を表す。", "純白": "意味：血の色と並べるのに白は合わない。", "紺色": "意味：血の色とは結びつかない。", "黄金": "意味：乾いた血の色とは違う。"}, "sentence_index": 0, "correct_answer": "深紅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕日が空を深紅を染めた。", "explanation": "助詞の混同：色の結果は「に」で表す。"}, {"text": "夕日が空を一枚の深紅に染めた。", "explanation": "助数詞の誤り：色に「枚」は使わない。"}, {"text": "明日、夕日が空を深紅に染めた。", "explanation": "時制の誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52078, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は深紅がドレスを着ていた。", "corrected_sentence": "彼女は深紅のドレスを着ていた。", "error_description": "名詞を修飾するときは「深紅の」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52078, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「纏う」の目的語「深紅」を表す。"}, {"text": "が", "is_correct": false, "explanation": "「纏う」の目的語に主格は使えない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表すが、ここでは不自然。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、「纏う」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「纏う」の目的語「深紅」を表す。", "が": "「纏う」の目的語に主格は使えない。", "で": "手段を表すが、ここでは不自然。", "に": "着点を表し、「纏う」の目的語にならない。"}, "error_tags": {"が": "object_marking", "で": "instrument", "に": "location_vs_target"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52078, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "深紅", "is_correct": true, "explanation": "正解。「しんく」と読む。"}, {"text": "甚句", "is_correct": false, "explanation": "「じんく」。民謡の一種。最初の清濁の違い。"}, {"text": "新規", "is_correct": false, "explanation": "「しんき」。新しいこと。最後の一モーラが違う。"}, {"text": "新刊", "is_correct": false, "explanation": "「しんかん」。新しく出た本。音が近い。"}], "explanations": {"深紅": "正解。「しんく」と読む。", "甚句": "「じんく」。民謡の一種。最初の清濁の違い。", "新規": "「しんき」。新しいこと。最後の一モーラが違う。", "新刊": "「しんかん」。新しく出た本。音が近い。"}, "sentence_index": null, "correct_answer": "深紅"}, "level_3": {"options": [{"text": "深紅", "is_correct": true, "explanation": "正解。この絵では濃い赤が目立つ。"}, {"text": "騒音", "is_correct": false, "explanation": "意味：絵の色の話なので音は合わない。"}, {"text": "体重", "is_correct": false, "explanation": "意味：絵に体重はない。"}, {"text": "気温", "is_correct": false, "explanation": "意味：絵には気温はない。"}], "explanations": {"深紅": "正解。この絵では濃い赤が目立つ。", "騒音": "意味：絵の色の話なので音は合わない。", "体重": "意味：絵に体重はない。", "気温": "意味：絵には気温はない。"}, "sentence_index": 6, "correct_answer": "深紅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "深紅を夕焼けに目を奪われた。", "explanation": "助詞の混同：修飾には「の」を使う。"}, {"text": "明日、深紅の夕焼けに目を奪われた。", "explanation": "時制の誤り：「明日」と過去形が合わない。"}, {"text": "三本の深紅の夕焼けに目を奪われた。", "explanation": "助数詞の誤り：夕焼けは「本」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52078, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭に深紅をバラが咲いている。", "corrected_sentence": "庭に深紅のバラが咲いている。", "error_description": "「バラ」を修飾するので「深紅の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52078, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「飾る」の目的語「部屋」を表す。"}, {"text": "で", "is_correct": false, "explanation": "場所を表すが「部屋で飾る」は目的語がなく不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語にならない。"}, {"text": "が", "is_correct": false, "explanation": "主語が二つになり非文。"}], "correct_answer": "を", "explanations": {"を": "「飾る」の目的語「部屋」を表す。", "で": "場所を表すが「部屋で飾る」は目的語がなく不自然。", "へ": "方向を表し、目的語にならない。", "が": "主語が二つになり非文。"}, "error_tags": {"で": "location_vs_target", "へ": "direction", "が": "object_marking"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37781, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "決して", "is_correct": true, "explanation": "正解。「けっして」と読む。"}, {"text": "消して", "is_correct": false, "explanation": "「けして」。消すこと。促音の有無の違い。"}, {"text": "決死", "is_correct": false, "explanation": "「けっし」。命をかけること。音が近い。"}, {"text": "蹴って", "is_correct": false, "explanation": "「けって」。蹴ること。「し」が一つ抜けた違い。"}], "explanations": {"決して": "正解。「けっして」と読む。", "消して": "「けして」。消すこと。促音の有無の違い。", "決死": "「けっし」。命をかけること。音が近い。", "蹴って": "「けって」。蹴ること。「し」が一つ抜けた違い。"}, "sentence_index": null, "correct_answer": "決して"}, "level_3": {"options": [{"text": "決して", "is_correct": true, "explanation": "正解。「ではない」と共に強く否定する。"}, {"text": "たくさん", "is_correct": false, "explanation": "意味：量を表し、この文に合わない。"}, {"text": "ぜひ", "is_correct": false, "explanation": "意味：願いを表し、否定文に合わない。"}, {"text": "もっと", "is_correct": false, "explanation": "意味：比較を表し、「ではない」と結びつかない。"}], "explanations": {"決して": "正解。「ではない」と共に強く否定する。", "たくさん": "意味：量を表し、この文に合わない。", "ぜひ": "意味：願いを表し、否定文に合わない。", "もっと": "意味：比較を表し、「ではない」と結びつかない。"}, "sentence_index": 0, "correct_answer": "決して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この問題は決して簡単だ。", "explanation": "否定がない誤り：「決して」は否定と一緒に使う。"}, {"text": "この問題は決してが簡単ではない。", "explanation": "助詞の誤り：「決してが」は成り立たない。"}, {"text": "この問題は簡単ではない決して。", "explanation": "語順の誤り：副詞は述語の前に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
