INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37781, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "決して", "is_correct": true, "explanation": "正解。「けっして」と読む。"}, {"text": "消して", "is_correct": false, "explanation": "「けして」。促音がない。"}, {"text": "結果", "is_correct": false, "explanation": "「けっか」。音が近い。"}, {"text": "欠席", "is_correct": false, "explanation": "「けっせき」。音が近い。"}], "explanations": {"決して": "正解。「けっして」と読む。", "消して": "「けして」。促音がない。", "結果": "「けっか」。音が近い。", "欠席": "「けっせき」。音が近い。"}, "sentence_index": null, "correct_answer": "決して"}, "level_3": {"options": [{"text": "決して", "is_correct": true, "explanation": "正解。「とは言えない」と共に強く否定する。"}, {"text": "たくさん", "is_correct": false, "explanation": "意味：量を表し、この文に合わない。"}, {"text": "ぜひ", "is_correct": false, "explanation": "意味：願いを表す語で、この文に合わない。"}, {"text": "さっき", "is_correct": false, "explanation": "意味：時を表し、強い否定にならない。"}], "explanations": {"決して": "正解。「とは言えない」と共に強く否定する。", "たくさん": "意味：量を表し、この文に合わない。", "ぜひ": "意味：願いを表す語で、この文に合わない。", "さっき": "意味：時を表し、強い否定にならない。"}, "sentence_index": 6, "correct_answer": "決して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このことは決して誰にも話す。", "explanation": "否定の欠落：「決して」は否定と共に使う。"}, {"text": "このことは決してに誰にも話さない。", "explanation": "助詞の誤り：副詞に「に」は付かない。"}, {"text": "このことは誰にも話さない決して。", "explanation": "語順の誤り：副詞は述語の前に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
