INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51614, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "過ぎ去る", "is_correct": true, "explanation": "正解。「すぎさる」と読む。"}, {"text": "立ち去る", "is_correct": false, "explanation": "「たちさる」。その場を去ること。音が近い。"}, {"text": "引き去る", "is_correct": false, "explanation": "「ひきさる」。引いて去ること。音が近い。"}, {"text": "過ぎ行く", "is_correct": false, "explanation": "「すぎゆく」。音が近い。"}], "explanations": {"過ぎ去る": "正解。「すぎさる」と読む。", "立ち去る": "「たちさる」。その場を去ること。音が近い。", "引き去る": "「ひきさる」。引いて去ること。音が近い。", "過ぎ行く": "「すぎゆく」。音が近い。"}, "sentence_index": null, "correct_answer": "過ぎ去る"}, "level_3": {"options": [{"text": "過ぎ去り", "is_correct": true, "explanation": "正解。「過ぎ去りし」で過ぎてしまった季節を表す。"}, {"text": "生まれ", "is_correct": false, "explanation": "意味：季節が生まれた、では「冷たさを記憶する」と合わない。"}, {"text": "降り", "is_correct": false, "explanation": "連語：季節が降ることはない。"}, {"text": "走り", "is_correct": false, "explanation": "意味：季節は走らない。"}], "explanations": {"過ぎ去り": "正解。「過ぎ去りし」で過ぎてしまった季節を表す。", "生まれ": "意味：季節が生まれた、では「冷たさを記憶する」と合わない。", "降り": "連語：季節が降ることはない。", "走り": "意味：季節は走らない。"}, "sentence_index": 0, "correct_answer": "過ぎ去り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "過ぎ去った日々が思い出す。", "explanation": "助詞の混同：「思い出す」の目的語には「を」を使う。"}, {"text": "過ぎ去っている日々を思い出す。", "explanation": "アスペクトの誤り：もう終わったことなので「過ぎ去った」。"}, {"text": "日々を過ぎ去った思い出す。", "explanation": "語順の誤り：修飾の関係が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51614, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "楽しい夏休みが過ぎ去るた。", "corrected_sentence": "楽しい夏休みが過ぎ去った。", "error_description": "過去形は「過ぎ去った」と促音便になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "過ぎ去っ", "is_correct": true, "explanation": "「た」に続き、過去の連体修飾になる。"}, {"text": "過ぎ去る", "is_correct": false, "explanation": "辞書形に「た」は付かない。"}, {"text": "過ぎ去ら", "is_correct": false, "explanation": "未然形は「ない」に続く形。"}, {"text": "過ぎ去れ", "is_correct": false, "explanation": "仮定・命令の形で「た」に続かない。"}], "correct_form": "過ぎ去っ", "base_form": "過ぎ去る", "form_label": "た形（過去）", "sentence_index": 1, "explanations": {"過ぎ去っ": "「た」に続き、過去の連体修飾になる。", "過ぎ去る": "辞書形に「た」は付かない。", "過ぎ去ら": "未然形は「ない」に続く形。", "過ぎ去れ": "仮定・命令の形で「た」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51614, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「物語る」の目的語「年月」を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語が重なり、目的語を表せない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、ここでは非文。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、「物語る」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「物語る」の目的語「年月」を表す。", "が": "主語が重なり、目的語を表せない。", "で": "手段・場所を表し、ここでは非文。", "に": "着点を表し、「物語る」の目的語にならない。"}, "error_tags": {"が": "object_marking", "で": "instrument", "に": "location_vs_target"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "訪れる", "is_correct": true, "explanation": "時や季節がやって来ることで、去ることの反対。"}, {"text": "終わる", "is_correct": false, "explanation": "過ぎることに近く、対義ではない。"}, {"text": "流れる", "is_correct": false, "explanation": "時が過ぎることを表し、類義に近い。"}, {"text": "去る", "is_correct": false, "explanation": "ほぼ同じ意味で、対義ではない。"}], "correct_answer": "訪れる", "explanations": {"訪れる": "時や季節がやって来ることで、去ることの反対。", "終わる": "過ぎることに近く、対義ではない。", "流れる": "時が過ぎることを表し、類義に近い。", "去る": "ほぼ同じ意味で、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51614, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "過ぎ去る", "is_correct": true, "explanation": "正解。「すぎさる」と読む。"}, {"text": "消え去る", "is_correct": false, "explanation": "「きえさる」。音が近い。"}, {"text": "立ち去る", "is_correct": false, "explanation": "「たちさる」。音が近い。"}, {"text": "逃げ去る", "is_correct": false, "explanation": "「にげさる」。音が近い。"}], "explanations": {"過ぎ去る": "正解。「すぎさる」と読む。", "消え去る": "「きえさる」。音が近い。", "立ち去る": "「たちさる」。音が近い。", "逃げ去る": "「にげさる」。音が近い。"}, "sentence_index": null, "correct_answer": "過ぎ去る"}, "level_3": {"options": [{"text": "過ぎ去っ", "is_correct": true, "explanation": "正解。過ぎてしまった時を表す。"}, {"text": "覚え", "is_correct": false, "explanation": "意味：「時を覚えた」は文全体と合わない。"}, {"text": "食べ", "is_correct": false, "explanation": "意味：時は食べるものではない。"}, {"text": "読ん", "is_correct": false, "explanation": "意味：時は読むものではない。"}], "explanations": {"過ぎ去っ": "正解。過ぎてしまった時を表す。", "覚え": "意味：「時を覚えた」は文全体と合わない。", "食べ": "意味：時は食べるものではない。", "読ん": "意味：時は読むものではない。"}, "sentence_index": 6, "correct_answer": "過ぎ去っ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "過ぎ去ったことは気にしないでは。", "explanation": "助詞の誤り：文末の「は」が不自然。"}, {"text": "過ぎ去ったことは気にしないでた。", "explanation": "活用の誤り：「ないで」に「た」は付かない。"}, {"text": "過ぎ去ったことが気にしないで。", "explanation": "助詞の混同：「気にする」の対象は「は／を」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51614, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "嵐が過ぎ去っで、空が晴れた。", "corrected_sentence": "嵐が過ぎ去って、空が晴れた。", "error_description": "て形は「過ぎ去って」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "過ぎ去り", "is_correct": true, "explanation": "連用中止形で次の文につなぐ。"}, {"text": "過ぎ去る", "is_correct": false, "explanation": "辞書形のまま読点で続けるのは不自然。"}, {"text": "過ぎ去ろ", "is_correct": false, "explanation": "意向形の一部で、ここでは成り立たない。"}, {"text": "過ぎ去っ", "is_correct": false, "explanation": "促音便は「て」「た」が必要。"}], "correct_form": "過ぎ去り", "base_form": "過ぎ去る", "form_label": "連用形（中止）", "sentence_index": 7, "explanations": {"過ぎ去り": "連用中止形で次の文につなぐ。", "過ぎ去る": "辞書形のまま読点で続けるのは不自然。", "過ぎ去ろ": "意向形の一部で、ここでは成り立たない。", "過ぎ去っ": "促音便は「て」「た」が必要。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51614, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「過ぎ去る」の主語「冬」を表す。"}, {"text": "に", "is_correct": false, "explanation": "時点を表し、主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表し、非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、ここでは非文。"}], "correct_answer": "が", "explanations": {"が": "自動詞「過ぎ去る」の主語「冬」を表す。", "に": "時点を表し、主語にならない。", "で": "場所や手段を表し、非文。", "へ": "方向を表し、ここでは非文。"}, "error_tags": {"に": "location_vs_target", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "やって来る", "is_correct": true, "explanation": "近づいて来ることで、去ることの反対。"}, {"text": "消える", "is_correct": false, "explanation": "なくなることで、対義ではない。"}, {"text": "経つ", "is_correct": false, "explanation": "時が過ぎることで、類義に近い。"}, {"text": "遠ざかる", "is_correct": false, "explanation": "離れていくことで、類義に近い。"}], "correct_answer": "やって来る", "explanations": {"やって来る": "近づいて来ることで、去ることの反対。", "消える": "なくなることで、対義ではない。", "経つ": "時が過ぎることで、類義に近い。", "遠ざかる": "離れていくことで、類義に近い。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38879, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "質感", "is_correct": true, "explanation": "正解。「しつかん」と読む。"}, {"text": "疾患", "is_correct": false, "explanation": "「しっかん」。病気。「つ」が促音になる違い。"}, {"text": "失陥", "is_correct": false, "explanation": "「しっかん」。城などを失うこと。促音の違い。"}, {"text": "実感", "is_correct": false, "explanation": "「じっかん」。音が近い。"}], "explanations": {"質感": "正解。「しつかん」と読む。", "疾患": "「しっかん」。病気。「つ」が促音になる違い。", "失陥": "「しっかん」。城などを失うこと。促音の違い。", "実感": "「じっかん」。音が近い。"}, "sentence_index": null, "correct_answer": "質感"}, "level_3": {"options": [{"text": "質感", "is_correct": true, "explanation": "正解。指でなぞった革の触った感じ。"}, {"text": "値段", "is_correct": false, "explanation": "意味：指でなぞって値段は記憶されない。"}, {"text": "名前", "is_correct": false, "explanation": "意味：革の名前を指でなぞるのは文脈に合わない。"}, {"text": "番号", "is_correct": false, "explanation": "意味：革の番号を指でなぞって記憶するのは合わない。"}], "explanations": {"質感": "正解。指でなぞった革の触った感じ。", "値段": "意味：指でなぞって値段は記憶されない。", "名前": "意味：革の名前を指でなぞるのは文脈に合わない。", "番号": "意味：革の番号を指でなぞって記憶するのは合わない。"}, "sentence_index": 0, "correct_answer": "質感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木を質感が好きです。", "explanation": "助詞の混同：「木の質感」と「の」を使う。"}, {"text": "一匹の木の質感が好きです。", "explanation": "助数詞の誤り：木は「匹」で数えない。"}, {"text": "明日、木の質感が好きでした。", "explanation": "時制の誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38879, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この布はやわらかい質感に。", "corrected_sentence": "この布はやわらかい質感だ。", "error_description": "文末に「だ」が必要で、「に」では文が終わらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
