INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38879, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "質感", "is_correct": true, "explanation": "正解。「しつかん」と読む。"}, {"text": "史観", "is_correct": false, "explanation": "「しかん」。歴史の見方。「つ」がない違い。"}, {"text": "志願", "is_correct": false, "explanation": "「しがん」。自分から願い出ること。音が近い。"}, {"text": "質問", "is_correct": false, "explanation": "「しつもん」。問うこと。後半が違う。"}], "explanations": {"質感": "正解。「しつかん」と読む。", "史観": "「しかん」。歴史の見方。「つ」がない違い。", "志願": "「しがん」。自分から願い出ること。音が近い。", "質問": "「しつもん」。問うこと。後半が違う。"}, "sentence_index": null, "correct_answer": "質感"}, "level_3": {"options": [{"text": "質感", "is_correct": true, "explanation": "正解。物の触った感じの違いに気づいた。"}, {"text": "静か", "is_correct": false, "explanation": "品詞：形容動詞で「の違い」に続かない。"}, {"text": "走る", "is_correct": false, "explanation": "品詞：動詞で「の違い」に続かない。"}, {"text": "とても", "is_correct": false, "explanation": "品詞：副詞で「の違い」に続かない。"}], "explanations": {"質感": "正解。物の触った感じの違いに気づいた。", "静か": "品詞：形容動詞で「の違い」に続かない。", "走る": "品詞：動詞で「の違い」に続かない。", "とても": "品詞：副詞で「の違い」に続かない。"}, "sentence_index": 6, "correct_answer": "質感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この皿を質感にこだわっている。", "explanation": "助詞の混同：主題は「は」で示す。"}, {"text": "この皿は質感がこだわっている。", "explanation": "助詞の混同：こだわる対象は「に」で示す。"}, {"text": "二人の皿は質感にこだわっている。", "explanation": "助数詞の誤り：皿は「人」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd7e250-5646-4e79-a85b-1c0ec47e6836') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
