INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37085, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や物を、別の場所へ移すために、持っていく。", "primary_collocate": null, "pronunciation": "はこぶ", "ipa": "hakobɯ", "syllable_count": 3, "sentences": [{"text": "夜が明け、太陽が農場を照らし始める朝、農家の男は鶏舎へと足を運ぶ。", "target_word": "運ぶ", "complexity_tier": "T3", "furigana": "よ あ たいよう のうじょう て はじ あさ のうか おとこ けいしゃ あし はこ", "sentence_source": "mined"}, {"text": "みずを はこぶ ためです。", "target_word": "はこぶ", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "重い箱を二人で運んだ。", "target_word": "運ん", "complexity_tier": "T3", "furigana": "おも はこ ふたり はこ", "sentence_source": "generated"}, {"text": "机を教室まで運んでください。", "target_word": "運ん", "complexity_tier": "T3", "furigana": "つくえ きょうしつ はこ", "sentence_source": "generated"}, {"text": "トラックが野菜を町へ運ぶ。", "target_word": "運ぶ", "complexity_tier": "T3", "furigana": "やさい まち はこ", "sentence_source": "generated"}, {"text": "父は荷物を車に運びました。", "target_word": "運び", "complexity_tier": "T3", "furigana": "ちち にもつ くるま はこ", "sentence_source": "generated"}, {"text": "けが人は病院に運ばれた。", "target_word": "運ば", "complexity_tier": "T3", "furigana": "にん びょういん はこ", "sentence_source": "generated"}, {"text": "この船は多くの人を運べる。", "target_word": "運べ", "complexity_tier": "T3", "furigana": "ふね おお ひと はこ", "sentence_source": "generated"}, {"text": "いすを運ぶのを手伝って。", "target_word": "運ぶ", "complexity_tier": "T3", "furigana": "はこ てつだ", "sentence_source": "generated"}, {"text": "彼はお皿を台所へ運んでいる。", "target_word": "運ん", "complexity_tier": "T3", "furigana": "かれ さら だいどころ はこ", "sentence_source": "generated"}], "morphological_forms": [{"form": "運んだ", "label": "活用"}, {"form": "運んで", "label": "活用"}, {"form": "運ばない", "label": "活用"}, {"form": "運び方", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 人や物を別の場所へ移す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db15b5-16dd-40aa-83c1-ecc96d923e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52244, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ただ一つだけであること。他にないこと。", "primary_collocate": null, "pronunciation": "ゆいいつ", "ipa": "jɯiitsɯ", "syllable_count": 4, "sentences": [{"text": "それは、誰しもが生涯唯一無二の隆線パターンを有するという生体認証の絶対性に拠る。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "だれ しょうがい ゆいいつむに りゅうせん ゆう せいたいにんしょう ぜったいせい よ", "sentence_source": "mined"}, {"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "ゆびさき つう つた きじ びみょう だんりょく はっこう しんこう ぐあい ゆいいつ らしんばん かれ おんど しつど へんすう ちみつ せいぎょ びせいぶつ め み しず たいわ こころ", "sentence_source": "mined"}, {"text": "彼は私の唯一の友達です。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "かれ わたし ゆいいつ ともだち", "sentence_source": "generated"}, {"text": "それが唯一の方法だと思う。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "ゆいいつ ほうほう おも", "sentence_source": "generated"}, {"text": "この店は町で唯一のパン屋だ。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "みせ まち ゆいいつ や", "sentence_source": "generated"}, {"text": "唯一の楽しみは週末の映画です。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "ゆいいつ たの しゅうまつ えいが", "sentence_source": "generated"}, {"text": "彼女だけが唯一答えられた。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "かのじょ ゆいいつ こた", "sentence_source": "generated"}, {"text": "この島で唯一の学校が閉まった。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "しま ゆいいつ がっこう し", "sentence_source": "generated"}, {"text": "音楽が私の唯一の趣味です。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "おんがく わたし ゆいいつ しゅみ", "sentence_source": "generated"}, {"text": "唯一わかったのは彼の名前だ。", "target_word": "唯一", "complexity_tier": "T3", "furigana": "ゆいいつ かれ なまえ", "sentence_source": "generated"}], "morphological_forms": [{"form": "唯一の", "label": "派生"}, {"form": "唯一無二", "label": "派生"}, {"form": "唯一性", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | ただ一つだけで他にないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 拠る (Zipf 2.41)','sentence 1 above tier T2: 7 words above tier T2 (max 3): 指先 (Zipf 3.6), 弾力 (Zipf 3.23), 羅針盤 (Zipf 3.09), 変数 (Zipf 3.63), 緻密 (Zipf 3.25), 微生物 (Zipf 3.52)']::text[], 'e4db15b5-16dd-40aa-83c1-ecc96d923e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36509, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある時点や場所よりも、先の部分や位置。", "primary_collocate": null, "pronunciation": "まえ", "ipa": "mae", "syllable_count": 2, "sentences": [{"text": "いかなる偽装も、この厳密な科学的検証の前には無力化されるほかない。", "target_word": "前", "complexity_tier": "T3", "furigana": "ぎそう げんみつ かがくてき けんしょう まえ むりょくか", "sentence_source": "mined"}, {"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "前", "complexity_tier": "T3", "furigana": "しゅぎょう とじょう わか しょくにん よあ まえ りん くうき は つ やせい こうぼ お びさい げきてき かがくはんのう もくもく かくとう", "sentence_source": "mined"}, {"text": "駅の前で友達を待っている。", "target_word": "前", "complexity_tier": "T3", "furigana": "えき まえ ともだち ま", "sentence_source": "generated"}, {"text": "寝る前に歯をみがきます。", "target_word": "前", "complexity_tier": "T3", "furigana": "ね まえ は", "sentence_source": "generated"}, {"text": "家の前に大きな木がある。", "target_word": "前", "complexity_tier": "T3", "furigana": "いえ まえ おお き", "sentence_source": "generated"}, {"text": "三年前にこの町に来た。", "target_word": "前", "complexity_tier": "T3", "furigana": "さんねん まえ まち き", "sentence_source": "generated"}, {"text": "前の席に座ってもいいですか。", "target_word": "前", "complexity_tier": "T3", "furigana": "まえ せき すわ", "sentence_source": "generated"}, {"text": "食事の前に手を洗おう。", "target_word": "前", "complexity_tier": "T3", "furigana": "しょくじ まえ て あら", "sentence_source": "generated"}, {"text": "前を見て歩いてください。", "target_word": "前", "complexity_tier": "T3", "furigana": "まえ み ある", "sentence_source": "generated"}, {"text": "試合の前はいつも緊張する。", "target_word": "前", "complexity_tier": "T3", "furigana": "しあい まえ きんちょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "前に", "label": "派生"}, {"form": "午前", "label": "派生"}, {"form": "前日", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 時点や場所より先の位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 4 words above tier T1 (max 2): いかなる (Zipf 3.91), 偽装 (Zipf 3.98), 厳密 (Zipf 3.79), 無力 (Zipf 3.76)','sentence 1 above tier T1: contains vocabulary far above tier T1: 張り詰める (Zipf 1.07)']::text[], 'e4db15b5-16dd-40aa-83c1-ecc96d923e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51768, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある目的を達成するために用いる、具体的な方法ややり方。", "primary_collocate": null, "pronunciation": "しゅほう", "ipa": "ɕɯhoː", "syllable_count": 3, "sentences": [{"text": "まず、現場や鑑識ラボにおいて、肉眼では捉えられぬ潜在指紋を、シアノアクリレート法や光学的手法といったアプローチにより顕在化させる。", "target_word": "手法", "complexity_tier": "T3", "furigana": "げんば かんしき にくがん とら せんざい しもん ほう こうがくてき しゅほう けんざいか", "sentence_source": "mined"}, {"text": "これは、日照や風通しなどの環境データを変数としてアルゴリズムに入力し、最適な街区配置を自動的に生成する手法です。", "target_word": "手法", "complexity_tier": "T3", "furigana": "にっしょう かぜとお かんきょう へんすう にゅうりょく さいてき がいく はいち じどうてき せいせい しゅほう", "sentence_source": "mined"}, {"text": "先生は新しい手法で授業をしている。", "target_word": "手法", "complexity_tier": "T3", "furigana": "せんせい あたら しゅほう じゅぎょう", "sentence_source": "generated"}, {"text": "この手法はとても便利だ。", "target_word": "手法", "complexity_tier": "T3", "furigana": "しゅほう べんり", "sentence_source": "generated"}, {"text": "画家は独特な手法で絵をかいた。", "target_word": "手法", "complexity_tier": "T3", "furigana": "がか どくとく しゅほう え", "sentence_source": "generated"}, {"text": "同じ手法を何度も使った。", "target_word": "手法", "complexity_tier": "T3", "furigana": "おな しゅほう なんど つか", "sentence_source": "generated"}, {"text": "その手法には問題がある。", "target_word": "手法", "complexity_tier": "T3", "furigana": "しゅほう もんだい", "sentence_source": "generated"}, {"text": "彼の手法をまねしてみた。", "target_word": "手法", "complexity_tier": "T3", "furigana": "かれ しゅほう", "sentence_source": "generated"}, {"text": "古い手法が今も使われている。", "target_word": "手法", "complexity_tier": "T3", "furigana": "ふる しゅほう いま つか", "sentence_source": "generated"}, {"text": "どの手法が一番いいと思う？", "target_word": "手法", "complexity_tier": "T3", "furigana": "しゅほう いちばん おも", "sentence_source": "generated"}], "morphological_forms": [{"form": "新手法", "label": "派生"}, {"form": "分析手法", "label": "派生"}, {"form": "表現手法", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 目的を達するための具体的なやり方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: シアノアクリレート (Zipf 1.04)']::text[], 'e4db15b5-16dd-40aa-83c1-ecc96d923e9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35139, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "町", "is_correct": true, "explanation": "まち。正解。"}, {"text": "松", "is_correct": false, "explanation": "まつ：「ち」が「つ」に変わる一モーラ差。"}, {"text": "窓", "is_correct": false, "explanation": "まど：「ち」が「ど」に変わる一モーラ差。"}, {"text": "豆", "is_correct": false, "explanation": "まめ：「ち」が「め」に変わる一モーラ差。"}, {"text": "前", "is_correct": false, "explanation": "まえ：「ち」が「え」に変わる一モーラ差。"}], "explanations": {"町": "まち。正解。", "松": "まつ：「ち」が「つ」に変わる一モーラ差。", "窓": "まど：「ち」が「ど」に変わる一モーラ差。", "豆": "まめ：「ち」が「め」に変わる一モーラ差。", "前": "まえ：「ち」が「え」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "町"}, "level_3": {"options": [{"text": "町", "is_correct": true, "explanation": "人が住む地域を守るという文意に合う。"}, {"text": "夢", "is_correct": false, "explanation": "意味：夢は防衛する対象ではない。"}, {"text": "歌", "is_correct": false, "explanation": "意味：歌を防衛するとは言わない。"}, {"text": "時間", "is_correct": false, "explanation": "連語：「時間を防衛する」は不自然。"}], "explanations": {"町": "人が住む地域を守るという文意に合う。", "夢": "意味：夢は防衛する対象ではない。", "歌": "意味：歌を防衛するとは言わない。", "時間": "連語：「時間を防衛する」は不自然。"}, "sentence_index": 0, "correct_answer": "町"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町を一本見に行きました。", "explanation": "助数詞の誤り：町は「本」で数えない。"}, {"text": "町で大きな駅があります。", "explanation": "助詞の混同：存在の場所は「町に」。"}, {"text": "昨日、町へ行っている。", "explanation": "活用・アスペクトの誤り：「昨日」なら「行った」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
