INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35031, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "作る", "is_correct": true, "explanation": "つくる。正解。"}, {"text": "尽くす", "is_correct": false, "explanation": "つくす：「る」が「す」に変わる一モーラ差。"}, {"text": "つくね", "is_correct": false, "explanation": "つくね：「る」が「ね」に変わる一モーラ差。"}, {"text": "付ける", "is_correct": false, "explanation": "つける：「く」が「け」に変わる一モーラ差。"}], "explanations": {"作る": "つくる。正解。", "尽くす": "つくす：「る」が「す」に変わる一モーラ差。", "つくね": "つくね：「る」が「ね」に変わる一モーラ差。", "付ける": "つける：「く」が「け」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "作る"}, "level_3": {"options": [{"text": "作っ", "is_correct": true, "explanation": "新聞を作り出す意味で自然。"}, {"text": "走っ", "is_correct": false, "explanation": "項構造：自動詞で「新聞を」をとれない。"}, {"text": "眠っ", "is_correct": false, "explanation": "項構造：自動詞で目的語をとれない。"}, {"text": "泣い", "is_correct": false, "explanation": "項構造：「新聞を泣く」とは言わない。"}], "explanations": {"作っ": "新聞を作り出す意味で自然。", "走っ": "項構造：自動詞で「新聞を」をとれない。", "眠っ": "項構造：自動詞で目的語をとれない。", "泣い": "項構造：「新聞を泣く」とは言わない。"}, "sentence_index": 6, "correct_answer": "作っ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カレーが作るのが好きです。", "explanation": "助詞の混同：目的語は「を」。"}, {"text": "カレーを一冊作りました。", "explanation": "助数詞の誤り：カレーは「冊」で数えない。"}, {"text": "カレーを作ってのが好きです。", "explanation": "活用の誤り：「の」の前は辞書形「作る」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35031, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "紙で飛行機が作ることができる。", "corrected_sentence": "紙で飛行機を作ることができる。", "error_description": "助詞の混同：「作る」の目的語は「を」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "作る", "is_correct": true, "explanation": "「こと」の前は辞書形。"}, {"text": "作った", "is_correct": false, "explanation": "「ことができる」は過去形に続かない。"}, {"text": "作って", "is_correct": false, "explanation": "て形は「こと」に続かない。"}, {"text": "作ろう", "is_correct": false, "explanation": "意向形は「こと」に続かない。"}], "correct_form": "作る", "base_form": "作る", "form_label": "活用", "sentence_index": 7, "explanations": {"作る": "「こと」の前は辞書形。", "作った": "「ことができる」は過去形に続かない。", "作って": "て形は「こと」に続かない。", "作ろう": "意向形は「こと」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35031, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「作る」の目的語を示す。"}, {"text": "の", "is_correct": false, "explanation": "「飛行機の作る」は名詞修飾になり非文。"}, {"text": "に", "is_correct": false, "explanation": "着点を示し、目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「作る」の目的語を示す。", "の": "「飛行機の作る」は名詞修飾になり非文。", "に": "着点を示し、目的語にならない。", "へ": "方向を示し、目的語にならない。"}, "error_tags": {"の": "other", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "作ることの反対で、対義語。"}, {"text": "集める", "is_correct": false, "explanation": "物を一か所にまとめる意味で、対義ではない。"}, {"text": "洗う", "is_correct": false, "explanation": "汚れを落とす意味で、対義ではない。"}, {"text": "買う", "is_correct": false, "explanation": "お金を払って手に入れる意味で、対義ではない。"}], "correct_answer": "壊す", "explanations": {"壊す": "作ることの反対で、対義語。", "集める": "物を一か所にまとめる意味で、対義ではない。", "洗う": "汚れを落とす意味で、対義ではない。", "買う": "お金を払って手に入れる意味で、対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37085, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "運ぶ", "is_correct": true, "explanation": "はこぶ。正解。"}, {"text": "ハコベ", "is_correct": false, "explanation": "はこべ：「ぶ」が「べ」に変わる一モーラ差。草の名前。"}, {"text": "箱", "is_correct": false, "explanation": "はこ：最後の「ぶ」がない一モーラ差。"}, {"text": "波高", "is_correct": false, "explanation": "はこう：「ぶ」が「う」に変わる一モーラ差。波の高さ。"}], "explanations": {"運ぶ": "はこぶ。正解。", "ハコベ": "はこべ：「ぶ」が「べ」に変わる一モーラ差。草の名前。", "箱": "はこ：最後の「ぶ」がない一モーラ差。", "波高": "はこう：「ぶ」が「う」に変わる一モーラ差。波の高さ。"}, "sentence_index": null, "correct_answer": "運ぶ"}, "level_3": {"options": [{"text": "運ぶ", "is_correct": true, "explanation": "「足を運ぶ」で出かけて行く意味。"}, {"text": "食べる", "is_correct": false, "explanation": "連語：足を食べるとは言わない。"}, {"text": "眠る", "is_correct": false, "explanation": "項構造：自動詞で目的語をとれない。"}, {"text": "書く", "is_correct": false, "explanation": "連語：足を書くは文意に合わない。"}], "explanations": {"運ぶ": "「足を運ぶ」で出かけて行く意味。", "食べる": "連語：足を食べるとは言わない。", "眠る": "項構造：自動詞で目的語をとれない。", "書く": "連語：足を書くは文意に合わない。"}, "sentence_index": 0, "correct_answer": "運ぶ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机が教室まで運んでください。", "explanation": "助詞の混同：目的語は「を」。"}, {"text": "机を一匹教室まで運んでください。", "explanation": "助数詞の誤り：机は「台」で数える。"}, {"text": "机を教室まで運ぶください。", "explanation": "活用の誤り：「ください」の前はて形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dbef9f-d21a-483e-a767-e6ed239a2667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
